{"command":"cat > nodeutil.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"reflect"
	"regexp"
	"strconv"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// helpers for yaml.Node values

func scalarNode(tag, value string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: tag, Value: value}
}
func stringNode(s string) *yaml.Node { return scalarNode("!!str", s) }
func intNode(i int64) *yaml.Node { return scalarNode("!!int", strconv.FormatInt(i, 10)) }
func uintNode(i uint64) *yaml.Node { return scalarNode("!!int", strconv.FormatUint(i, 10)) }
func floatNode(f float64) *yaml.Node {
	return scalarNode("!!float", formatFloat(f))
}
func boolNode(b bool) *yaml.Node {
	if b {
		return scalarNode("!!bool", "true")
	}
	return scalarNode("!!bool", "false")
}
func nullNode() *yaml.Node { return scalarNode("!!null", "null") }
func blankNullNode() *yaml.Node { return scalarNode("!!null", "") }
func seqNode(children ...*yaml.Node) *yaml.Node {
	return &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Content: children}
}
func mapNode(content ...*yaml.Node) *yaml.Node {
	return &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map", Content: content}
}

func formatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return ".inf"
	}
	if math.IsInf(f, -1) {
		return "-.inf"
	}
	if math.IsNaN(f) {
		return ".nan"
	}
	// match Go yaml / yq formatting for many cases
	s := strconv.FormatFloat(f, 'g', -1, 64)
	// FormatFloat gives e.g. 1e+06 ; yaml lib keeps? yq uses strconv.FormatFloat(..., 'f', -1, 64) in some places?
	// Probe later; keep g but ensure plain for moderate numbers is already plain.
	return s
}

// parse a scalar's numeric value according to tag/value
func nodeToFloat(n *yaml.Node) (float64, bool) {
	if n == nil {
		return 0, false
	}
	if n.Tag == "!!float" || n.Tag == "!!int" {
		v, ok := parseNumberValue(n.Value)
		if ok {
			if iv, ok2 := v.(int64); ok2 {
				return float64(iv), true
			}
			if fv, ok2 := v.(float64); ok2 {
				return fv, true
			}
			if uv, ok2 := v.(uint64); ok2 {
				return float64(uv), true
			}
		}
	}
	return 0, false
}

func parseNumberValue(s string) (interface{}, bool) {
	orig := s
	s = strings.ReplaceAll(s, "_", "")
	// yaml int formats
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		// reject leading zeros? 0123 in yaml1.2 is int 123 - ParseInt accepts; fine
		// But strings like "+12" ParseInt accepts (+)
		return i, true
	}
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		if i, err := strconv.ParseInt(s[2:], 16, 64); err == nil {
			return i, true
		}
		if u, err := strconv.ParseUint(s[2:], 16, 64); err == nil {
			return u, true
		}
	}
	if strings.HasPrefix(s, "-0x") || strings.HasPrefix(s, "-0X") {
		if i, err := strconv.ParseInt(s[3:], 16, 64); err == nil {
			return -i, true
		}
	}
	if strings.HasPrefix(s, "+0x") || strings.HasPrefix(s, "+0X") {
		if i, err := strconv.ParseInt(s[3:], 16, 64); err == nil {
			return i, true
		}
	}
	if strings.HasPrefix(s, "0o") || strings.HasPrefix(s, "0O") {
		if i, err := strconv.ParseInt(s[2:], 8, 64); err == nil {
			return i, true
		}
	}
	if strings.HasPrefix(s, "-0o") || strings.HasPrefix(s, "-0O") {
		if i, err := strconv.ParseInt(s[3:], 8, 64); err == nil {
			return -i, true
		}
	}
	if strings.HasPrefix(s, "0b") || strings.HasPrefix(s, "0B") {
		if i, err := strconv.ParseInt(s[2:], 2, 64); err == nil {
			return i, true
		}
	}
	if u, err := strconv.ParseUint(s, 10, 64); err == nil && !strings.HasPrefix(s, "-") {
		// large uint
		return u, true
	}
	ls := strings.ToLower(orig)
	switch ls {
	case ".inf", "+.inf":
		return math.Inf(1), true
	case "-.inf":
		return math.Inf(-1), true
	case ".nan":
		return math.NaN(), true
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		return f, true
	}
	return nil, false
}

func isIntTag(n *yaml.Node) bool {
	if n.Tag != "!!int" {
		return false
	}
	_, ok := parseNumberValue(n.Value)
	if !ok {
		return false
	}
	// check int-like (no . or e unless hex etc) - parseNumberValue returns int for those
	v, _ := parseNumberValue(n.Value)
	switch v.(type) {
	case int64, uint64:
		return true
	}
	return false
}

func nodeIntValue(n *yaml.Node) (int64, bool) {
	v, ok := parseNumberValue(n.Value)
	if !ok {
		return 0, false
	}
	switch t := v.(type) {
	case int64:
		return t, true
	case uint64:
		if t <= math.MaxInt64 {
			return int64(t), true
		}
		return 0, false
	case float64:
		return int64(t), true
	}
	return 0, false
}

// decode node to Go interface{} similar to yaml decode but preserving int/uint/float distinction and timestamps as time.Time? yq decode returns time for timestamps in comparisons.
// For generic conversions (json etc) we use node.Decode
func decodeNode(n *yaml.Node) (interface{}, error) {
	if n == nil {
		return nil, nil
	}
	switch n.Kind {
	case yaml.ScalarNode:
		return decodeScalar(n)
	case yaml.SequenceNode:
		out := make([]interface{}, 0, len(n.Content))
		for _, c := range n.Content {
			v, err := decodeNode(c)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case yaml.MappingNode:
		out := make(map[string]interface{})
		// but caller may need ordered; for generic use only
		for i := 0; i+1 < len(n.Content); i += 2 {
			kv, _ := decodeNode(n.Content[i])
			ks := fmt.Sprintf("%v", kv)
			v, err := decodeNode(n.Content[i+1])
			if err != nil {
				return nil, err
			}
			out[ks] = v
		}
		return out, nil
	case yaml.AliasNode:
		if n.Alias != nil {
			return decodeNode(n.Alias)
		}
		return nil, nil
	case yaml.DocumentNode:
		if len(n.Content) > 0 {
			return decodeNode(n.Content[0])
		}
		return nil, nil
	}
	return nil, nil
}

func decodeScalar(n *yaml.Node) (interface{}, error) {
	switch n.Tag {
	case "!!null", "~", "null", "":
		if n.Tag == "!!null" {
			return nil, nil
		}
		// fallthrough?
		return nil, nil
	case "!!bool":
		return parseBool(n.Value), nil
	case "!!int":
		v, ok := parseNumberValue(n.Value)
		if ok {
			return v, nil
		}
		return n.Value, nil
	case "!!float":
		v, ok := parseNumberValue(n.Value)
		if ok {
			switch t := v.(type) {
			case int64:
				return float64(t), nil
			case uint64:
				return float64(t), nil
			}
			return v, nil
		}
		return n.Value, nil
	case "!!timestamp":
		if t, err := parseTimestamp(n.Value); err == nil {
			return t, nil
		}
		return n.Value, nil
	case "!!str":
		return n.Value, nil
	default:
		return n.Value, nil
	}
}

func parseBool(s string) bool {
	switch strings.ToLower(s) {
	case "true", "yes", "on":
		// note yaml 1.2 yq: yes/no not bool when parsed from yaml (tagged !!str)
		// but if tag !!bool, value should be true/false
		return true
	default:
		return false
	}
}

var timestampFormats = []string{
	time.RFC3339Nano,
	"2006-01-02T15:04:05.999999999Z07:00",
	"2006-01-02t15:04:05.999999999Z07:00",
	"2006-01-02 15:04:05.999999999Z07:00",
	"2006-01-02T15:04:05",
	"2006-01-02 15:04:05",
	"2006-01-02",
	"2006-01-02T15:04:05Z07:00",
}

func parseTimestamp(s string) (time.Time, error) {
	for _, f := range timestampFormats {
		if t, err := time.Parse(f, s); err == nil {
			return t, nil
		}
	}
	// try yaml.v3 decode to time
	var t time.Time
	n := scalarNode("!!timestamp", s)
	if err := n.Decode(&t); err == nil && !t.IsZero() {
		return t, nil
	}
	return time.Time{}, fmt.Errorf("invalid timestamp")
}

func formatTimestamp(t time.Time) string {
	// yq prints timestamps in RFC3339 (seconds) when created via now etc.
	// If time has no monotonic and location UTC, format "2006-01-02T15:04:05Z"
	// If fractional seconds nonzero, include?
	if t.Nanosecond() == 0 {
		return t.Format(time.RFC3339)
	}
	return t.Format(time.RFC3339Nano)
}

func copyNode(n *yaml.Node) *yaml.Node {
	if n == nil {
		return nil
	}
	c := *n
	if n.Content != nil {
		c.Content = make([]*yaml.Node, len(n.Content))
		for i, ch := range n.Content {
			c.Content[i] = copyNode(ch)
		}
	}
	if n.Alias != nil {
		c.Alias = copyNode(n.Alias)
	}
	return &c
}

// copy that keeps alias pointing to original alias node (shallow alias)
// yq's Copy() may preserve anchor references within copied tree... complex.
// Use copyNodeWithAnchorMap for deep copies inside same document when needed:
func copyNodePreserve(n *yaml.Node) *yaml.Node {
	m := map[*yaml.Node]*yaml.Node{}
	return copyWithMap(n, m)
}
func copyWithMap(n *yaml.Node, m map[*yaml.Node]*yaml.Node) *yaml.Node {
	if n == nil {
		return nil
	}
	if v, ok := m[n]; ok {
		return v
	}
	c := *n
	m[n] = &c
	if n.Content != nil {
		c.Content = make([]*yaml.Node, len(n.Content))
		for i, ch := range n.Content {
			c.Content[i] = copyWithMap(ch, m)
		}
	}
	if n.Alias != nil {
		// alias should point to copied target if target was in copied subtree, otherwise original
		if v, ok := m[n.Alias]; ok {
			c.Alias = v
		} else {
			c.Alias = n.Alias
		}
	}
	return &c
}

// value equality for Go decoded scalars (used in ==)
func valuesEqual(a, b interface{}) bool {
	return reflect.DeepEqual(normalizeNum(a), normalizeNum(b))
}
func normalizeNum(v interface{}) interface{} {
	switch t := v.(type) {
	case int:
		return int64(t)
	case int32:
		return int64(t)
	case uint64:
		// keep
		return t
	}
	return v
}

func nodeIsNull(n *yaml.Node) bool {
	return n != nil && n.Tag == "!!null"
}
func nodeIsBoolFalse(n *yaml.Node) bool {
	return n != nil && n.Tag == "!!bool" && !parseBool(n.Value)
}
func nodeIsFalsey(n *yaml.Node) bool {
	return nodeIsNull(n) || nodeIsBoolFalse(n)
}

// convert path element (from traversal) to node for path operator output
func pathElemNode(e interface{}) *yaml.Node {
	switch t := e.(type) {
	case string:
		return stringNode(t)
	case int:
		return intNode(int64(t))
	case int64:
		return intNode(t)
	case float64:
		return floatNode(t)
	case bool:
		return boolNode(t)
	case nil:
		return nullNode()
	default:
		// could be node?
		if n, ok := e.(*yaml.Node); ok {
			return copyNode(n)
		}
		return stringNode(fmt.Sprintf("%v", t))
	}
}

// key string representation of a map key node
func keyString(n *yaml.Node) string {
	// for matching traversals, use decoded string form
	if n.Kind == yaml.ScalarNode {
		// For !!str etc, value directly; for numbers/bools, value string is also used in matching? yq matches keys by decoded value.
		return n.Value
	}
	// complex key: use yaml representation trimmed
	b, _ := yaml.Marshal(n)
	return strings.TrimSpace(string(b))
}

// Compare key node to desired path element (string or int etc)
func keyMatches(key *yaml.Node, want interface{}) bool {
	// Alias keys?
	k := key
	if k.Kind == yaml.AliasNode && k.Alias != nil {
		k = k.Alias
	}
	switch w := want.(type) {
	case string:
		// yq: matching is done on string value of key if key is scalar?
		// But numeric key 1 vs string "1": probe shows they do match? We will test later.
		// For now: compare raw value
		if k.Kind == yaml.ScalarNode {
			return k.Value == w
		}
		return false
	case int:
		if k.Kind == yaml.ScalarNode {
			if iv, ok := nodeIntValue(k); ok && k.Tag == "!!int" {
				return int(iv) == w
			}
			return k.Value == strconv.Itoa(w)
		}
	case int64:
		if k.Kind == yaml.ScalarNode {
			if iv, ok := nodeIntValue(k); ok {
				return iv == w
			}
			return k.Value == strconv.FormatInt(w, 10)
		}
	case float64:
		if f, ok := nodeToFloat(k); ok {
			return f == w
		}
	case bool:
		return k.Tag == "!!bool" && parseBool(k.Value) == w
	case *yaml.Node:
		// compare decoded
		a, _ := decodeScalarSmart(k)
		b, _ := decodeScalarSmart(w)
		return valuesEqual(a, b)
	}
	return false
}

func decodeScalarSmart(n *yaml.Node) (interface{}, error) {
	if n.Kind == yaml.ScalarNode {
		return decodeScalar(n)
	}
	return decodeNode(n)
}

// glob match for path keys: * and ? wildcards (yq uses doublestar? path.Match style)
// It also supports ** ? Use simple matching converting glob to regexp, where * matches any sequence (including /? keys have no separators)
func globMatch(pattern, s string) bool {
	if !strings.ContainsAny(pattern, "*?") {
		return pattern == s
	}
	// build regex
	var b strings.Builder
	b.WriteString("^")
	for _, r := range pattern {
		switch r {
		case '*':
			b.WriteString(".*")
		case '?':
			b.WriteString(".")
		default:
			b.WriteString(regexp.QuoteMeta(string(r)))
		}
	}
	b.WriteString("$")
	re, err := regexp.Compile(b.String())
	if err != nil {
		return false
	}
	return re.MatchString(s)
}

func kindString(n *yaml.Node) string {
	switch n.Kind {
	case yaml.ScalarNode:
		return "scalar"
	case yaml.SequenceNode:
		return "seq"
	case yaml.MappingNode:
		return "map"
	case yaml.AliasNode:
		return "alias"
	case yaml.DocumentNode:
		return "doc"
	}
	return ""
}

// style string as yq represents
func styleString(n *yaml.Node) string {
	s := n.Style
	// FlowStyle is a bit combined with others? In yaml.v3, Style is bitmask
	if s&yaml.FlowStyle != 0 {
		return "flow"
	}
	switch s {
	case yaml.DoubleQuotedStyle:
		return "double"
	case yaml.SingleQuotedStyle:
		return "single"
	case yaml.LiteralStyle:
		return "literal"
	case yaml.FoldedStyle:
		return "folded"
	case yaml.FlowStyle:
		return "flow"
	case 0:
		return ""
	}
	// TaggedStyle etc handled elsewhere
	if s&yaml.TaggedStyle != 0 {
		// yq returns?? probe later
	}
	return ""
}

func applyStyleString(n *yaml.Node, style string) {
	switch style {
	case "":
		n.Style = 0
	case "double":
		n.Style = yaml.DoubleQuotedStyle
	case "single":
		n.Style = yaml.SingleQuotedStyle
	case "literal":
		n.Style = yaml.LiteralStyle
	case "folded":
		n.Style = yaml.FoldedStyle
	case "flow":
		n.Style = yaml.FlowStyle
	default:
		// unknown: yq may error elsewhere
	}
}

func stringValueOfNode(n *yaml.Node) string {
	if n == nil {
		return ""
	}
	if n.Kind == yaml.ScalarNode {
		return n.Value
	}
	return ""
}

func nodeTagOrDefault(n *yaml.Node) string {
	if n.Tag != "" {
		return n.Tag
	}
	switch n.Kind {
	case yaml.MappingNode:
		return "!!map"
	case yaml.SequenceNode:
		return "!!seq"
	case yaml.ScalarNode:
		return "!!str"
	case yaml.AliasNode:
		if n.Alias != nil {
			return nodeTagOrDefault(n.Alias)
		}
		return "!!null"
	}
	return ""
}

// check if string is a valid identifier-ish for creating map keys etc.
func isNumberString(s string) bool {
	_, ok := parseNumberValue(s)
	return ok
}

// create node from Go value (interface) preserving ordered maps when value is *orderedMap etc.
func valueToNode(v interface{}) *yaml.Node {
	switch t := v.(type) {
	case nil:
		return nullNode()
	case string:
		return stringNode(t)
	case bool:
		return boolNode(t)
	case int:
		return intNode(int64(t))
	case int64:
		return intNode(t)
	case int32:
		return intNode(int64(t))
	case uint64:
		return uintNode(t)
	case uint:
		return uintNode(uint64(t))
	case float64:
		return floatNode(t)
	case float32:
		return floatNode(float64(t))
	case time.Time:
		return scalarNode("!!timestamp", formatTimestamp(t))
	case []interface{}:
		n := seqNode()
		for _, e := range t {
			n.Content = append(n.Content, valueToNode(e))
		}
		return n
	case map[string]interface{}:
		// unordered - callers should avoid
		n := mapNode()
		for k, val := range t {
			n.Content = append(n.Content, stringNode(k), valueToNode(val))
		}
		return n
	case *yaml.Node:
		return t
	default:
		// use yaml marshal via Node encode
		n := &yaml.Node{}
		if err := n.Encode(v); err == nil && n.Kind != 0 {
			// Encode creates Document? Actually Node.Encode sets node to representation.
			return n
		}
		return stringNode(fmt.Sprintf("%v", t))
	}
}
