// parse a scalar's numeric value according to tag/value
func nodeToFloat(n *yaml.Node) (float64, bool) {
	if n == nil {
		return 0, false
	}
	if n.Tag == "!!float" || n.Tag == "!!int" {
		v, ok := parseNumberValue(n.Value)
		if ok {
			if iv, ok2 := v.(int64); ok2 {
				return float64(iv), true
			}
			if fv, ok2 := v.(float64); ok2 {
				return fv, true
			}
			if uv, ok2 := v.(uint64); ok2 {
				return float64(uv), true
			}
		}
	}
	return 0, false
