	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		// reject leading zeros? 0123 in yaml1.2 is int 123 - ParseInt accepts; fine
		// But strings like "+12" ParseInt accepts (+)
		return i, true
	}
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		if i, err := strconv.ParseInt(s[2:], 16, 64); err == nil {
			return i, true
		}
		if u, err := strconv.ParseUint(s[2:], 16, 64); err == nil {
			return u, true
		}
	}
	if strings.HasPrefix(s, "-0x") || strings.HasPrefix(s, "-0X") {
		if i, err := strconv.ParseInt(s[3:], 16, 64); err == nil {
			return -i, true
		}
	}
	if strings.HasPrefix(s, "+0x") || strings.HasPrefix(s, "+0X") {
		if i, err := strconv.ParseInt(s[3:], 16, 64); err == nil {
			return i, true
		}
	}
	if strings.HasPrefix(s, "0o") || strings.HasPrefix(s, "0O") {
		if i, err := strconv.ParseInt(s[2:], 8, 64); err == nil {
