				return token{kind: tFormat, text: f, line: startLine, col: startCol, pos: startPos}, nil
			}
		}
		return token{}, l.errorAt(startPos, startLine, startCol)
	}

	// ~ null literal
	if c == '~' {
		l.advance(1)
		return token{kind: tNullTilde, text: "~", line: startLine, col: startCol, pos: startPos}, nil
	}

	// Symbols - longest first
	// multiply with flags: * followed by [+?dn]+ (but not *=)
	if c == '*' && len(rest) > 1 && rest[1] != '=' {
		j := 1
		for j < len(rest) && (rest[j] == '+' || rest[j] == '?' || rest[j] == 'd' || rest[j] == 'n') {
