	for _, name := range operatorNamesSorted {
		if strings.HasPrefix(rest, name) {
			// Note: no word-boundary requirement to mimic original.
			l.advanceStr(name)
			return token{kind: tName, text: name, line: startLine, col: startCol, pos: startPos}, nil
		}
	}

	return token{}, l.errorAt(startPos, startLine, startCol)
}

func isHex(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}
func isVarChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

func lexAll(src string) ([]token, error) {
	l := newLexer(src)
	var toks []token
	for {
		t, err := l.next()
		if err != nil {
			return nil, err
		}
		toks = append(toks, t)
		if t.kind == tEOF {
			break
		}
	}
	return toks, nil
}
