package main

import (
	"fmt"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type Cand struct {
	Node    *yaml.Node
	Parent  *Cand
	Key     *yaml.Node // key node in parent map, or node itself if IsKey
	IsKey   bool
	Path    []interface{}
	DocIdx  int
	FileIdx int
	Filename string
	Leading string // leading content for document root
	// Mark for split_doc: printed as new document even if same docIdx? Use DocIdx override
	IsSplitDoc bool
}

func (c *Cand) cloneWith(node *yaml.Node) *Cand {
	if c == nil {
		return &Cand{Node: node}
	}
	n := *c
	n.Node = node
	n.Leading = "" // leading only for exact root candidate? but arithmetic on root? ... root op returns original.
	// Actually for candidates derived from root via transformation (e.g. tag), leading should not print.
	// Keep leading only if node is same object?
	if node == c.Node {
		n.Leading = c.Leading
	}
	return &n
}

func (c *Cand) rootCand() *Cand {
	cur := c
	for cur != nil && cur.Parent != nil {
		cur = cur.Parent
	}
	return cur
}

func (c *Cand) child(node *yaml.Node, key *yaml.Node, pathElem interface{}, isKey bool) *Cand {
	p := make([]interface{}, len(c.Path)+1)
	copy(p, c.Path)
	p[len(c.Path)] = pathElem
	return &Cand{Node: node, Parent: c, Key: key, IsKey: isKey, Path: p, DocIdx: c.DocIdx, FileIdx: c.FileIdx, Filename: c.Filename}
}

// dedupe by pointer identity (yq candidate list semantics)
func addCand(list []*Cand, c *Cand) []*Cand {
	for _, e := range list {
		if e == c {
			return list
		}
	}
	return append(list, c)
}
func addCands(list []*Cand, cs []*Cand) []*Cand {
	for _, c := range cs {
		list = addCand(list, c)
	}
	return list
}

type Ctx struct {
	parent   *Ctx
	vars     map[string][]*Cand
	noCreate bool
	dtf      string
	// for split exp $index etc, bindings are in vars
}

func newCtx() *Ctx { return &Ctx{vars: map[string][]*Cand{}} }
func (ctx *Ctx) childCtx() *Ctx { return &Ctx{parent: ctx, vars: map[string][]*Cand{}, noCreate: ctx.noCreate, dtf: ctx.dtf} }
func (ctx *Ctx) withNoCreate() *Ctx {
	c := ctx.childCtx()
	c.noCreate = true
	return c
}
func (ctx *Ctx) withCreate() *Ctx {
	c := ctx.childCtx()
	c.noCreate = false
	return c
}
func (ctx *Ctx) getVar(name string) ([]*Cand, bool) {
	for cur := ctx; cur != nil; cur = cur.parent {
		if v, ok := cur.vars[name]; ok {
			return v, true
		}
	}
	return nil, false
}
func (ctx *Ctx) setVar(name string, v []*Cand) { ctx.vars[name] = v }

// Path segment
type pathSeg struct {
	kind     string // "key", "index", "splat", "slice", "expr", "recurse", "recurseAll"
	key      string
	index    int
	hasIndex bool
	optional bool
	slice    *[2]*int // pointers nil = omitted? Use aux fields below
	sliceLo  *int
	sliceHi  *int
	expr     Expr
	// for string index from bracket string literal etc, key used
	// exprIndex indicates brackets contains expression evaluated dynamically
}

func (seg pathSeg) String() string {
	return seg.key
}

// traverse a single segment from one candidate
func traverseSeg(ctx *Ctx, c *Cand, seg pathSeg) ([]*Cand, error) {
	results, err := traverseSegInner(ctx, c, seg)
	if err != nil && seg.optional {
		return nil, nil
	}
	return results, err
}

func traverseSegInner(ctx *Ctx, c *Cand, seg pathSeg) ([]*Cand, error) {
	if seg.kind == "recurse" {
		return recurseCands(c, false), nil
	}
	if seg.kind == "recurseAll" {
		return recurseCands(c, true), nil
	}
	node := c.Node
	// follow alias for container traversal
	effCand := c
	if node.Kind == yaml.AliasNode && node.Alias != nil {
		effCand = c.cloneWith(node.Alias)
		// preserve parent etc from c (cloneWith keeps)
		effCand.Parent = c.Parent
		effCand.Path = c.Path
		effCand.Key = c.Key
		node = node.Alias
	}
	if seg.kind == "expr" {
		return traverseExprIndex(ctx, effCand, seg)
	}
	if seg.kind == "slice" {
		return traverseSlice(ctx, effCand, seg)
	}
	if seg.kind == "splat" {
		return splatCand(effCand), nil
	}
	// key or index segment
	switch node.Kind {
	case yaml.MappingNode:
		return traverseMap(ctx, effCand, seg)
	case yaml.SequenceNode:
		return traverseSeq(ctx, effCand, seg)
	case yaml.ScalarNode:
