				node.Kind = yaml.SequenceNode
				node.Tag = "!!seq"
				node.Value = ""
				node.Content = nil
				node.Style = 0
				return traverseSeq(ctx, effCand, seg)
			}
			node.Kind = yaml.MappingNode
			node.Tag = "!!map"
			node.Value = ""
			node.Content = nil
			node.Style = 0
			return traverseMap(ctx, effCand, seg)
		}
		return nil, nil
	case yaml.DocumentNode:
		if len(node.Content) > 0 {
			inner := effCand.cloneWith(node.Content[0])
			return traverseSegInner(ctx, inner, seg)
		}
		return nil, nil
	}
	return nil, nil
}

func isIndexSeg(seg pathSeg) bool {
	if seg.kind == "index" {
		return true
	}
	// bracket index with numeric key handled as kind index
	return false
}

func segPathElem(seg pathSeg) interface{} {
	if seg.kind == "index" {
		return seg.index
	}
	return seg.key
}

func traverseMap(ctx *Ctx, c *Cand, seg pathSeg) ([]*Cand, error) {
	node := c.Node
	// Determine desired key
	if seg.kind == "index" {
		// indexing map with int: key is int node match
		want := seg.index
		for i := 0; i+1 < len(node.Content); i += 2 {
			k := node.Content[i]
			if keyMatches(k, want) {
