			return []*Cand{nc}, nil
		}
		k := intNode(int64(want))
		v := nullNode()
		node.Content = append(node.Content, k, v)
		return []*Cand{c.child(v, k, want, false)}, nil
	}
	keyStr := seg.key
	// glob?
	if strings.ContainsAny(keyStr, "*?") {
		var out []*Cand
		for i := 0; i+1 < len(node.Content); i += 2 {
			k := node.Content[i]
			ks := keyString(k)
			if globMatch(keyStr, ks) {
				out = addCand(out, c.child(node.Content[i+1], k, pathElemFromKey(k), false))
			}
		}
		if len(out) == 0 {
			// glob missing: yq returns null? Probe showed .foo* with matches. For no match, return null detached? We'll return null candidate with path = keyStr? Test later via differential.
			// But many usages: .missing* in select should be empty. Hmm.
			// Let's check behavior later; for now return empty (to be tuned)
			return nil, nil
		}
		return out, nil
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		k := node.Content[i]
		if keyMatches(k, keyStr) {
			return []*Cand{c.child(node.Content[i+1], k, pathElemFromKey(k), false)}, nil
		}
	}
	// missing
	if ctx.noCreate {
		k := stringNode(keyStr)
		nc := c.child(nullNode(), k, keyStr, false)
		return []*Cand{nc}, nil
	}
	k := stringNode(keyStr)
	// inherit style from sibling keys? If existing keys are quoted, yq may use same style? Keep 0.
	v := nullNode()
	node.Content = append(node.Content, k, v)
	return []*Cand{c.child(v, k, keyStr, false)}, nil
