func traverseSeq(ctx *Ctx, c *Cand, seg pathSeg) ([]*Cand, error) {
	node := c.Node
	var idx int
	if seg.kind == "index" {
		idx = seg.index
	} else {
		// key segment: try parse int (glob splat handled before)
		ks := seg.key
		if strings.ContainsAny(ks, "*?") {
			// glob match indices as strings
			var out []*Cand
			for i, ch := range node.Content {
				if globMatch(ks, strconv.Itoa(i)) {
					out = append(out, c.child(ch, nil, i, false))
				}
			}
			return out, nil
		}
		iv, err := strconv.ParseInt(ks, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("cannot index array with '%s' (%s)", ks, err.Error())
		}
		idx = int(iv)
	}
	origIdx := idx
	if idx < 0 {
		idx = len(node.Content) + idx
		if idx < 0 {
			return nil, fmt.Errorf("index [%d] out of range, array size is %d", origIdx, len(node.Content))
		}
		return []*Cand{c.child(node.Content[idx], nil, idx, false)}, nil
	}
	if idx < len(node.Content) {
		return []*Cand{c.child(node.Content[idx], nil, idx, false)}, nil
	}
	// out of range positive
	if ctx.noCreate {
		nc := c.child(nullNode(), nil, idx, false)
		return []*Cand{nc}, nil
	}
	for len(node.Content) <= idx {
		node.Content = append(node.Content, nullNode())
	}
	return []*Cand{c.child(node.Content[idx], nil, idx, false)}, nil
