func splatCand(c *Cand) []*Cand {
	node := c.Node
	if node.Kind == yaml.AliasNode && node.Alias != nil {
		node = node.Alias
		c = c.cloneWith(node)
	}
	switch node.Kind {
	case yaml.MappingNode:
		var out []*Cand
		for i := 0; i+1 < len(node.Content); i += 2 {
			out = append(out, c.child(node.Content[i+1], node.Content[i], pathElemFromKey(node.Content[i]), false))
		}
		return out
	case yaml.SequenceNode:
		var out []*Cand
		for i, ch := range node.Content {
			out = append(out, c.child(ch, nil, i, false))
		}
		return out
	default:
		return nil
	}
}

func recurseCands(c *Cand, includeKeys bool) []*Cand {
	var out []*Cand
	var walk func(*Cand)
	walk = func(cur *Cand) {
		out = addCand(out, cur)
		node := cur.Node
		if node.Kind == yaml.AliasNode && node.Alias != nil {
			// do not recurse into alias? yq .. includes alias target content? keep simple: treat alias target children as children of alias candidate clone
			eff := cur.cloneWith(node.Alias)
			// walk children of eff but not eff itself again
			for _, ch := range childCands(eff, includeKeys) {
				walk(ch)
			}
			return
		}
		for _, ch := range childCands(cur, includeKeys) {
			walk(ch)
		}
	}
	walk(c)
	return out
}

func childCands(c *Cand, includeKeys bool) []*Cand {
	node := c.Node
	var out []*Cand
	switch node.Kind {
	case yaml.MappingNode:
		for i := 0; i+1 < len(node.Content); i += 2 {
			k := node.Content[i]
			v := node.Content[i+1]
			if includeKeys {
				kc := c.child(k, k, pathElemFromKey(k), true)
				out = append(out, kc)
			}
			out = append(out, c.child(v, k, pathElemFromKey(k), false))
		}
	case yaml.SequenceNode:
		for i, ch := range node.Content {
			out = append(out, c.child(ch, nil, i, false))
		}
	case yaml.AliasNode:
		if node.Alias != nil {
			eff := c.cloneWith(node.Alias)
			return childCands(eff, includeKeys)
		}
	}
	return out
}

func pathElemFromKey(k *yaml.Node) interface{} {
	if k.Kind == yaml.ScalarNode {
		v, err := decodeScalar(k)
		if err == nil {
			switch t := v.(type) {
			case string:
				return t
			case int64:
				// Path outputs int for int keys? Need check: map with int key 1: path element shows 1 (int) - yaml encode same visually.
				return t
			case uint64:
				return t
			case float64:
				return t
			case bool:
				return t
			case nil:
				return nil
			}
		}
		return k.Value
	}
	// complex key: return node itself as path elem
	return k
}

func traverseSlice(ctx *Ctx, c *Cand, seg pathSeg) ([]*Cand, error) {
	node := c.Node
	if node.Kind != yaml.SequenceNode {
		// On string? yq slice of string? probe later
		if node.Kind == yaml.ScalarNode && node.Tag == "!!str" {
			// slice string by runes?
			s := node.Value
			runes := []rune(s)
			lo, hi := sliceBounds(seg, len(runes))
			if lo < 0 { lo = 0 }
			if hi > len(runes) { hi = len(runes) }
			if lo > hi { lo = hi }
			nc := c.cloneWith(stringNode(string(runes[lo:hi])))
			return []*Cand{nc}, nil
		}
		// For maps/scalars, empty?
		return nil, nil
	}
	lo, hi := sliceBounds(seg, len(node.Content))
	if lo < 0 { lo = 0 }
	if hi > len(node.Content) { hi = len(node.Content) }
	if lo > hi { lo = hi }
	newSeq := seqNode()
	// Preserve style of original?
	newSeq.Style = node.Style
	for _, ch := range node.Content[lo:hi] {
		newSeq.Content = append(newSeq.Content, ch)
	}
	// Result candidate inherits path of the sequence (c) - as if new array replaces it for further traversal indices rebase.
	// But children traversed from result should have indices 0..
	// We use c as parent? cloneWith keeps Path of c, parent c.Parent
	res := c.cloneWith(newSeq)
	// To ensure subsequent child indices are based on new seq, child() on res uses res.Path - good.
	// However original nodes are shared (not copies) as slice is view - yq behaviour maybe.
	return []*Cand{res}, nil
}

func sliceBounds(seg pathSeg, n int) (int, int) {
	lo := 0
	hi := n
	if seg.sliceLo != nil {
		lo = *seg.sliceLo
		if lo < 0 {
			lo = n + lo
		}
	}
	if seg.sliceHi != nil {
		hi = *seg.sliceHi
		if hi < 0 {
			hi = n + hi
		}
	}
	return lo, hi
}

func traverseExprIndex(ctx *Ctx, c *Cand, seg pathSeg) ([]*Cand, error) {
	// Evaluate expr against c as single input
	vals, err := seg.expr.Eval(ctx, []*Cand{c})
	if err != nil {
		return nil, err
	}
	if len(vals) == 0 {
		// No index values: explode all children (observed .[$x] unbound)
		return splatCand(c), nil
	}
	var out []*Cand
	for _, v := range vals {
		// v may be same as child etc. Convert its node to segment.
		subSeg, err := segFromValue(v.Node, seg.optional)
		if err != nil {
			if seg.optional { continue }
			return nil, err
		}
		res, err := traverseSeg(ctx, c, subSeg)
		if err != nil {
			return nil, err
		}
		out = addCands(out, res)
	}
	return out, nil
}

func segFromValue(n *yaml.Node, optional bool) (pathSeg, error) {
	if n.Kind == yaml.ScalarNode {
		switch n.Tag {
		case "!!int":
			iv, ok := nodeIntValue(n)
			if ok {
				return pathSeg{kind: "index", index: int(iv), hasIndex: true, optional: optional}, nil
			}
			return pathSeg{kind: "key", key: n.Value, optional: optional}, nil
		default:
			// string / bool etc: key as raw value (but bool key matching handled by keyMatches string vs bool? keyMatches with string compares Value, bool key Value is "true" so ok)
			return pathSeg{kind: "key", key: n.Value, optional: optional}, nil
		}
	}
	// non-scalar index: use its string representation? return error?
	return pathSeg{}, fmt.Errorf("cannot index with %s", nodeTagOrDefault(n))
}

// Setting a value at a candidate location: replace node content in-place if candidate is attached to parent,
// or mutate its node (if root/detached) by copying fields.
// Returns candidate pointing to (possibly same) node containing new value.
func assignToCand(c *Cand, newNode *yaml.Node) *Cand {
	// If c.IsKey: assigning to a key node: replace key node in parent map
	// The newNode should become the key - replace fields of c.Node (key node object) with newNode fields to keep map pointer.
	replaceNodeContents(c.Node, newNode)
	return c
}

func replaceNodeContents(dst *yaml.Node, src *yaml.Node) {
	if dst == src {
		return
	}
	// Preserve dst identity
	*dst = *src
}

