func (p *parser) parsePrimary() (Expr, error) {
	tok := p.peek()
	switch tok.kind {
	case tEOF:
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	case tPath:
		segs, err := p.parsePathSegmentsFromToken()
		if err != nil { return nil, err }
		return &PathExpr{segs: segs}, nil
	case tRecurse:
		segs, err := p.parsePathSegmentsFromToken()
		if err != nil { return nil, err }
		return &PathExpr{segs: segs}, nil
	case tNumber:
		p.nextTok()
		n, err := numberLiteralNode(tok.text)
		if err != nil { return nil, err }
		return &LiteralExpr{node: n}, nil
	case tString:
		p.nextTok()
		return parseStringExpr(tok.text)
	case tVar:
		p.nextTok()
		return &VarExpr{name: tok.text}, nil
	case tEnv:
		p.nextTok()
		return &EnvExpr{kind: tok.text, name: tok.aux}, nil
	case tFormat:
		p.nextTok()
		return &FormatExpr{name: tok.text}, nil
	case tNullTilde:
		p.nextTok()
		return &LiteralExpr{node: scalarNode("!!null","~")}, nil
	case tName:
		name := tok.text
		if name=="true" || name=="false" {
			p.nextTok(); return &LiteralExpr{node: boolNode(name=="true")}, nil
		}
		if name=="null" {
			p.nextTok(); return &LiteralExpr{node: nullNode()}, nil
		}
		if name=="and" || name=="or" {
			// binary op missing LHS
			return nil, fmt.Errorf("'%s' expects 2 args but there is 0", name)
		}
		if name=="ireduce" {
			return nil, fmt.Errorf("'ireduce' expects 2 args but there is 0")
		}
		if name=="ref" {
			return nil, fmt.Errorf("'ref' expects 2 args but there is 0")
		}
		if name=="as" {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		// function / operator name
		p.nextTok()
		// Optional parentheses argument - but be careful: `(...)` after a zero-arg op that is a separate parenthesized expr juxtaposed gives bad expression in original for some.
		// Names that require arg must have parens; if missing, error expects 1 arg... except first/eval weird (bare first/eval returns something)
		// We emulate: if next '(' parse arg; else if requiring arg -> error. For first/eval, allow bare (hasParens false) and eval handles.
		if p.peek().kind==tSymbol && p.peek().text=="(" {
			// parse parentheses content as Union (which includes block ;)
			p.nextTok()
			if p.peek().kind==tSymbol && p.peek().text==")" {
				p.nextTok()
				// empty parens
				if funcsRequiringArg[name] {
					// e.g. select() ? original?
					return &FuncExpr{name:name, arg: &BlockExpr{exprs:nil}, hasParens:true}, nil
				}
				return &FuncExpr{name:name, hasParens:true}, nil
			}
			arg, err := p.parseUnion()
			if err != nil { return nil, err }
			if err := p.expectSymbol(")"); err != nil { return nil, err }
			// special bad-expression cases: tojson/toyaml/flatten with block arg
			if _, isBlock := arg.(*BlockExpr); isBlock {
				if name=="tojson" || name=="to_json" || name=="toyaml" || name=="to_yaml" || name=="flatten" || name=="toxml" || name=="to_xml" {
					return nil, fmt.Errorf("bad expression, please check expression syntax")
				}
			}
			return &FuncExpr{name:name, arg:arg, hasParens:true}, nil
		}
		// no parens
		if funcsRequiringArg[name] {
			if name=="first" || name=="eval" {
				// allow bare: will act as identity-ish in eval (first bare behaviour approximated there)
				return &FuncExpr{name:name, hasParens:false}, nil
			}
			return nil, fmt.Errorf("'%s' expects 1 arg but received none", name)
		}
		return &FuncExpr{name:name, hasParens:false}, nil
	case tSymbol:
		switch tok.text {
		case "(":
			p.nextTok()
			if p.peek().kind==tSymbol && p.peek().text==")" {
				p.nextTok()
				// empty parens () - original? treat as block empty
				return &BlockExpr{}, nil
			}
			e, err := p.parseUnion()
			if err != nil { return nil, err }
			if err := p.expectSymbol(")"); err != nil { return nil, err }
			return e, nil
		case "[":
			// collect array or empty seq literal or slice?? In primary position, [ is collect
			p.nextTok()
			if p.peek().kind==tSymbol && p.peek().text=="]" {
				p.nextTok()
				// [] as primary: this is explode operator when in pipe e.g. ".a | .[]" is path, but standalone "[]"
				// Original: "[]" alone as expression returns splat of input? Or empty array literal? Need check: test later.
				// We'll represent as Path with splat segment (explode). However "[1,2] | . + [3]" second [3] is collect, and "[]" used as literal in comparisons ".a == []" likely empty array.
