	// Our binary parsing will attempt parse RHS primary starting with '=', yielding bad expression - but original says '/' expects 2 args...
	// Handle detection: if peek is '/' or '%' and peekAt1 is '='
	if p.peek().kind == tSymbol && (p.peek().text=="/" || p.peek().text=="%") && p.peekAt(1).kind==tSymbol && p.peekAt(1).text=="=" {
		op := p.peek().text
		return nil, fmt.Errorf("'%s' expects 2 args but there is 1", op)
	}
	return left, nil
}

func (p *parser) parseAlternative() (Expr, error) {
	left, err := p.parseBoolean()
	if err != nil { return nil, err }
	if p.peek().kind == tSymbol && p.peek().text == "//" {
		p.nextTok()
		right, err := p.parseAlternative()
		if err != nil { return nil, err }
		return &BinaryExpr{op: "//", left: left, right: right}, nil
	}
	return left, nil
}

func (p *parser) parseBoolean() (Expr, error) {
	left, err := p.parseComparison()
	if err != nil { return nil, err }
	if p.peek().kind == tName && (p.peek().text=="and" || p.peek().text=="or") {
		op := p.nextTok().text
		right, err := p.parseBoolean()
		if err != nil { return nil, err }
		return &BinaryExpr{op: op, left: left, right: right}, nil
	}
	return left, nil
}

func (p *parser) parseComparison() (Expr, error) {
	left, err := p.parseAdditive()
	if err != nil { return nil, err }
	if p.peek().kind == tSymbol {
		switch p.peek().text {
		case "==","!=","<=",">=","<",">":
			op := p.nextTok().text
			// Check for "===" which lexer splits as == then = ; original error '==' expects 2 args but there is 1
			if p.peek().kind==tSymbol && p.peek().text=="=" {
				return nil, fmt.Errorf("'%s' expects 2 args but there is 1", op)
			}
			right, err := p.parseComparison()
			if err != nil { return nil, err }
			return &BinaryExpr{op: op, left: left, right: right}, nil
		}
	}
	// ref infix?
	if p.peek().kind == tName && p.peek().text=="ref" {
		p.nextTok()
		right, err := p.parseComparison()
		if err != nil { return nil, err }
		return &BinaryExpr{op: "ref", left: left, right: right}, nil
	}
	return left, nil
}

func (p *parser) parseAdditive() (Expr, error) {
	left, err := p.parseMultiplicative()
	if err != nil { return nil, err }
	if p.peek().kind == tSymbol && (p.peek().text=="+" || p.peek().text=="-") {
		op := p.nextTok().text
		right, err := p.parseAdditive()
		if err != nil { return nil, err }
		return &BinaryExpr{op: op, left: left, right: right}, nil
	}
	return left, nil
}

func (p *parser) parseMultiplicative() (Expr, error) {
	left, err := p.parsePostfix()
	if err != nil { return nil, err }
	if p.peek().kind == tSymbol {
		txt := p.peek().text
		if txt=="*" || txt=="/" || txt=="%" || (strings.HasPrefix(txt,"*") && len(txt)>1) {
			// */% compound assign handled earlier as *= token, not here
			op := p.nextTok().text
			// check /= %= **= cases:
			if p.peek().kind==tSymbol && p.peek().text=="=" {
				return nil, fmt.Errorf("'%s' expects 2 args but there is 1", op)
			}
			if op=="*" && p.peek().kind==tSymbol && p.peek().text=="*" {
				return nil, fmt.Errorf("'*' expects 2 args but there is 1")
			}
			right, err := p.parseMultiplicative()
			if err != nil { return nil, err }
			return &BinaryExpr{op: op, left: left, right: right}, nil
		}
	}
	return left, nil
}

// postfix: traversal path / brackets applied to a primary, also primary may itself be a path
func (p *parser) parsePostfix() (Expr, error) {
	e, err := p.parsePrimary()
	if err != nil { return nil, err }
	for {
		// path token following
		if p.peek().kind == tPath || p.peek().kind == tRecurse {
			segs, err := p.parsePathSegmentsFromToken()
			if err != nil { return nil, err }
			// apply as traverse; but if e is already PathExpr with no base, merge segs
			if pe, ok := e.(*PathExpr); ok {
				pe.segs = append(pe.segs, segs...)
				e = pe
			} else {
				e = &TraverseExpr{base: e, segs: segs}
			}
			continue
		}
		if p.peek().kind == tSymbol && p.peek().text == "[" {
			segs, err := p.parseBracketSegments()
			if err != nil { return nil, err }
			if pe, ok := e.(*PathExpr); ok {
				pe.segs = append(pe.segs, segs...)
				e = pe
			} else if te, ok := e.(*TraverseExpr); ok {
				te.segs = append(te.segs, segs...)
				e = te
			} else {
				e = &TraverseExpr{base: e, segs: segs}
			}
			continue
		}
		break
	}
	return e, nil
}

// parse path token and any following brackets are handled by caller loop, but path token may be "." alone etc.
func (p *parser) parsePathSegmentsFromToken() ([]pathSeg, error) {
	tok := p.nextTok()
	if tok.kind == tRecurse {
		if tok.text == "..." {
			return []pathSeg{{kind:"recurseAll"}}, nil
		}
		return []pathSeg{{kind:"recurse"}}, nil
	}
	// tok.text like "." or ".a.b" or ".a." etc
	txt := tok.text
	if txt == "." {
		return nil, nil
	}
	// split by '.' keeping segments; txt starts with '.'
	parts := strings.Split(txt[1:], ".")
	var segs []pathSeg
	for _, part := range parts {
		segs = append(segs, segFromRaw(part))
	}
	return segs, nil
}

func segFromRaw(part string) pathSeg {
	optional := false
	orig := part
	if strings.HasSuffix(part, "?") && len(part) >= 1 {
		// strip one trailing ? as optional marker, except if part is exactly "?"? then strip to empty (observed)
		optional = true
		part = part[:len(part)-1]
		_ = orig
	}
	if part == "*" {
		return pathSeg{kind:"splat", optional: optional}
	}
	// quoted segment ."a-b"
	if len(part) >= 2 && part[0]=='"' && part[len(part)-1]=='"' {
		unq := processStringEscapes(part[1:len(part)-1])
		return pathSeg{kind:"key", key: unq, optional: optional}
	}
	// numeric segment? Keep as key; traverseSeq will parse, traverseMap with key string matching int keys via Value compare
	return pathSeg{kind:"key", key: part, optional: optional}
}

func (p *parser) parseBracketSegments() ([]pathSeg, error) {
	// consume '['
	p.nextTok()
	optional := false
	// empty [] explode/splat - but note collect array is handled in primary when '[' starts an expression, postfix bracket only reached after a primary
	if p.peek().kind == tSymbol && p.peek().text == "]" {
		p.nextTok()
		// optional ?
		// '?' as separate token is not produced except after ] we produce symbol in lexer? we handle raw: peek may be... our lexer has no ? token. But path token after like ? would be lexer error. TODO: handle in lexer
		return []pathSeg{{kind:"splat", optional: optional}}, nil
	}
	// slice or index expression
	// We need to detect slice form: [num? : num?] where numbers can be negative number tokens or empty
	// Save position to attempt slice parsing
	save := p.pos
	sliceSeg, isSlice, err := p.tryParseSlice()
	if err != nil { return nil, err }
	if isSlice {
		// expect ]
		if err := p.expectSymbol("]"); err != nil { return nil, err }
		if p.peek().kind==tSymbol && p.peek().text=="?" { p.nextTok(); sliceSeg.optional=true }
		return []pathSeg{sliceSeg}, nil
	}
	p.pos = save
	// General expression inside brackets
	inner, err := p.parseUnion()
	if err != nil { return nil, err }
	if err := p.expectSymbol("]"); err != nil { return nil, err }
	if p.peek().kind==tSymbol && p.peek().text=="?" { p.nextTok(); optional=true }
	// If inner is literal string/int, make direct seg for efficiency/semantics (autocreate etc)
	if lit, ok := inner.(*LiteralExpr); ok {
		if lit.node.Tag == "!!int" {
			if iv, ok2 := nodeIntValue(lit.node); ok2 {
				return []pathSeg{{kind:"index", index:int(iv), hasIndex:true, optional: optional}}, nil
			}
		}
		if lit.node.Tag == "!!str" {
			return []pathSeg{{kind:"key", key: lit.node.Value, optional: optional}}, nil
		}
	}
	if strE, ok := inner.(*StringExpr); ok && strE.isPlain {
		return []pathSeg{{kind:"key", key: strE.plain, optional: optional}}, nil
	}
	// PathExpr with single segment? e.g. [.a] - evaluate .a against current and use value as key - keep expr seg
	return []pathSeg{{kind:"expr", expr: inner, optional: optional}}, nil
}

func (p *parser) tryParseSlice() (pathSeg, bool, error) {
	// At entry, next token is first inside [
	// forms: [ : ], [1:], [:2], [1:2], [-1:], [:-1] etc. Also [1:2:??] no
	// We try: optional number, then ':' 
	pos := p.pos
	var lo, hi *int
	parseNum := func() (*int, bool) {
		if p.peek().kind == tNumber {
			t := p.nextTok()
			// must be integer decimal possibly negative (token includes -)
			if iv, err := strconv.Atoi(t.text); err == nil {
				v := iv
				return &v, true
			}
			// float token not slice
			return nil, false
		}
		return nil, true // omitted = nil but ok flag confuse; caller uses presence of colon
	}
	// remember if lo present
	loPresent := p.peek().kind == tNumber
	loVal, ok := parseNum()
	if !ok { p.pos = pos; return pathSeg{}, false, nil }
	if loPresent { lo = loVal }
	if !(p.peek().kind==tSymbol && p.peek().text==":") {
		p.pos = pos; return pathSeg{}, false, nil
	}
	p.nextTok() // colon
	if p.peek().kind == tNumber {
		hv, ok := parseNum(); if !ok { p.pos=pos; return pathSeg{}, false, nil }; hi = hv
	}
	// Next should be ] if slice; if not, not slice
	if !(p.peek().kind==tSymbol && p.peek().text=="]") {
		p.pos = pos; return pathSeg{}, false, nil
	}
	return pathSeg{kind:"slice", sliceLo: lo, sliceHi: hi}, true, nil
}

var funcsRequiringArg = map[string]bool{
	"select":true,"map":true,"map_values":true,"filter":true,"has":true,"contains":true,"del":true,"pick":true,"omit":true,"test":true,"match":true,"capture":true,"sub":true,"split":true,"join":true,"sort_by":true,"unique_by":true,"group_by":true,"sort_keys":true,"with_entries":true,"any_c":true,"all_c":true,"error":true,"load":true,"load_str":true,"eval":true,"first":true,"collect":true,"setpath":true,"delpaths":true,"with_dtf":true,"tz":true,"explode":true,"system":true,
}
var zeroArgFuncs = map[string]bool{
	"length":true,"keys":true,"key":true,"sort":true,"reverse":true,"unique":true,"flatten":true,"min":true,"max":true,"tostring":true,"to_string":true,"tonumber":true,"to_number":true,"tojson":true,"to_json":true,"fromjson":true,"from_json":true,"toyaml":true,"to_yaml":true,"fromyaml":true,"from_yaml":true,"toxml":true,"to_xml":true,"fromxml":true,"from_xml":true,"to_props":true,"from_props":true,"to_csv":true,"from_csv":true,"to_tsv":true,"from_tsv":true,"to_entries":true,"from_entries":true,"tag":true,"type":true,"kind":true,"style":true,"anchor":true,"alias":true,"line":true,"column":true,"filename":true,"fileName":true,"file_name":true,"fileIndex":true,"fileindex":true,"file_index":true,"fi":true,"documentIndex":true,"documentindex":true,"document_index":true,"di":true,"head_comment":true,"foot_comment":true,"line_comment":true,"path":true,"parent":true,"parents":true,"root":true,"is_key":true,"not":true,"any":true,"all":true,"now":true,"downcase":true,"upcase":true,"trim":true,"envsubst":true,"array_to_map":true,"pivot":true,"shuffle":true,"split_doc":true,"splitdoc":true,
}

func (p *parser) parsePrimary() (Expr, error) {
	tok := p.peek()
	switch tok.kind {
	case tEOF:
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	case tPath:
		segs, err := p.parsePathSegmentsFromToken()
		if err != nil { return nil, err }
		return &PathExpr{segs: segs}, nil
	case tRecurse:
		segs, err := p.parsePathSegmentsFromToken()
		if err != nil { return nil, err }
		return &PathExpr{segs: segs}, nil
	case tNumber:
		p.nextTok()
		n, err := numberLiteralNode(tok.text)
		if err != nil { return nil, err }
		return &LiteralExpr{node: n}, nil
	case tString:
		p.nextTok()
		return parseStringExpr(tok.text)
	case tVar:
		p.nextTok()
		return &VarExpr{name: tok.text}, nil
	case tEnv:
		p.nextTok()
		return &EnvExpr{kind: tok.text, name: tok.aux}, nil
	case tFormat:
		p.nextTok()
		return &FormatExpr{name: tok.text}, nil
	case tNullTilde:
		p.nextTok()
		return &LiteralExpr{node: scalarNode("!!null","~")}, nil
	case tName:
		name := tok.text
		if name=="true" || name=="false" {
			p.nextTok(); return &LiteralExpr{node: boolNode(name=="true")}, nil
		}
		if name=="null" {
			p.nextTok(); return &LiteralExpr{node: nullNode()}, nil
		}
		if name=="and" || name=="or" {
			// binary op missing LHS
			return nil, fmt.Errorf("'%s' expects 2 args but there is 0", name)
		}
		if name=="ireduce" {
			return nil, fmt.Errorf("'ireduce' expects 2 args but there is 0")
		}
		if name=="ref" {
			return nil, fmt.Errorf("'ref' expects 2 args but there is 0")
		}
		if name=="as" {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		// function / operator name
		p.nextTok()
		// Optional parentheses argument - but be careful: `(...)` after a zero-arg op that is a separate parenthesized expr juxtaposed gives bad expression in original for some.
		// Names that require arg must have parens; if missing, error expects 1 arg... except first/eval weird (bare first/eval returns something)
		// We emulate: if next '(' parse arg; else if requiring arg -> error. For first/eval, allow bare (hasParens false) and eval handles.
		if p.peek().kind==tSymbol && p.peek().text=="(" {
			// parse parentheses content as Union (which includes block ;)
			p.nextTok()
			if p.peek().kind==tSymbol && p.peek().text==")" {
				p.nextTok()
				// empty parens
				if funcsRequiringArg[name] {
					// e.g. select() ? original?
					return &FuncExpr{name:name, arg: &BlockExpr{exprs:nil}, hasParens:true}, nil
				}
				return &FuncExpr{name:name, hasParens:true}, nil
			}
			arg, err := p.parseUnion()
			if err != nil { return nil, err }
			if err := p.expectSymbol(")"); err != nil { return nil, err }
			// special bad-expression cases: tojson/toyaml/flatten with block arg
			if _, isBlock := arg.(*BlockExpr); isBlock {
				if name=="tojson" || name=="to_json" || name=="toyaml" || name=="to_yaml" || name=="flatten" || name=="toxml" || name=="to_xml" {
					return nil, fmt.Errorf("bad expression, please check expression syntax")
				}
			}
			return &FuncExpr{name:name, arg:arg, hasParens:true}, nil
		}
		// no parens
		if funcsRequiringArg[name] {
			if name=="first" || name=="eval" {
				// allow bare: will act as identity-ish in eval (first bare behaviour approximated there)
				return &FuncExpr{name:name, hasParens:false}, nil
			}
			return nil, fmt.Errorf("'%s' expects 1 arg but received none", name)
		}
		return &FuncExpr{name:name, hasParens:false}, nil
	case tSymbol:
		switch tok.text {
		case "(":
			p.nextTok()
			if p.peek().kind==tSymbol && p.peek().text==")" {
				p.nextTok()
				// empty parens () - original? treat as block empty
				return &BlockExpr{}, nil
			}
			e, err := p.parseUnion()
			if err != nil { return nil, err }
			if err := p.expectSymbol(")"); err != nil { return nil, err }
			return e, nil
		case "[":
			// collect array or empty seq literal or slice?? In primary position, [ is collect
			p.nextTok()
			if p.peek().kind==tSymbol && p.peek().text=="]" {
				p.nextTok()
				// [] as primary: this is explode operator when in pipe e.g. ".a | .[]" is path, but standalone "[]"
				// Original: "[]" alone as expression returns splat of input? Or empty array literal? Need check: test later.
				// We'll represent as Path with splat segment (explode). However "[1,2] | . + [3]" second [3] is collect, and "[]" used as literal in comparisons ".a == []" likely empty array.
				// Distinguish impossible statically; yq postfix model: [] token is explode operator, but when used as RHS value (?) e.g. ".a = []" gave a: [].
				// In assign RHS context our parser produces this node; eval of explode on input doc map returns values... that would be wrong for .a = [].
				// We'll make a special FuncExpr name="__empty_array_or_explode" evaluated contextually: in Literal creation contexts (assign RHS, binary RHS etc) original semantics unclear.
				// For now return Literal empty seq; pipe explode forms are ".[]" path or ".a[]" path or "[...][]" postfix, which go through bracketSegments, not primary.
				// Standalone "[]" after pipe: ".a | []" - primary after pipe, original probably explode. We'll handle: return FuncExpr explode_array marker and in eval, if used as ... Hmm.
				// Decision: use marker and let Eval decide based on a ctx flag? We will return a PathExpr splat, and special-case in Assign/Binary evaluation when RHS is exactly that marker -> treat as empty seq literal.
				return &PathExpr{segs: []pathSeg{{kind:"splat"}}}, nil
			}
			inner, err := p.parseUnion()
			if err != nil { return nil, err }
			if err := p.expectSymbol("]"); err != nil { return nil, err }
			return &CollectExpr{inner: inner}, nil
		case "{":
			return p.parseObject()
		case "-":
			// unary minus not supported (number token includes -)
			return nil, fmt.Errorf("'-' expects 2 args but there is 1")
		case "+","*","/","%","|",",","=","==","!=","<",">","<=",">=":
			// binary op with missing lhs
			op := tok.text
			// count args available =0? original messages vary. Use generic for most.
			if op=="|" || op=="*" || op=="/" || op=="%" || op=="==" || op=="!=" || op=="<" {
				// peek stack size approximation: 0
				return nil, fmt.Errorf("'%s' expects 2 args but there is 0", op)
			}
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
	}
	return nil, fmt.Errorf("bad expression, please check expression syntax")
}

func (p *parser) parseObject() (Expr, error) {
	p.nextTok() // {
	if p.peek().kind==tSymbol && p.peek().text=="}" {
		p.nextTok()
		return &ObjectExpr{entries:nil}, nil
	}
	var entries []ObjectEntry
	for {
		// key expr: parse until colon at this level. Key could be string/number/path in parens/path token/variable/array etc.
		// Use parsePipe (not union/comma) for key, but within parens commas handled.
		// However key like .k without parens - parsePostfix
		keyExpr, err := p.parsePipe()
		if err != nil {
			// try simpler?
			return nil, err
		}
		if !(p.peek().kind==tSymbol && p.peek().text==":") {
			// no colon: original produces empty result for {"x"} etc. Represent as object with a special entry with nil val -> eval returns empty.
			// Consume up to comma or }
			entries = append(entries, ObjectEntry{key:keyExpr, val:nil})
		} else {
			p.nextTok() // :
			valExpr, err := p.parsePipe()
			if err != nil { return nil, err }
			entries = append(entries, ObjectEntry{key:keyExpr, val:valExpr})
		}
		if p.peek().kind==tSymbol && p.peek().text=="," {
			p.nextTok()
			if p.peek().kind==tSymbol && p.peek().text=="}" {
				return nil, fmt.Errorf("',' expects 2 args but there is 1")
			}
			continue
		}
		break
	}
	if err := p.expectSymbol("}"); err != nil { return nil, err }
	return &ObjectExpr{entries:entries}, nil
}

func numberLiteralNode(text string) (*yaml.Node, error) {
	// Determine int vs float: contains . e/E (but hex is int)
	if strings.HasPrefix(text,"0x") || strings.HasPrefix(text,"0X") || strings.HasPrefix(text,"-0x") || strings.HasPrefix(text,"-0X") {
		// validate ParseInt base 0? original uses ParseInt(...,10?) for decimal error messages, hex validated elsewhere.
		// We'll validate with ParseInt base 0 after handling sign
		var err error
		s := text
		neg := false
		if strings.HasPrefix(s,"-") { neg=true; s=s[1:] }
		_, err = strconv.ParseInt(s[2:],16,64)
		if err != nil { return nil, err }
		_ = neg
		return scalarNode("!!int", text), nil
	}
	if strings.ContainsAny(text, ".eE") {
		if _, err := strconv.ParseFloat(text,64); err != nil { return nil, err }
		return scalarNode("!!float", text), nil
	}
	if _, err := strconv.ParseInt(text,10,64); err != nil { return nil, err }
	return scalarNode("!!int", text), nil
}

func processStringEscapes(raw string) string {
	// yq custom processing: \n \t \" \\ \b \f \r \v replaced; others left as-is incl \u \x \/
	var b strings.Builder
	for i:=0;i<len(raw);i++ {
		if raw[i]=='\\' && i+1 < len(raw) {
			switch raw[i+1] {
			case 'n': b.WriteByte('\n'); i++
			case 't': b.WriteByte('\t'); i++
			case 'r': b.WriteByte('\r'); i++
			case 'b': b.WriteByte('\b'); i++
			case 'f': b.WriteByte('\f'); i++
			case 'v': b.WriteByte('\v'); i++
			case '"': b.WriteByte('"'); i++
			case '\\': b.WriteByte('\\'); i++
			default:
				b.WriteByte(raw[i])
			}
		} else {
			b.WriteByte(raw[i])
		}
	}
	return b.String()
}

func parseStringExpr(raw string) (Expr, error) {
	// If string interpolation disabled globally later, treat as plain. We'll parse interpolations now and at eval check flag.
	if !strings.Contains(raw, "\\(") {
		return &StringExpr{plain: processStringEscapes(raw), isPlain:true}, nil
	}
	// Need to split by unescaped \( ... matching )
	var parts []interface{}
	i := 0
	for i < len(raw) {
		// find "\(" not preceded by unescaped backslash handling: "\\(" is escaped backslash + '('
		idx := findInterpolation(raw[i:])
		if idx < 0 {
			parts = append(parts, processStringEscapes(raw[i:]))
			break
		}
		idx += i
		if idx > i {
			parts = append(parts, processStringEscapes(raw[i:idx]))
		}
		// find matching ) accounting nested parens and strings (simple count, strings may break - original also breaks with nested quotes)
		depth := 1
		j := idx+2
		for j < len(raw) && depth > 0 {
			if raw[j]=='(' { depth++ } else if raw[j]==')' { depth--; if depth==0 { break } }
			j++
		}
		if depth != 0 {
			// unterminated interpolation: treat rest as literal?
			parts = append(parts, processStringEscapes(raw[idx:]))
			break
		}
		innerSrc := raw[idx+2:j]
		innerExpr, err := parseExpression(innerSrc)
		if err != nil {
			// original error position resets to 1:1 with inner invalid text - parseExpression lexer error already has that for inner src
			return nil, err
		}
		parts = append(parts, innerExpr)
		i = j+1
	}
	return &StringExpr{parts: parts}, nil
}

func findInterpolation(s string) int {
