func (e *StringExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	inputs := effectiveInputs(ctx, in)
	var out []*Cand
	if e.isPlain || !globalCfg.stringInterpolation {
		plain := e.plain
		if !e.isPlain && !globalCfg.stringInterpolation {
			// reconstruct rawish: parts strings + \(...) cannot fully reconstruct - approximate by concatenating string parts and placeholders
			// When interpolation disabled, original lexer treats string as plain with escapes processed but \( left as-is.
			// Our parser already split; we store no raw. For now join string parts.
			var sb strings.Builder
			for _, part := range e.parts {
				if s, ok := part.(string); ok { sb.WriteString(s) } else { sb.WriteString("\\(...)") }
			}
			plain = sb.String()
		}
		for _, c := range inputs {
			out = addCand(out, c.cloneWith(stringNode(plain)))
		}
		return out, nil
	}
	for _, c := range inputs {
		var sb strings.Builder
		for _, part := range e.parts {
			if s, ok := part.(string); ok {
				sb.WriteString(s)
			} else if expr, ok := part.(Expr); ok {
				vals, err := expr.Eval(ctx, []*Cand{c})
				if err != nil { return nil, err }
				for _, v := range vals {
					sb.WriteString(interpolationString(v.Node))
				}
			}
		}
		out = addCand(out, c.cloneWith(stringNode(sb.String())))
	}
