	if n == nil { return "" }
	if n.Kind == yaml.ScalarNode {
		if n.Tag == "!!null" && n.Value == "" { return "" }
		if n.Tag == "!!null" { return "null" } // \(.missing) where missing created null node value "null" -> "null"? check later
