	for _, en := range e.entries {
		if en.val == nil { return nil, nil }
	}
	// cartesian combinations
	type pair struct{ k, v *Cand }
	// compute per entry pairs
	var perEntry [][]pair
	for _, en := range e.entries {
		keys, err := en.key.Eval(ctx, in)
		if err != nil { return nil, err }
		vals, err := en.val.Eval(ctx, in)
		if err != nil { return nil, err }
		if len(keys)==0 {
			keys = []*Cand{effectiveInputs(ctx,in)[0].cloneWith(nullNode())}
		}
		if len(vals)==0 {
			// value empty -> no maps?
			return nil, nil
		}
		var pairs []pair
		for _, k := range keys {
			for _, v := range vals {
				pairs = append(pairs, pair{k,v})
			}
		}
		perEntry = append(perEntry, pairs)
	}
	var combos [][]pair
	var rec func(int, []pair)
	rec = func(idx int, cur []pair) {
		if idx==len(perEntry) { combos = append(combos, append([]pair(nil), cur...)); return }
		for _, pr := range perEntry[idx] { rec(idx+1, append(cur, pr)) }
	}
	rec(0, nil)
	base := effectiveInputs(ctx, in)[0]
	var out []*Cand
	for _, combo := range combos {
		m := mapNode()
		for _, pr := range combo {
			kNode := copyNodePreserve(pr.k.Node)
			// Keys that are complex etc kept; scalar keys style reset?
			// If key is literal string, node is !!str
			vNode := copyNodePreserve(pr.v.Node)
			m.Content = append(m.Content, kNode, vNode)
		}
		res := &Cand{Node:m, Path: []interface{}{}, DocIdx: base.DocIdx, FileIdx: base.FileIdx, Filename: base.Filename}
