func (e *EnvExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	if globalCfg.securityDisableEnvOps {
		return nil, fmt.Errorf("env operations have been disabled")
	}
	val, present := os.LookupEnv(e.name)
	inputs := effectiveInputs(ctx, in)
	var out []*Cand
	if e.kind == "strenv" {
		// always string, empty if missing
		for _, c := range inputs { out = addCand(out, c.cloneWith(stringNode(val))) }
		return out, nil
	}
	// env()
	if !present || val == "" {
		return nil, fmt.Errorf("value for env variable '%s' not provided in env()", e.name)
	}
	// parse value as yaml scalar/node
	node, err := parseYAMLStringToNode(val)
	if err != nil {
		node = stringNode(val)
	}
	for _, c := range inputs { out = addCand(out, c.cloneWith(copyNode(node))) }
	return out, nil
}

func parseYAMLStringToNode(s string) (*yaml.Node, error) {
	var n yaml.Node
	dec := yaml.NewDecoder(strings.NewReader(s))
	if err := dec.Decode(&n); err != nil { return nil, err }
	if len(n.Content)>0 { return n.Content[0], nil }
	return blankNullNode(), nil
}
