package main

import (
	"fmt"
	"os"
	"strings"

	"gopkg.in/yaml.v3"
)

// effective inputs for creation-type ops when in is empty
func effectiveInputs(ctx *Ctx, in []*Cand) []*Cand {
	if len(in) > 0 {
		return in
	}
	if ctx != nil && len(ctx.fallback) > 0 {
		return ctx.fallback
	}
	return []*Cand{{Node: blankNullNode(), Path: []interface{}{}}}
}

func (e *LiteralExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	inputs := effectiveInputs(ctx, in)
	var out []*Cand
	for _, c := range inputs {
		out = addCand(out, c.cloneWith(copyNode(e.node)))
	}
	return out, nil
}

func (e *StringExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	inputs := effectiveInputs(ctx, in)
	var out []*Cand
	if e.isPlain || !globalCfg.stringInterpolation {
		plain := e.plain
		if !e.isPlain && !globalCfg.stringInterpolation {
			// reconstruct rawish: parts strings + \(...) cannot fully reconstruct - approximate by concatenating string parts and placeholders
			// When interpolation disabled, original lexer treats string as plain with escapes processed but \( left as-is.
			// Our parser already split; we store no raw. For now join string parts.
			var sb strings.Builder
			for _, part := range e.parts {
				if s, ok := part.(string); ok { sb.WriteString(s) } else { sb.WriteString("\\(...)") }
			}
			plain = sb.String()
		}
		for _, c := range inputs {
			out = addCand(out, c.cloneWith(stringNode(plain)))
		}
		return out, nil
	}
	for _, c := range inputs {
		var sb strings.Builder
		for _, part := range e.parts {
			if s, ok := part.(string); ok {
				sb.WriteString(s)
			} else if expr, ok := part.(Expr); ok {
				vals, err := expr.Eval(ctx, []*Cand{c})
				if err != nil { return nil, err }
				for _, v := range vals {
					sb.WriteString(interpolationString(v.Node))
				}
			}
		}
		out = addCand(out, c.cloneWith(stringNode(sb.String())))
	}
	return out, nil
}

func interpolationString(n *yaml.Node) string {
	if n == nil { return "" }
	if n.Kind == yaml.ScalarNode {
		if n.Tag == "!!null" && n.Value == "" { return "" }
		if n.Tag == "!!null" { return "null" } // \(.missing) where missing created null node value "null" -> "null"? check later
		return n.Value
	}
	// For complex, yq converts to yaml string?
	s, _ := encodeNodeToString(n, "yaml", 2)
	return strings.TrimSuffix(s, "\n")
}

func (e *VarExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	if v, ok := ctx.getVar(e.name); ok {
		return v, nil
	}
	// Special variables?
	if e.name == "__progname" {
		inputs := effectiveInputs(ctx, in)
		var out []*Cand
		for _, c := range inputs { out = addCand(out, c.cloneWith(stringNode("yq"))) }
		return out, nil
	}
	return nil, nil
}

func (e *PathExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	if len(e.segs)==0 {
		return in, nil
	}
	cur := in
	for _, seg := range e.segs {
		var next []*Cand
		for _, c := range cur {
			res, err := traverseSeg(ctx, c, seg)
			if err != nil { return nil, err }
			next = addCands(next, res)
		}
		cur = next
	}
	return cur, nil
}

func (e *TraverseExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	base, err := e.base.Eval(ctx, in)
	if err != nil { return nil, err }
	p := &PathExpr{segs: e.segs}
	return p.Eval(ctx, base)
}

func (e *PipeExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	left, err := e.left.Eval(ctx, in)
	if err != nil { return nil, err }
	rctx := ctx.childCtx()
	if len(left)==0 {
		if len(in)>0 { rctx.fallback = in }
		// else keep ctx fallback
	}
	return e.right.Eval(rctx, left)
}

func (e *UnionExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	var out []*Cand
	for _, sub := range e.exprs {
		res, err := sub.Eval(ctx, in)
		if err != nil { return nil, err }
		out = addCands(out, res)
	}
	return out, nil
}

func (e *BlockExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	return nil, nil
}

func (e *AsExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	vals, err := e.expr.Eval(ctx, in)
	if err != nil { return nil, err }
	child := ctx.childCtx()
	child.setVar(e.varName, vals)
	// body evaluated against original inputs (jq semantics: . in body is original input before as expression? In jq, `exp as $x | body` body input is original input, not exp result.)
	// yq examples: ".a as $x | $x + 1" doesn't use . ; ". as $item ireduce" etc. Test: ".a as $x | ." should be root if jq semantics, or .a if yq semantics?
	return e.body.Eval(child, in)
}

func (e *IreduceExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	// evaluate generator exp against in (each result is an item)
	items, err := e.expr.Eval(ctx, in)
	if err != nil { return nil, err }
	// init evaluated against in? jq reduce init input is original.
	acc, err := e.init.Eval(ctx, in)
	if err != nil { return nil, err }
	// acc should be single list; if multiple, ireduce over each? yq ireduce semantics: accumulator starts init (first?)
	// For typical `. as $item ireduce ({}; . * $item)` with multiple inputs (eval-all), items are all docs, init {} single.
	// If acc empty, use fallback null?
	if len(acc)==0 {
		acc = effectiveInputs(ctx, in)
		// clone with null?
		for i:= range acc { acc[i] = acc[i].cloneWith(blankNullNode()) }
	}
	// iterate: for each acc candidate separately? Usually one.
	var results []*Cand
	for _, a := range acc {
		cur := a
		for _, item := range items {
			child := ctx.childCtx()
			child.setVar(e.varName, []*Cand{item})
			next, err := e.update.Eval(child, []*Cand{cur})
			if err != nil { return nil, err }
			if len(next)==0 {
				cur = cur.cloneWith(blankNullNode())
			} else {
				// update may produce multiple - take last? or first? Take first for accumulator, but if multiple, last is typical? Probe later.
				cur = next[len(next)-1]
			}
		}
		results = addCand(results, cur)
	}
	return results, nil
}

func (e *CollectExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	vals, err := e.inner.Eval(ctx, in)
	if err != nil { return nil, err }
	seq := seqNode()
	for _, v := range vals {
		seq.Content = append(seq.Content, copyNodePreserve(v.Node))
	}
	// Candidate metadata: new root path [] ; doc/file from first input/fallback
	base := effectiveInputs(ctx, in)[0]
	res := &Cand{Node: seq, Path: []interface{}{}, DocIdx: base.DocIdx, FileIdx: base.FileIdx, Filename: base.Filename}
	// children parent linkage created on traversal from res
	return []*Cand{res}, nil
}

func (e *ObjectExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	if len(e.entries)==0 {
		base := effectiveInputs(ctx, in)[0]
		m := mapNode()
		m.Style = yaml.FlowStyle // {} prints as {} - yaml encoder prints empty map as {} regardless
		res := &Cand{Node:m, Path: []interface{}{}, DocIdx: base.DocIdx, FileIdx: base.FileIdx, Filename: base.Filename}
		return []*Cand{res}, nil
	}
	// if any entry has nil val (no colon) -> empty result
	for _, en := range e.entries {
		if en.val == nil { return nil, nil }
	}
	// cartesian combinations
	type pair struct{ k, v *Cand }
	// compute per entry pairs
	var perEntry [][]pair
	for _, en := range e.entries {
		keys, err := en.key.Eval(ctx, in)
		if err != nil { return nil, err }
		vals, err := en.val.Eval(ctx, in)
		if err != nil { return nil, err }
		if len(keys)==0 {
			keys = []*Cand{effectiveInputs(ctx,in)[0].cloneWith(nullNode())}
		}
		if len(vals)==0 {
			// value empty -> no maps?
			return nil, nil
		}
		var pairs []pair
		for _, k := range keys {
			for _, v := range vals {
				pairs = append(pairs, pair{k,v})
			}
		}
		perEntry = append(perEntry, pairs)
	}
	var combos [][]pair
	var rec func(int, []pair)
	rec = func(idx int, cur []pair) {
		if idx==len(perEntry) { combos = append(combos, append([]pair(nil), cur...)); return }
		for _, pr := range perEntry[idx] { rec(idx+1, append(cur, pr)) }
	}
	rec(0, nil)
	base := effectiveInputs(ctx, in)[0]
	var out []*Cand
	for _, combo := range combos {
		m := mapNode()
		for _, pr := range combo {
			kNode := copyNodePreserve(pr.k.Node)
			// Keys that are complex etc kept; scalar keys style reset?
			// If key is literal string, node is !!str
			vNode := copyNodePreserve(pr.v.Node)
			m.Content = append(m.Content, kNode, vNode)
		}
		res := &Cand{Node:m, Path: []interface{}{}, DocIdx: base.DocIdx, FileIdx: base.FileIdx, Filename: base.Filename}
		out = addCand(out, res)
	}
	return out, nil
}

func (e *EnvExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	if globalCfg.securityDisableEnvOps {
		return nil, fmt.Errorf("env operations have been disabled")
	}
	val, present := os.LookupEnv(e.name)
	inputs := effectiveInputs(ctx, in)
	var out []*Cand
	if e.kind == "strenv" {
		// always string, empty if missing
		for _, c := range inputs { out = addCand(out, c.cloneWith(stringNode(val))) }
		return out, nil
	}
	// env()
	if !present || val == "" {
		return nil, fmt.Errorf("value for env variable '%s' not provided in env()", e.name)
	}
	// parse value as yaml scalar/node
	node, err := parseYAMLStringToNode(val)
	if err != nil {
		node = stringNode(val)
	}
	for _, c := range inputs { out = addCand(out, c.cloneWith(copyNode(node))) }
	return out, nil
}

func parseYAMLStringToNode(s string) (*yaml.Node, error) {
	var n yaml.Node
	dec := yaml.NewDecoder(strings.NewReader(s))
	if err := dec.Decode(&n); err != nil { return nil, err }
	if len(n.Content)>0 { return n.Content[0], nil }
	return blankNullNode(), nil
}
