package main

import (
	"fmt"
	"math"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

func ensureOperand(ctx *Ctx, in []*Cand, vals []*Cand) []*Cand {
	if len(vals) > 0 { return vals }
	inputs := effectiveInputs(ctx, in)
	var out []*Cand
	for _, c := range inputs { out = append(out, c.cloneWith(nullNode())) }
	return out
}

func (e *BinaryExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	op := e.op
	if op == "//" {
		left, err := e.left.Eval(ctx, in)
		if err != nil { return nil, err }
		var nonFalsey []*Cand
		for _, c := range left { if !nodeIsFalsey(c.Node) { nonFalsey = addCand(nonFalsey, c) } }
		if len(nonFalsey) > 0 { return nonFalsey, nil }
		return e.right.Eval(ctx, in)
	}
	// operand context
	ectx := ctx
	switch {
	case op=="+" || op=="-" || op=="/" || op=="%" || strings.HasPrefix(op,"*") || op=="and" || op=="or":
		ectx = ctx.withNoCreate()
	}
	left, err := e.left.Eval(ectx, in)
	if err != nil { return nil, err }
	right, err := e.right.Eval(ectx, in)
	if err != nil { return nil, err }
	left = ensureOperand(ctx, in, left)
	right = ensureOperand(ctx, in, right)
	var out []*Cand
	for _, l := range left {
		for _, r := range right {
			res, err := applyBinary(op, l, r)
			if err != nil { return nil, err }
			if res != nil { out = addCand(out, res) }
		}
	}
	return out, nil
}

func resultNode(lhs *Cand, n *yaml.Node) *Cand {
	return lhs.cloneWith(n)
}

func pathLeaf(c *Cand) string {
	if len(c.Path)==0 { return "" }
	return fmt.Sprintf("%v", c.Path[len(c.Path)-1])
}

func arithError(op string, lhs, rhs *Cand) error {
	lt := nodeTagOrDefault(lhs.Node); rt := nodeTagOrDefault(rhs.Node)
	lp := pathLeaf(lhs); rp := pathLeaf(rhs)
	switch op {
	case "+":
		return fmt.Errorf("%s (%s) cannot be added to a %s (%s)", rt, rp, lt, lp)
	case "-":
		return fmt.Errorf("%s (%s) cannot be subtracted from a %s (%s)", rt, rp, lt, lp)
	case "/":
		return fmt.Errorf("%s (%s) cannot be divided by %s (%s)", lt, lp, rt, rp)
	case "%":
		return fmt.Errorf("%s (%s) cannot be modded by %s (%s)", lt, lp, rt, rp)
	default: // *
		return fmt.Errorf("%s (%s) cannot be multiplied by %s (%s)", lt, lp, rt, rp)
	}
}

func applyBinary(op string, lhs, rhs *Cand) (*Cand, error) {
	switch op {
	case "and":
		return resultNode(lhs, boolNode(!nodeIsFalsey(lhs.Node) && !nodeIsFalsey(rhs.Node))), nil
	case "or":
		return resultNode(lhs, boolNode(!nodeIsFalsey(lhs.Node) || !nodeIsFalsey(rhs.Node))), nil
	case "==", "!=", "<", "<=", ">", ">=":
		b, err := compareNodes(op, lhs.Node, rhs.Node)
		if err != nil { return nil, err }
		return resultNode(lhs, boolNode(b)), nil
	case "ref":
		return nil, fmt.Errorf("must use variable with a pipe, e.g. `exp as $x | ...`")
	}
	return applyArithmetic(op, lhs, rhs)
}

func compareNodes(op string, a, b *yaml.Node) (bool, error) {
	if op=="==" || op=="!=" {
		eq := nodesEqual(a,b)
		if op=="==" { return eq, nil }
		return !eq, nil
	}
	// ordering
	cmp, err := nodeCmp(a,b)
	if err != nil { return false, err }
	switch op {
	case "<": return cmp < 0, nil
	case "<=": return cmp <= 0, nil
	case ">": return cmp > 0, nil
	case ">=": return cmp >= 0, nil
	}
	return false, nil
}

func nodesEqual(a,b *yaml.Node) bool {
	// Dereference alias
	a = derefAlias(a); b = derefAlias(b)
	if a.Kind != b.Kind {
		// numeric cross int/float both scalar - kinds same (scalar) so only containers differ
		return false
	}
	switch a.Kind {
	case yaml.ScalarNode:
		// Numbers equal by value even across int/float?
		if (a.Tag=="!!int" || a.Tag=="!!float") && (b.Tag=="!!int" || b.Tag=="!!float") {
			af, aok := nodeToFloat(a); bf, bok := nodeToFloat(b)
			if aok && bok {
				// for big ints float compare may be lossy; if both int compare ints
				if a.Tag=="!!int" && b.Tag=="!!int" {
					ai,_:=nodeIntValue(a); bi,_:=nodeIntValue(b); return ai==bi
				}
				return af==bf
			}
		}
		if a.Tag=="!!timestamp" && b.Tag=="!!timestamp" {
			at,ae:=parseTimestamp(a.Value); bt,be:=parseTimestamp(b.Value)
			if ae==nil && be==nil { return at.Equal(bt) }
		}
		// Tags must match? !!str "1" vs !!int 1 probably not equal.
		// But null variants: value "" vs "null" vs "~" all !!null equal?
		if a.Tag=="!!null" && b.Tag=="!!null" { return true }
		return a.Tag==b.Tag && a.Value==b.Value
	case yaml.SequenceNode:
		if len(a.Content)!=len(b.Content) { return false }
		for i:= range a.Content { if !nodesEqual(a.Content[i], b.Content[i]) { return false } }
		return true
	case yaml.MappingNode:
		if len(a.Content)!=len(b.Content) { return false }
		// unordered matching by key equality
		used := make([]bool, len(b.Content)/2)
		for i:=0;i+1<len(a.Content);i+=2 {
			found:=false
			for j:=0;j+1<len(b.Content);j+=2 {
				if used[j/2] { continue }
				if nodesEqual(a.Content[i], b.Content[j]) && nodesEqual(a.Content[i+1], b.Content[j+1]) { used[j/2]=true; found=true; break }
			}
			if !found { return false }
		}
		return true
	}
	return false
}

func derefAlias(n *yaml.Node) *yaml.Node {
	if n != nil && n.Kind==yaml.AliasNode && n.Alias != nil { return derefAlias(n.Alias) }
	return n
}

func nodeCmp(a,b *yaml.Node) (int, error) {
	a = derefAlias(a); b = derefAlias(b)
	// Arrays/maps comparison for sort: yq sort has its own logic; comparison operator errors.
	if a.Kind==yaml.SequenceNode || b.Kind==yaml.SequenceNode {
		return 0, fmt.Errorf("arrays not yet supported for comparison")
	}
	if a.Kind==yaml.MappingNode || b.Kind==yaml.MappingNode {
		return 0, fmt.Errorf("maps not yet supported for comparison")
	}
	// both scalar
	// numbers
	af, aIsNum := nodeToFloat(a); bf, bIsNum := nodeToFloat(b)
	if aIsNum && bIsNum {
		// exact int compare
		if a.Tag=="!!int" && b.Tag=="!!int" {
			ai,ok1:=nodeIntValue(a); bi,ok2:=nodeIntValue(b)
			if ok1 && ok2 { if ai<bi {return -1,nil}; if ai>bi {return 1,nil}; return 0,nil }
		}
		if af<bf {return -1,nil}; if af>bf {return 1,nil}; return 0,nil
	}
	if a.Tag=="!!timestamp" || b.Tag=="!!timestamp" {
		// Compare as time if both parsable or one is string date?
		at, ae := parseTimestamp(a.Value); bt, be := parseTimestamp(b.Value)
		if ae==nil && be==nil { if at.Before(bt){return -1,nil}; if at.After(bt){return 1,nil}; return 0,nil }
		// fallthrough string compare
	}
	if a.Tag=="!!str" && b.Tag=="!!str" {
		return strings.Compare(a.Value,b.Value), nil
	}
	if a.Tag=="!!timestamp" && b.Tag=="!!str" {
		at, ae := parseTimestamp(a.Value); bt, be := parseTimestamp(b.Value)
		if ae==nil && be==nil { if at.Before(bt){return -1,nil}; if at.After(bt){return 1,nil}; return 0,nil }
		return strings.Compare(a.Value,b.Value), nil
	}
	if a.Tag=="!!str" && b.Tag=="!!timestamp" {
		at, ae := parseTimestamp(a.Value); bt, be := parseTimestamp(b.Value)
		if ae==nil && be==nil { if at.Before(bt){return -1,nil}; if at.After(bt){return 1,nil}; return 0,nil }
		return strings.Compare(a.Value,b.Value), nil
	}
	if a.Tag=="!!null" && b.Tag=="!!null" { return 0,nil }
	// Unsupported type for ordering: error mentions lhs tag (observed !!bool / !!int when comparing int to bool)
	return 0, fmt.Errorf("%s not yet supported for comparison", nodeTagOrDefault(a))
}

// sort comparison used by sort operators: returns -1/0/1 with yq ordering rules.
// yq sorting: nulls first? Then booleans? numbers, strings ... We'll implement based on probes later.
func sortCmp(a,b *yaml.Node) int {
	a=derefAlias(a); b=derefAlias(b)
	ra:=sortRank(a); rb:=sortRank(b)
	if ra!=rb { if ra<rb {return -1}; return 1 }
	switch a.Kind {
	case yaml.ScalarNode:
		if c,err:=nodeCmpSafe(a,b); err==nil {return c}
		// bool: false<true
		if a.Tag=="!!bool" && b.Tag=="!!bool" { av:=parseBool(a.Value); bv:=parseBool(b.Value); if av==bv{return 0}; if !av{return -1}; return 1 }
		return strings.Compare(a.Value,b.Value)
	case yaml.SequenceNode:
		for i:=0;i<len(a.Content) && i<len(b.Content);i++ { if c:=sortCmp(a.Content[i],b.Content[i]); c!=0 {return c} }
		if len(a.Content)<len(b.Content){return -1}; if len(a.Content)>len(b.Content){return 1}; return 0
	case yaml.MappingNode:
		// compare by keys then values in order?
		for i:=0;i<len(a.Content) && i<len(b.Content);i++ { if c:=sortCmp(a.Content[i],b.Content[i]); c!=0 {return c} }
		if len(a.Content)<len(b.Content){return -1}; if len(a.Content)>len(b.Content){return 1}; return 0
	}
	return 0
}
func nodeCmpSafe(a,b *yaml.Node)(int,error){
	// nodeCmp but for null/bool returns error - only use when numeric/string/timestamp
	if (a.Tag=="!!int"||a.Tag=="!!float") && (b.Tag=="!!int"||b.Tag=="!!float") { return nodeCmp(a,b) }
	if a.Tag=="!!str" && b.Tag=="!!str" { return nodeCmp(a,b) }
	if a.Tag=="!!timestamp" && b.Tag=="!!timestamp" { return nodeCmp(a,b) }
	return 0, fmt.Errorf("no")
}
func sortRank(n *yaml.Node) int {
	if n.Kind==yaml.ScalarNode {
		switch n.Tag {
		case "!!null": return 0
		case "!!bool": return 1
		case "!!int","!!float": return 2
		case "!!str": return 3
		case "!!timestamp": return 3
		default: return 3
		}
	}
	if n.Kind==yaml.SequenceNode { return 4 }
	if n.Kind==yaml.MappingNode { return 5 }
	return 6
}

func applyArithmetic(op string, lhs, rhs *Cand) (*Cand, error) {
	ln := derefAlias(lhs.Node); rn := derefAlias(rhs.Node)
	// Null handling for +
	if op=="+" {
		if nodeIsNull(ln) {
			// result is rhs copy, but candidate derived from lhs (path) or rhs? Use lhs clone with copy rhs
			return resultNode(lhs, copyNode(rn)), nil
		}
		if nodeIsNull(rn) {
			return resultNode(lhs, copyNode(ln)), nil
		}
	}
	// Timestamps arithmetic + / -
	if (op=="+" || op=="-") {
		if res, handled, err := timestampArithmetic(op,lhs,rhs,ln,rn); handled { return res, err }
	}
	// Multiply maps merge
	if strings.HasPrefix(op,"*") && ln.Kind==yaml.MappingNode && rn.Kind==yaml.MappingNode {
		merged := mergeMaps(copyNodePreserve(ln), copyNodePreserve(rn), op)
		return resultNode(lhs, merged), nil
	}
	if strings.HasPrefix(op,"*") && ((ln.Kind==yaml.MappingNode) || (rn.Kind==yaml.MappingNode)) {
		// map * scalar etc: if one is null?
		if nodeIsNull(ln) { return resultNode(lhs, copyNode(rn)), nil }
		if nodeIsNull(rn) { return resultNode(lhs, copyNode(ln)), nil }
		// fallthrough error below if numbers not
	}
	// Arrays
	if op=="+" && ln.Kind==yaml.SequenceNode && rn.Kind==yaml.SequenceNode {
		newSeq := seqNode()
		newSeq.Style = ln.Style
		for _, ch := range ln.Content { newSeq.Content=append(newSeq.Content, copyNode(ch)) }
		for _, ch := range rn.Content { newSeq.Content=append(newSeq.Content, copyNode(ch)) }
		return resultNode(lhs, newSeq), nil
	}
	if op=="-" && ln.Kind==yaml.SequenceNode && rn.Kind==yaml.SequenceNode {
		newSeq:=seqNode(); newSeq.Style=ln.Style
		for _, ch := range ln.Content {
			found:=false
			for _, rch := range rn.Content { if nodesEqual(ch,rch){found=true;break} }
			if !found { newSeq.Content=append(newSeq.Content, copyNode(ch)) }
		}
		return resultNode(lhs, newSeq), nil
	}
	// String operations
	if ln.Kind==yaml.ScalarNode && rn.Kind==yaml.ScalarNode {
		// string concatenation: if either is string and op is +, and other is scalar convertible?
		if op=="+" && (ln.Tag=="!!str" || rn.Tag=="!!str") {
			// But numbers as strings? int + string gave "1x". Timestamp+string handled above.
			return resultNode(lhs, stringNode(scalarToString(ln)+scalarToString(rn))), nil
		}
		if op=="/" && ln.Tag=="!!str" && rn.Tag=="!!str" {
			// split
			if rn.Value=="" {
				// split into chars?
				parts:= strings.Split(ln.Value,"")
				seq:=seqNode(); for _,p:=range parts{seq.Content=append(seq.Content,stringNode(p))}; return resultNode(lhs,seq),nil
			}
			parts:=strings.Split(ln.Value, rn.Value)
			seq:=seqNode(); for _,p:=range parts{seq.Content=append(seq.Content,stringNode(p))}; return resultNode(lhs,seq),nil
		}
		if op=="*" || strings.HasPrefix(op,"*") {
			// string repeat
			if ln.Tag=="!!str" && rn.Tag=="!!int" {
				iv,_:=nodeIntValue(rn); if iv<0{iv=0}; return resultNode(lhs,stringNode(strings.Repeat(ln.Value,int(iv)))),nil
			}
			if rn.Tag=="!!str" && ln.Tag=="!!int" {
				iv,_:=nodeIntValue(ln); if iv<0{iv=0}; return resultNode(lhs,stringNode(strings.Repeat(rn.Value,int(iv)))),nil
			}
			if ln.Tag=="!!str" && rn.Tag=="!!str" {
				// jq: split lhs by rhs
				parts:=strings.Split(ln.Value, rn.Value); seq:=seqNode(); for _,p:=range parts{seq.Content=append(seq.Content,stringNode(p))}; return resultNode(lhs,seq),nil
			}
		}
		// numeric
		lf, lIsNum := nodeToFloat(ln); rf, rIsNum := nodeToFloat(rn)
		if lIsNum && rIsNum {
			li, lIsInt := intValueIfInt(ln); ri, rIsInt := intValueIfInt(rn)
			bothInt := lIsInt && rIsInt
			var res *yaml.Node
			switch op {
			case "+":
				if bothInt { res=intNode(li+ri) } else { res=floatNode(lf+rf) }
			case "-":
				if bothInt { res=intNode(li-ri) } else { res=floatNode(lf-rf) }
			case "*":
				if bothInt { res=intNode(li*ri) } else { res=floatNode(lf*rf) }
			case "/":
				// int division: if divides evenly? Probe: yq 4/2 = 2 (presumably float 2?) We'll emit int if both int and divisible, else float.
				if bothInt && ri!=0 && li%ri==0 { res=intNode(li/ri) } else { res=floatNode(lf/rf) }
			case "%":
				if bothInt { if ri==0 { return nil, fmt.Errorf("cannot modulo by zero") }; res=intNode(li%ri) } else { res=floatNode(math.Mod(lf,rf)) }
			default:
				if strings.HasPrefix(op,"*") {
					if bothInt { res=intNode(li*ri) } else { res=floatNode(lf*rf) }
				} else {
					return nil, arithError(op,lhs,rhs)
				}
			}
			return resultNode(lhs,res),nil
		}
		// handle multiply with flags on scalars -> error as *
	}
	// Null with other ops: - * / etc: treat null as identity? jq null arithmetic: null - x = -x etc. yq likely: numbers above fail if null - check later. For now arith error except + handled.
	return nil, arithError(op,lhs,rhs)
}

func intValueIfInt(n *yaml.Node)(int64,bool){
	if n.Tag!="!!int" {return 0,false}
	v,ok:=nodeIntValue(n); return v,ok
}

func scalarToString(n *yaml.Node) string {
	if n.Tag=="!!null" { if n.Value==""{return ""}; return n.Value }
	return n.Value
}

func timestampArithmetic(op string, lhs, rhs *Cand, ln, rn *yaml.Node)(*Cand,bool,error){
	// LHS timestamp +/- duration (rhs scalar parsed as duration)
	if ln.Tag=="!!timestamp" {
		lt, err := parseTimestamp(ln.Value)
		if err!=nil { return nil,false,nil }
		// rhs duration string from its raw value regardless tag (int will error missing unit as original)
		durStr := rn.Value
		if op=="-" { durStr = "-" + durStr; if strings.HasPrefix(rn.Value,"-") { durStr = rn.Value[1:] } }
		// Original error for t-t : 'unable to parse duration [x]: time: unknown unit "-" in duration "-x"' where x is rhs timestamp and duration string passed is "-x" for subtraction? Wait for '-' they negate duration by prefixing '-' then parse, error shows duration "-2021..." i.e. includes minus. Our durStr mirrors.
		d, err := parseDurationExt(durStr)
		if err != nil {
			return nil,true, fmt.Errorf("unable to parse duration [%s]: %s", rn.Value, durationErrString(durStr, err))
		}
		// parseDurationExt may return calendar components - handled inside returning a time result directly? Simplify: only time.Duration
		newT := lt.Add(d)
		// calendar add if ext duration had years/months/days stored in global? parseDurationExt returns duration approximating days as 24h - may mismatch month/year cases. Accept.
		return resultNode(lhs, scalarNode("!!timestamp", formatTimestamp(newT))), true, nil
	}
	if op=="+" && rn.Tag=="!!timestamp" && ln.Tag=="!!str" {
		rt, err:=parseTimestamp(rn.Value); if err!=nil {return nil,false,nil}
		d, err:=parseDurationExt(ln.Value); if err!=nil { return nil,true, fmt.Errorf("unable to parse duration [%s]: %s", ln.Value, durationErrString(ln.Value,err)) }
		return resultNode(lhs, scalarNode("!!timestamp", formatTimestamp(rt.Add(d)))), true,nil
	}
	return nil,false,nil
}

func durationErrString(s string, err error) string {
	// Go time.ParseDuration errors already have format `time: unknown unit ... in duration "..."` etc.
	return err.Error()
}

// parse duration with yq extensions: supports Go units plus d, w, y? Probe later.
func parseDurationExt(s string)(time.Duration,error){
	// Try Go first
	if d,err:=time.ParseDuration(s); err==nil { return d,nil }
	// Handle simple extensions by replacing 'd' with '24h' etc is complex if composite.
	// Implement regex parse of components: number + unit where unit in y, mo?, w,d,h,m,s,ms,us,ns
	// For now return Go error from a parse attempt on original to preserve error message.
	_,err:=time.ParseDuration(s)
	return 0,err
}

func mergeMaps(lhs, rhs *yaml.Node, op string) *yaml.Node {
	appendArr := strings.Contains(op,"+")
	onlyExisting := strings.Contains(op,"?")
	deepArr := strings.Contains(op,"d")
	nullOnly := strings.Contains(op,"n")
	mergeInto(lhs,rhs,appendArr,onlyExisting,deepArr,nullOnly,op)
	return lhs
}
func mergeInto(lhs, rhs *yaml.Node, appendArr, onlyExisting, deepArr, nullOnly bool, op string){
	// both maps
	for i:=0;i+1<len(rhs.Content);i+=2 {
		rk:=rhs.Content[i]; rv:=rhs.Content[i+1]
		// handle merge key << in rhs? If rk is !!merge <<, merge its value map(s)
		if rk.Tag=="!!merge" || rk.Value=="<<" {
			// rv may be map or seq of maps or alias
			mergeValue := derefAlias(rv)
			if mergeValue.Kind==yaml.MappingNode { mergeInto(lhs, copyNodePreserve(mergeValue),appendArr,onlyExisting,deepArr,nullOnly,op) } else if mergeValue.Kind==yaml.SequenceNode { for _,ch:=range mergeValue.Content { mv:=derefAlias(ch); if mv.Kind==yaml.MappingNode { mergeInto(lhs, copyNodePreserve(mv),appendArr,onlyExisting,deepArr,nullOnly,op)}}}
			continue
		}
		// find in lhs
		idx:=-1
		for j:=0;j+1<len(lhs.Content);j+=2 {
			if keyMatches(lhs.Content[j], keyString(rk)) || nodesEqual(lhs.Content[j], rk) { idx=j; break }
		}
		if idx<0 {
			if onlyExisting { continue }
			lhs.Content=append(lhs.Content, copyNodePreserve(rk), copyNodePreserve(rv))
		} else {
			lv:=lhs.Content[idx+1]
			merged:=mergeValues(lv,rv,appendArr,onlyExisting,deepArr,nullOnly,op)
			if merged!=nil { lhs.Content[idx+1]=merged }
		}
	}
	// Also handle lhs merge keys? Keep as is.
}
func mergeValues(lv, rv *yaml.Node, appendArr, onlyExisting, deepArr, nullOnly bool, op string) *yaml.Node {
	lvd:=derefAlias(lv); rvd:=derefAlias(rv)
	if nullOnly {
		if !nodeIsNull(lvd) {
			// if both maps, still recursively merge? For *n example with nested maps? It may still merge maps but not overwrite non-null scalars.
			if lvd.Kind==yaml.MappingNode && rvd.Kind==yaml.MappingNode {
				res:=copyNodePreserve(lvd); mergeInto(res, copyNodePreserve(rvd),appendArr,onlyExisting,deepArr,nullOnly,op); return res
			}
			return lv
		}
		return copyNodePreserve(rv)
	}
	if lvd.Kind==yaml.MappingNode && rvd.Kind==yaml.MappingNode {
		res:=copyNodePreserve(lvd); mergeInto(res, copyNodePreserve(rvd),appendArr,onlyExisting,deepArr,nullOnly,op); return res
	}
	if lvd.Kind==yaml.SequenceNode && rvd.Kind==yaml.SequenceNode {
		if deepArr {
			// merge by index
			res:=seqNode(); res.Style=lvd.Style
			max:=len(lvd.Content); if len(rvd.Content)>max{max=len(rvd.Content)}
			for i:=0;i<max;i++ {
				if i < len(lvd.Content) && i < len(rvd.Content) {
					if appendArr {
						// *+d observed [2,2] from [1] and [2]: deep merging scalars with append => [merged(index), rhs element appended?]
						// This behaviour is odd; approximate: merged element then append copy of rhs element
						m:=mergeValues(copyNodePreserve(lvd.Content[i]), copyNodePreserve(rvd.Content[i]),appendArr,onlyExisting,deepArr,nullOnly,op)
						res.Content=append(res.Content,m)
						res.Content=append(res.Content, copyNodePreserve(rvd.Content[i]))
					} else {
						res.Content=append(res.Content, mergeValues(copyNodePreserve(lvd.Content[i]), copyNodePreserve(rvd.Content[i]),appendArr,onlyExisting,deepArr,nullOnly,op))
					}
				} else if i < len(lvd.Content) {
					res.Content=append(res.Content, copyNodePreserve(lvd.Content[i]))
				} else {
					res.Content=append(res.Content, copyNodePreserve(rvd.Content[i]))
				}
			}
			return res
		}
		if appendArr {
			res:=seqNode(); res.Style=lvd.Style
			for _,ch:=range lvd.Content{res.Content=append(res.Content,copyNodePreserve(ch))}
			for _,ch:=range rvd.Content{res.Content=append(res.Content,copyNodePreserve(ch))}
			return res
		}
		return copyNodePreserve(rv)
	}
	// scalars / mismatched: if append and both scalars? yq may create array combining? We'll overwrite
	return copyNodePreserve(rv)
}
