func (e *FuncExpr) Eval(ctx *Ctx, in []*Cand) ([]*Cand, error) {
	name := normalizeFuncName(e.name)
	switch name {
	// functions requiring arg handling separately
	case "select", "map", "map_values", "filter", "has", "contains", "del", "pick", "omit", "test", "match", "capture", "sub", "split", "join", "sort_by", "unique_by", "group_by", "sort_keys", "with_entries", "any_c", "all_c", "error", "load", "load_str", "eval", "first", "collect", "setpath", "delpaths", "with_dtf", "tz", "explode", "system", "flatten", "tojson", "toyaml", "toxml":
		return evalArgFunc(ctx,in,e,name)
	}
	// zero-arg functions: if hasParens with arg for some (flatten/tojson handled above)
	if e.hasParens && e.arg != nil {
		// e.g. length(.) - original? Function names parsed by postfix may treat (.) as an arg applied first? Probe: length(.) on root returns? We'll treat as evaluating arg against in then applying zero func to results.
		// But for names in requiring list handled above. For zero names with parens, evaluate arg first.
		vals, err := e.arg.Eval(ctx,in)
		if err != nil {return nil,err}
		in = vals
	}
	return evalZeroFunc(ctx,in,name,e)
}

func normalizeFuncName(n string) string {
	switch n {
	case "to_string": return "tostring"
	case "to_number": return "tonumber"
	case "to_json": return "tojson"
	case "from_json": return "fromjson"
	case "to_yaml": return "toyaml"
	case "from_yaml": return "fromyaml"
	case "to_xml": return "toxml"
	case "from_xml": return "fromxml"
	case "splitdoc": return "split_doc"
	case "fileindex","file_index","fi": return "fileIndex"
	case "documentindex","document_index","di": return "documentIndex"
	case "filename","fileName","file_name": return "filename"
	case "type": return "tag"
	}
	return n
}

func evalZeroFunc(ctx *Ctx, in []*Cand, name string, e *FuncExpr) ([]*Cand,error){
	// Creation-type ops
	switch name {
	case "now":
		inputs:=effectiveInputs(ctx,in); var out []*Cand; ts:=time.Now().UTC().Truncate(time.Second)
		for _,c:=range inputs{ out=addCand(out,c.cloneWith(scalarNode("!!timestamp", formatTimestamp(ts)))) }
		return out,nil
	case "fileIndex":
		inputs:=effectiveInputs(ctx,in); var out []*Cand; for _,c:=range inputs{ out=addCand(out,c.cloneWith(intNode(int64(c.FileIdx)))) }; return out,nil
	case "documentIndex":
		inputs:=effectiveInputs(ctx,in); var out []*Cand; for _,c:=range inputs{ out=addCand(out,c.cloneWith(intNode(int64(c.DocIdx)))) }; return out,nil
	case "filename":
		inputs:=effectiveInputs(ctx,in); var out []*Cand; for _,c:=range inputs{ fn:=c.Filename; if fn==""{fn="-"}; out=addCand(out,c.cloneWith(stringNode(fn))) }; return out,nil
	}
	var out []*Cand
	for _, c := range in {
		res, err := applyZeroFuncToOne(ctx,c,name)
		if err != nil { return nil, err }
		out = addCands(out,res)
	}
	return out,nil
}

func applyZeroFuncToOne(ctx *Ctx, c *Cand, name string) ([]*Cand,error){
	n:=c.Node
	dn:=derefAlias(n)
	switch name {
	case "length":
		return []*Cand{c.cloneWith(intNode(int64(nodeLength(dn))))},nil
	case "keys":
