			// candidate is a key node itself, key returns its own decoded? Original ...|key behavior: for map keys recursion, key returns key value
			// If c.Key != nil and IsKey, result is key node itself as value candidate
			return []*Cand{c.cloneWith(copyNode(c.Node))},nil
		}
		if len(c.Path)==0 {
			return nil,nil
		}
		elem:=c.Path[len(c.Path)-1]
		return []*Cand{c.cloneWith(pathElemNode(elem))},nil
	case "is_key":
		return []*Cand{c.cloneWith(boolNode(c.IsKey))},nil
	case "sort":
		return sortCand(c)
	case "reverse":
		if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("node at path %s is not an array (it's a %s)", pathBracketString(c.Path), nodeTagOrDefault(dn)) }
		newSeq:=seqNode(); newSeq.Style=dn.Style; newSeq.Anchor=dn.Anchor
		for i:=len(dn.Content)-1;i>=0;i-- { newSeq.Content=append(newSeq.Content, copyNodePreserve(dn.Content[i])) }
		return []*Cand{c.cloneWith(newSeq)},nil
	case "shuffle":
		if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("node at path %s is not an array (it's a %s)", pathBracketString(c.Path), nodeTagOrDefault(dn)) }
		newSeq:=seqNode(); newSeq.Style=dn.Style
		indices:=shuffleIndices(len(dn.Content))
		for _,i:=range indices{ newSeq.Content=append(newSeq.Content, copyNodePreserve(dn.Content[i])) }
		return []*Cand{c.cloneWith(newSeq)},nil
	case "unique":
		if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("only arrays are supported for unique") }
		sorted, err:=sortNodeCopy(dn); if err!=nil{return nil,err}
		newSeq:=seqNode(); newSeq.Style=dn.Style
		for _,ch:=range sorted.Content { found:=false; for _,ex:=range newSeq.Content{ if nodesEqual(ch,ex){found=true;break}}; if !found{newSeq.Content=append(newSeq.Content,ch)} }
		return []*Cand{c.cloneWith(newSeq)},nil
	case "min","max":
		if dn.Kind!=yaml.SequenceNode {
			// original on map: "arrays not yet supported for comparison" because it tries values? For scalar? We'll handle: if map, compare its values? Scan showed min on map error arrays... because a value was array. If scalar, min itself?
			// Implement: if not seq, error based on attempting compare: if scalar return itself?
			// probe later; for now if scalar return c, if map try compare values and may error via nodeCmp
			if dn.Kind==yaml.ScalarNode { return []*Cand{c},nil }
			// map: collect values
			vals:=childCands(c,false); if len(vals)==0 {return []*Cand{c.cloneWith(nullNode())},nil}
			best:=vals[0]
			for _,v:=range vals[1:] { cmp,err:=nodeCmp(v.Node,best.Node); if err!=nil{return nil,err}; if (name=="min"&&cmp<0)||(name=="max"&&cmp>0){best=v} }
			return []*Cand{c.cloneWith(copyNode(best.Node))},nil
		}
		if len(dn.Content)==0 { return []*Cand{c.cloneWith(nullNode())},nil }
		best:=dn.Content[0]
		for _,ch:=range dn.Content[1:] { cmp,err:=nodeCmpForMinMax(ch,best); if err!=nil{return nil,err}; if (name=="min"&&cmp<0)||(name=="max"&&cmp>0){best=ch} }
		return []*Cand{c.cloneWith(copyNode(best))},nil
	case "tostring":
		if dn.Kind==yaml.ScalarNode {
			if dn.Tag=="!!str" { return []*Cand{c},nil } // keep style? tostring on string keeps node
			// numbers/bool/null => string value (null => ""? or "null") Probe later. Value for null node with "" gives "".
			s:=dn.Value
			return []*Cand{c.cloneWith(stringNode(s))},nil
		}
		// maps/seqs: original tostring on map returned map itself (scan showed root map output as map not string) Wait scan tostring on map output map yaml, because unwrapping? If it converted to string "a: 1..." then unwrap prints same text visually. Need distinguish via tag - probe later. We'll convert complex to yaml string.
		s,err:=encodeNodeToString(dn,"yaml",globalCfg.indent); if err!=nil{return nil,err}
		s=strings.TrimSuffix(s,"\n")
		// But if original indeed keeps map, tag test would tell. We'll keep conversion for now.
		return []*Cand{c.cloneWith(stringNode(s))},nil
	case "tonumber":
		if dn.Kind!=yaml.ScalarNode { return nil, fmt.Errorf("cannot convert node at path %s of tag %s to number", pathStringSpace(c.Path), nodeTagOrDefault(dn)) }
		if dn.Tag=="!!int"||dn.Tag=="!!float" { return []*Cand{c},nil }
		v, ok:=parseNumberValue(strings.TrimSpace(dn.Value))
		if !ok { return nil, fmt.Errorf("cannot convert node at path %s of tag %s to number", pathStringSpace(c.Path), nodeTagOrDefault(dn)) }
		switch t:=v.(type){ case int64: return []*Cand{c.cloneWith(intNode(t))},nil; case uint64: return []*Cand{c.cloneWith(uintNode(t))},nil; case float64: return []*Cand{c.cloneWith(floatNode(t))},nil }
		return []*Cand{c},nil
	case "tag":
		return []*Cand{c.cloneWith(stringNode(nodeTagOrDefault(c.Node)))},nil
	case "kind":
		return []*Cand{c.cloneWith(stringNode(kindString(c.Node)))},nil
	case "style":
		return []*Cand{c.cloneWith(stringNode(styleString(c.Node)))},nil
	case "anchor":
		return []*Cand{c.cloneWith(stringNode(c.Node.Anchor))},nil
	case "alias":
		// returns alias target's anchor? .a|alias on non-alias gave "123" (its own value!) in pprop: Input a:123 non-alias, alias op output 123. That suggests alias returns the candidate (?) if not alias returns itself? Wait pprop .a|alias output 123 - could be alias operator returns node referenced by alias, if node is not alias returns itself.
		if c.Node.Kind==yaml.AliasNode && c.Node.Alias!=nil {
			return []*Cand{c.cloneWith(stringNode(c.Node.Alias.Anchor))},nil
		}
		// probe showed 123 - maybe alias returns anchor name if exists else node value? Test in differential. For now mimic: if node has no alias, return itself?
		return []*Cand{c},nil
	case "line":
		return []*Cand{c.cloneWith(intNode(int64(c.Node.Line)))},nil
	case "column":
		return []*Cand{c.cloneWith(intNode(int64(c.Node.Column)))},nil
	case "head_comment": return []*Cand{c.cloneWith(stringNode(c.Node.HeadComment))},nil
	case "foot_comment": return []*Cand{c.cloneWith(stringNode(c.Node.FootComment))},nil
	case "line_comment": return []*Cand{c.cloneWith(stringNode(c.Node.LineComment))},nil
	case "path":
		seq:=seqNode()
		if len(c.Path)==0 { seq.Style=yaml.FlowStyle }
		for _,e:=range c.Path{ seq.Content=append(seq.Content,pathElemNode(e)) }
		res:=c.cloneWith(seq); res.Path=[]interface{}{}; res.Parent=nil; res.Key=nil; res.IsKey=false
		return []*Cand{res},nil
	case "parent":
		if c.Parent==nil { return nil,nil }
		return []*Cand{c.Parent},nil
	case "parents":
		seq:=seqNode(); seq.Style=0
		// parents list from immediate parent up to root, as nodes
		var parents []*Cand
		for p:=c.Parent;p!=nil;p=p.Parent{ parents=append(parents,p) }
		if len(parents)==0 { seq.Style=yaml.FlowStyle }
		for _,p:=range parents{ seq.Content=append(seq.Content, copyNodePreserve(p.Node)) }
		res:=c.cloneWith(seq); res.Path=c.Path // cloneWith kept path, but parents result candidate path []? probe later
		return []*Cand{res},nil
	case "root":
		return []*Cand{c.rootCand()},nil
	case "not":
		return []*Cand{c.cloneWith(boolNode(nodeIsFalsey(dn)))},nil
	case "any","all":
		if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("%s only supports arrays, was %s", name, nodeTagOrDefault(dn)) }
