	case "from_entries":
		if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("from entries only runs against arrays") }
		mp,err:=fromEntries(dn); if err!=nil{return nil,err}
		return []*Cand{c.cloneWith(mp)},nil
	case "downcase","upcase":
		if dn.Kind!=yaml.ScalarNode || dn.Tag!="!!str" { return nil, fmt.Errorf("cannot change case with %s, can only operate on strings.", nodeTagOrDefault(dn)) }
		s:=dn.Value; if name=="downcase"{s=strings.ToLower(s)}else{s=strings.ToUpper(s)}
		nn:=copyNode(c.Node); nn.Value=s; return []*Cand{c.cloneWith(nn)},nil
	case "trim":
		if dn.Kind!=yaml.ScalarNode || dn.Tag!="!!str" { return nil, fmt.Errorf("cannot trim %s, can only operate on strings.", nodeTagOrDefault(dn)) }
		nn:=copyNode(c.Node); nn.Value=strings.TrimSpace(dn.Value); return []*Cand{c.cloneWith(nn)},nil
	case "tojson","toyaml","toxml","fromjson","fromyaml","fromxml","to_props","from_props","to_csv","from_csv","to_tsv","from_tsv":
		// handled in arg funcs for tojson/toyaml/toxml (optional arg), others here
		return encodeDecodeZero(ctx,c,name)
	case "envsubst":
		return envsubstCand(c, nil)
	case "array_to_map":
		// Converts array to map using ??? Probe: array of scalars -> map with keys values? Implementation later in funcs2
		return arrayToMap(c)
	case "pivot":
		return pivotCand(c)
	case "split_doc":
		// Mark candidate as split doc: each element of a seq (?) becomes separate doc; if input is seq, return its elements with increasing DocIdx
		return splitDoc(c)
	case "flatten":
		// also handled in arg funcs if has arg, but zero will be called via arg func path (flatten in arg list) - not here
		return flattenCand(c,-1)
	}
	return nil, fmt.Errorf("bad expression, please check expression syntax")
}

func nodeCmpForMinMax(a,b *yaml.Node)(int,error){
	// min/max on scalars uses nodeCmp; for other kinds use sortCmp and error if arrays/maps? Original min on array containing arrays?
	if derefAlias(a).Kind!=yaml.ScalarNode || derefAlias(b).Kind!=yaml.ScalarNode {
		// try nodeCmp to produce "arrays not yet supported"
		return nodeCmp(a,b)
	}
	return nodeCmp(a,b)
}

func nodeLength(n *yaml.Node) int {
	switch n.Kind {
	case yaml.ScalarNode:
		if n.Tag=="!!null" { return 0 }
		if n.Tag=="!!str" { return len([]rune(n.Value)) }
		// numbers/bools: length of string representation? Observed 1==1|length -> 4 for true. Int 100 length 3?
		return len([]rune(n.Value))
	case yaml.SequenceNode: return len(n.Content)
	case yaml.MappingNode: return len(n.Content)/2
	}
	return 0
}

func sortCand(c *Cand)([]*Cand,error){
	dn:=derefAlias(c.Node)
	if dn.Kind==yaml.SequenceNode {
		sorted,err:=sortNodeCopy(dn); if err!=nil{return nil,err}
		return []*Cand{c.cloneWith(sorted)},nil
	}
	if dn.Kind==yaml.MappingNode {
		// yq sort on map: sorts its VALUES? Earlier "sort" on root map output reordered entries by values: b (map) before a (1) ... In first scan: input a:1 b:[...] c:hello -> sort output "b...,a...,c..." - it sorted entries by value using sortCmp where seq rank vs int vs string: seq rank 4 > int2 - order should int,string,seq if ascending rank - not match. Wait scan: input a:1, b:[3,1,2], c:hello => sort output b,a,c. That order corresponds sorting KEYS by...? No keys a,b,c ascending would a,b,c. Sorting values with yq compare that maybe compares string representations: "[3, 1, 2]" vs "1" vs "hello" lexical: "["(91) vs "1"(49) vs "h"(104) => 1,[,hello = a,b,c not.
		// Hmm maybe sort on map converts map to ... It output still a map but entries moved. Let's revisit later with probes. For now sort map by keys.
		res:=copyNodePreserve(dn)
		type pair struct{k,v *yaml.Node}
		var pairs []pair; for i:=0;i+1<len(res.Content);i+=2{pairs=append(pairs,pair{res.Content[i],res.Content[i+1]})}
		sort.SliceStable(pairs,func(i,j int)bool{return sortCmp(pairs[i].v,pairs[j].v)<0})
		res.Content=nil; for _,p:=range pairs{res.Content=append(res.Content,p.k,p.v)}
		return []*Cand{c.cloneWith(res)},nil
	}
	// scalar: return itself?
	return []*Cand{c},nil
}

func sortNodeCopy(n *yaml.Node)(*yaml.Node,error){
	res:=seqNode(); res.Style=n.Style; res.Anchor=n.Anchor
	for _,ch:=range n.Content{res.Content=append(res.Content,copyNodePreserve(ch))}
	sort.SliceStable(res.Content,func(i,j int)bool{return sortCmp(res.Content[i],res.Content[j])<0})
	return res,nil
}

func pathBracketString(p []interface{}) string {
	// "[a b]" in Go fmt of path? Error messages: node at path [] is not... and node at path [a] etc.
	if len(p)==0 {return "[]"}
	parts:=make([]string,len(p)); for i,e:=range p{parts[i]=fmt.Sprintf("%v",e)}
	return "["+strings.Join(parts," ")+"]"
}
func pathStringSpace(p []interface{}) string {
	// Error: cannot convert node at path  of tag... (empty when root, double space). For non-root, path like "a.b"? Probe later.
	if len(p)==0 {return ""}
	// yq prints path as space? Candidate string representation may be "a" for single. We'll use dot joined?
	parts:=make([]string,len(p)); for i,e:=range p{parts[i]=fmt.Sprintf("%v",e)}
	return strings.Join(parts,".")
}

func fromEntries(n *yaml.Node)(*yaml.Node,error){
	mp:=mapNode()
	for _,entry:=range n.Content{
		e:=derefAlias(entry)
		if e.Kind==yaml.MappingNode {
			var k,v *yaml.Node
			var nameN, valueN *yaml.Node
			for i:=0;i+1<len(e.Content);i+=2{
				kk:=e.Content[i].Value
				if kk=="key"{k=e.Content[i+1]} else if kk=="value"{v=e.Content[i+1]} else if kk=="name"{nameN=e.Content[i+1]} 
			}
			if k==nil && nameN!=nil {k=nameN}
			if k==nil { continue }
			if v==nil { v=nullNode() }
			_ = valueN
			mp.Content=append(mp.Content, copyNodePreserve(k), copyNodePreserve(v))
		} else if e.Kind==yaml.SequenceNode {
			if len(e.Content)>=2 { mp.Content=append(mp.Content, copyNodePreserve(e.Content[0]), copyNodePreserve(e.Content[1])) } else if len(e.Content)==1 { mp.Content=append(mp.Content, copyNodePreserve(e.Content[0]), nullNode()) }
		} else {
			// scalar entry => key with null?
			mp.Content=append(mp.Content, copyNodePreserve(e), nullNode())
		}
	}
	return mp,nil
}

var shuffleSeed int64 = 1
func shuffleIndices(n int) []int {
	// Deterministic pseudo-random shuffle cannot match original's random shuffle anyway (nondeterministic). Use Go math/rand with time seed via global rand.
	idx:=make([]int,n); for i:=range idx{idx[i]=i}
	// Use simple random based on time nanos for different runs (original also random)
	seed:=time.Now().UnixNano() + shuffleSeed; shuffleSeed++
	// xorshift
	state:=uint64(seed)
	next:=func()uint64{ state ^= state<<13; state ^= state>>7; state ^= state<<17; return state }
	for i:=n-1;i>0;i--{ j:=int(next()%uint64(i+1)); idx[i],idx[j]=idx[j],idx[i] }
	return idx
}

