	// Original usage: pick(["a","b"]) ? Or . as pick(.a, .b) gave {} in probes because paths evaluated to values not keys. Let's probe intended usage in tuning phase.
	// For now support: arg evaluated - if result is seq, its elements are keys (strings) or paths (seqs).
	// If arg is UnionExpr of path exprs, use their paths by evaluating with noCreate and gathering target Paths relative to input.
	var out []*Cand
	for _,c:=range in{
		paths,err:=extractPathsFromArg(ctx,c,e.arg); if err!=nil{return nil,err}
		dn:=derefAlias(c.Node)
		if dn.Kind!=yaml.MappingNode && dn.Kind!=yaml.SequenceNode {
			// pick on scalar -> {}? omit -> itself?
			if pick { out=addCand(out,c.cloneWith(mapNode())) } else { out=addCand(out,c) }
			continue
		}
		if pick {
			newNode:=pickPaths(dn,paths,c)
			out=addCand(out,c.cloneWith(newNode))
		} else {
			newNode:=copyNodePreserve(dn)
			// delete paths from copy: need to map paths to candidates in copy - implement via path deletion function on node
			for _,pth:=range paths{ deletePathFromNode(newNode,pth) }
			out=addCand(out,c.cloneWith(newNode))
		}
	}
	return out,nil
}
func extractPathsFromArg(ctx *Ctx,c *Cand,arg Expr)([][]interface{},error){
	// If arg is Union, evaluate each branch as a path generator (noCreate)
	if u,ok:=arg.(*UnionExpr); ok {
		var paths [][]interface{}
		for _,sub:=range u.exprs{
			vals,err:=sub.Eval(ctx.withNoCreate(),[]*Cand{c}); if err!=nil{return nil,err}
			for _,v:=range vals{
				// relative path: v.Path[len(c.Path):]
				if len(v.Path)>=len(c.Path){ paths=append(paths, append([]interface{}(nil), v.Path[len(c.Path):]...)) } else { paths=append(paths,v.Path) }
			}
		}
		// However earlier pick(.a,.s) gave {} meaning this interpretation may be wrong - if we return paths [a],[s], pick would give those keys, not {}. Wait probe input was s:hello a:1 and pick(.a,.s) gave {}. That suggests pick expects *values* (?) Let's keep this for now and revisit with dedicated probes.
		return paths,nil
	}
	vals,err:=arg.Eval(ctx.withNoCreate(),[]*Cand{c}); if err!=nil{return nil,err}
	var paths [][]interface{}
	for _,v:=range vals{
		vn:=derefAlias(v.Node)
		if vn.Kind==yaml.SequenceNode {
			// could be an array of keys, or a single path, or array of paths - heuristics: if elements are seqs -> paths; if elements scalars -> each is a top-level key path [elem]
			// But a single path arg like pick(["a","b"]) in yq means key a->b or keys a and b? Need probe.
			isPaths:=false; for _,ch:=range vn.Content{ if derefAlias(ch).Kind==yaml.SequenceNode{isPaths=true;break}}
			if isPaths { for _,ch:=range vn.Content{ paths=append(paths, pathFromSeqNode(ch)) } } else {
				// treat as list of keys
				for _,ch:=range vn.Content{ paths=append(paths, []interface{}{scalarPathElem(ch)}) }
			}
		} else if vn.Kind==yaml.ScalarNode {
			paths=append(paths, []interface{}{scalarPathElem(vn)})
		} else {
			// candidate from traversal: use its path
			if len(v.Path)>=len(c.Path){ paths=append(paths, append([]interface{}(nil), v.Path[len(c.Path):]...)) }
		}
	}
	return paths,nil
}
func scalarPathElem(n *yaml.Node) interface{} {
	n=derefAlias(n)
	if n.Tag=="!!int" { if iv,ok:=nodeIntValue(n); ok {return int(iv)} }
	v,_:=decodeScalar(n); if v==nil {return nil}; switch t:=v.(type){case int64: return int(t); default: return t}
}
func pathFromSeqNode(n *yaml.Node) []interface{} { var p []interface{}; for _,ch:=range derefAlias(n).Content{ p=append(p,scalarPathElem(ch)) }; return p }
func pickPaths(src *yaml.Node, paths [][]interface{}, base *Cand) *yaml.Node {
	// Build new node containing only picked paths
	if src.Kind==yaml.MappingNode {
		out:=mapNode()
		// preserve order of original keys that are picked (top level)
		// Group paths by first elem
		for i:=0;i+1<len(src.Content);i+=2{
			k:=src.Content[i]; v:=src.Content[i+1]
			elem:=pathElemFromKey(k)
			var sub [][]interface{}; includeAll:=false
			for _,p:=range paths{ if len(p)>0 && fmt.Sprintf("%v",p[0])==fmt.Sprintf("%v",elem){ if len(p)==1{includeAll=true}else{sub=append(sub,p[1:])} } }
			if includeAll { out.Content=append(out.Content,copyNodePreserve(k),copyNodePreserve(v)) } else if len(sub)>0 { out.Content=append(out.Content,copyNodePreserve(k),pickPaths(derefAlias(v),sub,base)) }
		}
		return out
	}
	if src.Kind==yaml.SequenceNode {
		out:=seqNode()
		for idx,ch:=range src.Content{
			var sub [][]interface{}; includeAll:=false
			for _,p:=range paths{ if len(p)>0 { if iv,ok:=p[0].(int); ok && iv==idx { if len(p)==1{includeAll=true}else{sub=append(sub,p[1:])} } } }
			if includeAll { out.Content=append(out.Content,copyNodePreserve(ch)) } else if len(sub)>0 { out.Content=append(out.Content,pickPaths(derefAlias(ch),sub,base)) }
		}
		return out
	}
	return copyNodePreserve(src)
}
func deletePathFromNode(root *yaml.Node, path []interface{}){
	if len(path)==0{return}
	cur:=derefAlias(root)
	if len(path)==1{
		if cur.Kind==yaml.MappingNode{ for i:=0;i+1<len(cur.Content);i+=2{ if keyMatches(cur.Content[i], path[0]){cur.Content=append(cur.Content[:i],cur.Content[i+2:]...); return} } }
		if cur.Kind==yaml.SequenceNode{ if idx,ok:=path[0].(int); ok && idx>=0 && idx<len(cur.Content){cur.Content=append(cur.Content[:idx],cur.Content[idx+1:]...)} }
		return
	}
	// recurse
	if cur.Kind==yaml.MappingNode{ for i:=0;i+1<len(cur.Content);i+=2{ if keyMatches(cur.Content[i],path[0]){ deletePathFromNode(cur.Content[i+1],path[1:]); return } } }
	if cur.Kind==yaml.SequenceNode{ if idx,ok:=path[0].(int); ok && idx>=0 && idx<len(cur.Content){ deletePathFromNode(cur.Content[idx],path[1:]) } }
}

func flattenCand(c *Cand, depth int)([]*Cand,error){
	dn:=derefAlias(c.Node)
	if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("only arrays are supported for flatten") }
	newSeq:=seqNode(); newSeq.Style=dn.Style
	var rec func(*yaml.Node,int)
	rec=func(n *yaml.Node,d int){
		nn:=derefAlias(n)
		if nn.Kind==yaml.SequenceNode && (depth<0 || d<depth){
			for _,ch:=range nn.Content{ rec(ch,d+1) }
		} else {
			newSeq.Content=append(newSeq.Content, copyNodePreserve(n))
		}
	}
	// flatten top level always one level? flatten with depth 0 returns same? Our rec starting children with d=0: if depth=0, children seqs not flattened because d<0 false - result same elements.
	for _,ch:=range dn.Content{ rec(ch,0) }
	return []*Cand{c.cloneWith(newSeq)},nil
}

func argSortByEtc(ctx *Ctx,in []*Cand,e *FuncExpr,name string)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		if name=="group_by" {
			// group_by on seq (or map values?) returns seq of seqs grouped by key, groups sorted by key
			if dn.Kind!=yaml.SequenceNode && dn.Kind!=yaml.MappingNode {
				// original sort_by on map reorders map entries - group_by on scalar?
				out=addCand(out,c); continue
			}
			children:=childCands(c,false)
			type item struct{ cand *Cand; key *yaml.Node }
			var items []item
			for _,ch:=range children{ vals,err:=e.arg.Eval(ctx.withNoCreate(),[]*Cand{ch}); if err!=nil{return nil,err}; var kn *yaml.Node; if len(vals)>0{kn=vals[0].Node}else{kn=nullNode()}; items=append(items,item{ch,kn}) }
			sort.SliceStable(items,func(i,j int)bool{return sortCmp(items[i].key,items[j].key)<0})
			seq:=seqNode()
			var curKey *yaml.Node; var curGroup *yaml.Node
			for _,it:=range items{
				if curKey==nil || !nodesEqual(curKey,it.key){ curKey=it.key; curGroup=seqNode(); seq.Content=append(seq.Content,curGroup) }
				curGroup.Content=append(curGroup.Content,copyNodePreserve(it.cand.Node))
			}
			out=addCand(out,c.cloneWith(seq)); continue
		}
		if dn.Kind==yaml.SequenceNode {
			children:=childCands(c,false)
			type item struct{ cand *Cand; keys []*yaml.Node }
			var items []item
			for _,ch:=range children{ vals,err:=e.arg.Eval(ctx.withNoCreate(),[]*Cand{ch}); if err!=nil{return nil,err}; var keys []*yaml.Node; for _,v:=range vals{keys=append(keys,v.Node)}; if len(keys)==0{keys=[]*yaml.Node{nullNode()}}; items=append(items,item{ch,keys}) }
			if name=="unique_by" {
				sort.SliceStable(items,func(i,j int)bool{return cmpKeys(items[i].keys,items[j].keys)<0})
				newSeq:=seqNode(); newSeq.Style=dn.Style
				var prev []*yaml.Node
				for _,it:=range items{ if prev==nil || cmpKeys(prev,it.keys)!=0{ newSeq.Content=append(newSeq.Content,copyNodePreserve(it.cand.Node)); prev=it.keys } }
				out=addCand(out,c.cloneWith(newSeq)); continue
			}
			// sort_by
			sort.SliceStable(items,func(i,j int)bool{return cmpKeys(items[i].keys,items[j].keys)<0})
			newSeq:=seqNode(); newSeq.Style=dn.Style; for _,it:=range items{newSeq.Content=append(newSeq.Content,copyNodePreserve(it.cand.Node))}
			out=addCand(out,c.cloneWith(newSeq)); continue
		}
		if dn.Kind==yaml.MappingNode {
			// sort_by on map: reorder entries by key computed from value? Earlier sort_by(.) on root map gave same as sort on map (b before a...) - sorting values.
			type pair struct{k,v *yaml.Node; keys []*yaml.Node}
			var pairs []pair
			for i:=0;i+1<len(dn.Content);i+=2{
				ch:=c.child(dn.Content[i+1],dn.Content[i],pathElemFromKey(dn.Content[i]),false)
				vals,err:=e.arg.Eval(ctx.withNoCreate(),[]*Cand{ch}); if err!=nil{return nil,err}
				var keys []*yaml.Node; for _,v:=range vals{keys=append(keys,v.Node)}; if len(keys)==0{keys=[]*yaml.Node{nullNode()}}
				pairs=append(pairs,pair{dn.Content[i],dn.Content[i+1],keys})
			}
			if name=="unique_by" {
				// unique on map error earlier? unique_by on map - treat as sorting then unique values to seq? Keep map unique by key computed
			}
			sort.SliceStable(pairs,func(i,j int)bool{return cmpKeys(pairs[i].keys,pairs[j].keys)<0})
			newMap:=mapNode(); for _,p:=range pairs{newMap.Content=append(newMap.Content,copyNodePreserve(p.k),copyNodePreserve(p.v))}
			out=addCand(out,c.cloneWith(newMap)); continue
		}
		// scalar
		if name=="unique_by" { return nil, fmt.Errorf("only arrays are supported for unique") }
		out=addCand(out,c)
	}
	return out,nil
}
func cmpKeys(a,b []*yaml.Node) int { for i:=0;i<len(a)&&i<len(b);i++{ if c:=sortCmp(a[i],b[i]); c!=0{return c} }; if len(a)<len(b){return -1}; if len(a)>len(b){return 1}; return 0 }

func argSortKeys(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		targets,err:=e.arg.Eval(ctx.withNoCreate(),[]*Cand{c}); if err!=nil{return nil,err}
		for _,t:=range targets{
			dn:=derefAlias(t.Node)
			if dn.Kind==yaml.MappingNode { sortMapKeysInPlace(dn) }
		}
		out=addCand(out,c)
	}
	return out,nil
}
func sortMapKeysInPlace(m *yaml.Node){
	type pair struct{k,v *yaml.Node}
	var pairs []pair; for i:=0;i+1<len(m.Content);i+=2{pairs=append(pairs,pair{m.Content[i],m.Content[i+1]})}
	sort.SliceStable(pairs,func(i,j int)bool{return sortCmp(pairs[i].k,pairs[j].k)<0})
	m.Content=nil; for _,p:=range pairs{m.Content=append(m.Content,p.k,p.v)}
}

func argWithEntries(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	// with_entries(f): to_entries | map(f) | from_entries ; but f may be assignments to .key/.value on entry maps
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		if dn.Kind!=yaml.MappingNode {
			// apply through to_entries error? We'll return error like to_entries?
			// Original with_entries on non-map likely error from to_entries.
			return nil, fmt.Errorf("to_entries only runs against maps, was %s", nodeTagOrDefault(dn))
		}
		// Build entries seq candidate
		entriesCandRes,err:=applyZeroFuncToOne(ctx,c,"to_entries"); if err!=nil{return nil,err}
		entriesCand:=entriesCandRes[0]
		// map(f) over entries
		mapE:=&FuncExpr{name:"map",arg:e.arg,hasParens:true}
		mapped,err:=argMap(ctx,[]*Cand{entriesCand},mapE,false); if err!=nil{return nil,err}
		// from_entries on mapped
		for _,m:=range mapped{
			mp,err:=fromEntries(derefAlias(m.Node)); if err!=nil{return nil,err}
			out=addCand(out,c.cloneWith(mp))
		}
	}
	return out,nil
}

func argAnyAllC(ctx *Ctx,in []*Cand,e *FuncExpr,name string)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		which:="any"; if name=="all_c"{which="all"}
		if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("%s only supports arrays, was %s", which, nodeTagOrDefault(dn)) }
		res:= (which=="all")
		for _,ch:=range childCands(c,false){
			vals,err:=e.arg.Eval(ctx.withNoCreate(),[]*Cand{ch}); if err!=nil{return nil,err}
			truthy:=false; for _,v:=range vals{ if !nodeIsFalsey(v.Node){truthy=true;break} }
			if which=="any" && truthy {res=true;break}
			if which=="all" && !truthy {res=false;break}
		}
		out=addCand(out,c.cloneWith(boolNode(res)))
	}
	return out,nil
}

func argError(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	vals,err:=e.arg.Eval(ctx, effectiveInputs(ctx,in)); if err!=nil{return nil,err}
	if len(vals)==0 { return nil, fmt.Errorf("aborted") }
	v:=vals[0].Node
	if v.Kind==yaml.ScalarNode {
		if v.Tag=="!!null" { return nil, fmt.Errorf("aborted") }
		return nil, fmt.Errorf("%s", v.Value)
	}
	s,_:=encodeNodeToString(v,"yaml",2); return nil, fmt.Errorf("%s", strings.TrimSpace(s))
}

func argFirst(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	vals,err:=e.arg.Eval(ctx,in); if err!=nil{return nil,err}
	if len(vals)==0 {return nil,nil}
	return []*Cand{vals[0]},nil
}

func argSetpath(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	args,kind:=blockOrUnionArgs(e.arg)
	if kind=="union" { return nil, fmt.Errorf("SETPATH must be given a block (;), got UNION instead") }
	if kind!="block" || len(args)<2 {
		// single arg? Original message maybe similar for non-block types: probe in tuning
		if kind=="single" { return nil, fmt.Errorf("SETPATH must be given a block (;), got %s instead", opNameOfExpr(e.arg)) }
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	var out []*Cand
	for _,c:=range in{
		pathVals,err:=args[0].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		valVals,err:=args[1].Eval(ctx.withNoCreate(),[]*Cand{c}); if err!=nil{return nil,err}
		if len(pathVals)==0 || len(valVals)==0 { out=addCand(out,c); continue }
		for _,pv:=range pathVals{
			pth:=pathFromNodeValue(pv.Node)
			for _,vv:=range valVals{
				// navigate/create path in c.Node and set
				if err:=setPathInCand(ctx,c,pth,vv.Node); err!=nil{return nil,err}
			}
		}
		out=addCand(out,c)
	}
	return out,nil
}
func opNameOfExpr(e Expr) string {
	switch e.(type){case *UnionExpr: return "UNION"; case *BlockExpr: return "BLOCK"; case *CollectExpr: return "COLLECT"; case *LiteralExpr: return "VALUE"; case *StringExpr: return "VALUE"; default: return "VALUE"}
}
func pathFromNodeValue(n *yaml.Node) []interface{} {
	n=derefAlias(n)
	if n.Kind==yaml.SequenceNode { var p []interface{}; for _,ch:=range n.Content{ p=append(p,scalarPathElem(ch))}; return p }
	if n.Kind==yaml.ScalarNode { return []interface{}{scalarPathElem(n)} }
	return nil
}
func setPathInCand(ctx *Ctx,c *Cand,pth []interface{}, val *yaml.Node) error {
	if len(pth)==0 { replaceNodeContents(c.Node, copyNodeForAssign(val,c.Node)); return nil }
	// Build segs and traverse with create from c, then assign
	var segs []pathSeg
	for _,elem:=range pth{
		switch t:=elem.(type){case string: segs=append(segs,pathSeg{kind:"key",key:t}); case int: segs=append(segs,pathSeg{kind:"index",index:t,hasIndex:true}); case int64: segs=append(segs,pathSeg{kind:"index",index:int(t),hasIndex:true}); default: segs=append(segs,pathSeg{kind:"key",key:fmt.Sprintf("%v",t)})}
	}
	pe:=&PathExpr{segs:segs}
	targets,err:=pe.Eval(ctx.withCreate(),[]*Cand{c}); if err!=nil{return err}
	for _,t:=range targets{ assignToCand(t, copyNodeForAssign(val,t.Node)) }
	return nil
}
func argDelpaths(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		for _,v:=range vals{
			vn:=derefAlias(v.Node)
			if vn.Kind==yaml.SequenceNode {
				// array of paths
				var paths [][]interface{}
				for _,ch:=range vn.Content{ paths=append(paths,pathFromNodeValue(ch)) }
				// sort longer / indices desc for deletion? deletePathFromNode on original c.Node
				sort.SliceStable(paths,func(i,j int)bool{return len(paths[i])>len(paths[j])})
				for _,pth:=range paths{ deletePathFromNode(c.Node, pth) }
			}
		}
		out=addCand(out,c)
	}
	return out,nil
}

func argWithDtf(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	args,kind:=blockOrUnionArgs(e.arg)
	if len(args)<2 {
		return nil, fmt.Errorf("must provide a date time format string and an expression, e.g. with_dtf(\"Monday, 02-Jan-06 at 3:04PM MST\"; <exp>)")
	}
	_ = kind
	// first arg evaluated to format string (against in)
	vals:=effectiveInputs(ctx,in)
	fmts,err:=args[0].Eval(ctx,vals); if err!=nil{return nil,err}
	format:=""
	if len(fmts)>0 { format=scalarStringValue(fmts[0].Node) }
	child:=ctx.childCtx(); child.dtf=format
	// remaining arg expression: if more than 2, join? Use last?
	expr:=args[1]
	if len(args)>2 { expr=&BlockExpr{exprs:args[1:]} }
	return expr.Eval(child,in)
}

func argTz(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		if len(vals)==0 {continue}
		tzname:=scalarStringValue(vals[0].Node)
		loc,err:=time.LoadLocation(tzname)
		if err!=nil { return nil, fmt.Errorf("could not load tz [%s]: %s", tzname, err.Error()) }
		dn:=derefAlias(c.Node)
		t,err:=parseTimestamp(dn.Value); if err!=nil{return nil,err}
		newT:=t.In(loc)
		out=addCand(out,c.cloneWith(scalarNode("!!timestamp", formatTimestamp(newT))))
	}
	return out,nil
}

func argExplode(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		targets,err:=e.arg.Eval(ctx.withNoCreate(),[]*Cand{c}); if err!=nil{return nil,err}
		warnMerge:=false
		for _,t:=range targets{
			changed:=explodeInPlace(t.Node, globalCfg.yamlFixMergeAnchor)
			if changed{warnMerge=true}
		}
		if warnMerge && !globalCfg.yamlFixMergeAnchor {
			logWarn("--yaml-fix-merge-anchor-to-spec is false; causing merge anchors to override the existing values which isn't to the yaml spec. This flag will default to true in late 2025.")
		}
		out=addCand(out,c)
	}
	return out,nil
}

// explodeInPlace expands aliases and merge keys and strips anchors in place (modifying node tree). Returns true if a merge anchor (<< with anchored value) was encountered.
func explodeInPlace(n *yaml.Node, fixSpec bool) bool {
	foundMergeAnchor:=false
	var rec func(*yaml.Node)
	rec=func(node *yaml.Node){
		if node==nil{return}
		if node.Kind==yaml.AliasNode { return } // handled by parent replacement
		node.Anchor=""
		if node.Kind==yaml.MappingNode{
			// process merge keys
			// build new content
			var newContent []*yaml.Node
			// First explode children (except merge values anchored - handle)
			for i:=0;i+1<len(node.Content);i+=2{
				k:=node.Content[i]; v:=node.Content[i+1]
				if k.Tag=="!!merge" || k.Value=="<<" {
					// merge source(s)
					sources:=mergeSourceMaps(v)
					if v.Anchor!="" || (v.Kind!=yaml.AliasNode && v.Anchor!="") { foundMergeAnchor=true }
					// Detect anchored merge value: v had an anchor before?
					// yaml parser puts anchor on value node (map with Anchor)
					// If fixSpec=false and source was defined inline with anchor on merge value, old yq skipped merging it into this map (observed c losing p)
					// Check: if v is a MappingNode with Anchor != "" (not yet cleared? we cleared only node, not children)
					isAnchoredDefinition := v.Anchor!=""
					if isAnchoredDefinition { foundMergeAnchor=true }
					if !fixSpec && isAnchoredDefinition {
						// do not merge into this map, but still explode source for other references? Source map node is same object referenced by aliases elsewhere; exploding it (strip anchor) later when alias replaced - need keep anchor for now? Aliases pointing to it will be replaced by copy in their parents before anchor stripped globally? Our single pass top-down might strip.
						// Explode contents of source maps but keep them aside; they are still referenced.
						for _,s:=range sources{ rec(s) }
						continue
					}
					for _,src:=range sources{
						// for each entry in src copy
						srcCopy:=copyNodePreserve(src)
						rec(srcCopy)
						for j:=0;j+1<len(srcCopy.Content);j+=2{
							mk:=srcCopy.Content[j]; mv:=srcCopy.Content[j+1]
							// if key already exists in newContent or remaining original explicit keys, spec: explicit wins (skip). Old behaviour (?) merge anchor overrides - if anchored definition and !fix, override handled above skipped entirely, so not.
							if mapHasKey(newContent,mk) || mapHasExplicitKey(node,mk,i) {
								if !fixSpec && isAnchoredDefinition {
									// override existing in newContent
									replaceMapValue(&newContent,mk,mv)
								}
								continue
							}
							newContent=append(newContent,mk,mv)
						}
					}
					continue
				}
				// normal entry: explode key/value, replace alias value with copy of target
				rec(k)
				if v.Kind==yaml.AliasNode && v.Alias!=nil {
					tgtCopy:=copyNodePreserve(v.Alias)
					rec(tgtCopy)
					newContent=append(newContent,k,tgtCopy)
				} else {
					rec(v)
					newContent=append(newContent,k,v)
				}
			}
			node.Content=newContent
			return
		}
		if node.Kind==yaml.SequenceNode{
			for idx,ch:=range node.Content{
				if ch.Kind==yaml.AliasNode && ch.Alias!=nil { tgt:=copyNodePreserve(ch.Alias); rec(tgt); node.Content[idx]=tgt } else { rec(ch) }
			}
			return
		}
		// scalar: nothing
	}
	if n.Kind==yaml.AliasNode && n.Alias!=nil {
		tgt:=copyNodePreserve(n.Alias)
		replaceNodeContents(n,tgt)
		rec(n)
	} else {
		rec(n)
	}
	return foundMergeAnchor
}
func mergeSourceMaps(v *yaml.Node) []*yaml.Node {
	var out []*yaml.Node
	dv:=derefAlias(v)
	if dv.Kind==yaml.MappingNode{ out=append(out,dv) } else if dv.Kind==yaml.SequenceNode{ for _,ch:=range dv.Content{ dc:=derefAlias(ch); if dc.Kind==yaml.MappingNode{out=append(out,dc)} } }
	return out
}
func mapHasKey(content []*yaml.Node, k *yaml.Node) bool { for i:=0;i+1<len(content);i+=2{ if nodesEqual(content[i],k){return true} }; return false }
func mapHasExplicitKey(node *yaml.Node,k *yaml.Node, upTo int) bool {
	// check all explicit (non-merge) keys in original node
	for i:=0;i+1<len(node.Content);i+=2{ kk:=node.Content[i]; if kk.Value=="<<"||kk.Tag=="!!merge"{continue}; if nodesEqual(kk,k){return true} }
