func decodeStringCand(c *Cand, format string)([]*Cand,error){
	dn:=derefAlias(c.Node)
	if dn.Kind!=yaml.ScalarNode {
		// Original fromjson on map gave EOF: it tries to decode node Value "" as json => EOF.
		s:=""
		node,err:=decodeStringToNode(s,format,c); if err!=nil{return nil,err}; return []*Cand{c.cloneWith(node)},nil
	}
