func argSetpath(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	args,kind:=blockOrUnionArgs(e.arg)
	if kind=="union" { return nil, fmt.Errorf("SETPATH must be given a block (;), got UNION instead") }
	if kind!="block" || len(args)<2 {
		// single arg? Original message maybe similar for non-block types: probe in tuning
		if kind=="single" { return nil, fmt.Errorf("SETPATH must be given a block (;), got %s instead", opNameOfExpr(e.arg)) }
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	var out []*Cand
	for _,c:=range in{
		pathVals,err:=args[0].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		valVals,err:=args[1].Eval(ctx.withNoCreate(),[]*Cand{c}); if err!=nil{return nil,err}
		if len(pathVals)==0 || len(valVals)==0 { out=addCand(out,c); continue }
		for _,pv:=range pathVals{
			pth:=pathFromNodeValue(pv.Node)
			for _,vv:=range valVals{
				// navigate/create path in c.Node and set
				if err:=setPathInCand(ctx,c,pth,vv.Node); err!=nil{return nil,err}
			}
		}
		out=addCand(out,c)
	}
	return out,nil
}
func opNameOfExpr(e Expr) string {
	switch e.(type){case *UnionExpr: return "UNION"; case *BlockExpr: return "BLOCK"; case *CollectExpr: return "COLLECT"; case *LiteralExpr: return "VALUE"; case *StringExpr: return "VALUE"; default: return "VALUE"}
}
func pathFromNodeValue(n *yaml.Node) []interface{} {
	n=derefAlias(n)
	if n.Kind==yaml.SequenceNode { var p []interface{}; for _,ch:=range n.Content{ p=append(p,scalarPathElem(ch))}; return p }
	if n.Kind==yaml.ScalarNode { return []interface{}{scalarPathElem(n)} }
	return nil
}
func setPathInCand(ctx *Ctx,c *Cand,pth []interface{}, val *yaml.Node) error {
	if len(pth)==0 { replaceNodeContents(c.Node, copyNodeForAssign(val,c.Node)); return nil }
	// Build segs and traverse with create from c, then assign
	var segs []pathSeg
	for _,elem:=range pth{
		switch t:=elem.(type){case string: segs=append(segs,pathSeg{kind:"key",key:t}); case int: segs=append(segs,pathSeg{kind:"index",index:t,hasIndex:true}); case int64: segs=append(segs,pathSeg{kind:"index",index:int(t),hasIndex:true}); default: segs=append(segs,pathSeg{kind:"key",key:fmt.Sprintf("%v",t)})}
	}
	pe:=&PathExpr{segs:segs}
	targets,err:=pe.Eval(ctx.withCreate(),[]*Cand{c}); if err!=nil{return err}
	for _,t:=range targets{ assignToCand(t, copyNodeForAssign(val,t.Node)) }
	return nil
}
func argDelpaths(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		for _,v:=range vals{
			vn:=derefAlias(v.Node)
			if vn.Kind==yaml.SequenceNode {
				// array of paths
				var paths [][]interface{}
				for _,ch:=range vn.Content{ paths=append(paths,pathFromNodeValue(ch)) }
				// sort longer / indices desc for deletion? deletePathFromNode on original c.Node
				sort.SliceStable(paths,func(i,j int)bool{return len(paths[i])>len(paths[j])})
				for _,pth:=range paths{ deletePathFromNode(c.Node, pth) }
			}
		}
		out=addCand(out,c)
	}
	return out,nil
}

func argWithDtf(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	args,kind:=blockOrUnionArgs(e.arg)
	if len(args)<2 {
		return nil, fmt.Errorf("must provide a date time format string and an expression, e.g. with_dtf(\"Monday, 02-Jan-06 at 3:04PM MST\"; <exp>)")
	}
	_ = kind
	// first arg evaluated to format string (against in)
	vals:=effectiveInputs(ctx,in)
	fmts,err:=args[0].Eval(ctx,vals); if err!=nil{return nil,err}
	format:=""
	if len(fmts)>0 { format=scalarStringValue(fmts[0].Node) }
	child:=ctx.childCtx(); child.dtf=format
	// remaining arg expression: if more than 2, join? Use last?
	expr:=args[1]
	if len(args)>2 { expr=&BlockExpr{exprs:args[1:]} }
	return expr.Eval(child,in)
}

func argTz(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		if len(vals)==0 {continue}
		tzname:=scalarStringValue(vals[0].Node)
		loc,err:=time.LoadLocation(tzname)
		if err!=nil { return nil, fmt.Errorf("could not load tz [%s]: %s", tzname, err.Error()) }
		dn:=derefAlias(c.Node)
		t,err:=parseTimestamp(dn.Value); if err!=nil{return nil,err}
		newT:=t.In(loc)
		out=addCand(out,c.cloneWith(scalarNode("!!timestamp", formatTimestamp(newT))))
	}
	return out,nil
}

func argExplode(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		targets,err:=e.arg.Eval(ctx.withNoCreate(),[]*Cand{c}); if err!=nil{return nil,err}
		warnMerge:=false
		for _,t:=range targets{
			changed:=explodeInPlace(t.Node, globalCfg.yamlFixMergeAnchor)
			if changed{warnMerge=true}
		}
		if warnMerge && !globalCfg.yamlFixMergeAnchor {
			logWarn("--yaml-fix-merge-anchor-to-spec is false; causing merge anchors to override the existing values which isn't to the yaml spec. This flag will default to true in late 2025.")
		}
		out=addCand(out,c)
	}
	return out,nil
}

// explodeInPlace expands aliases and merge keys and strips anchors in place (modifying node tree). Returns true if a merge anchor (<< with anchored value) was encountered.
func explodeInPlace(n *yaml.Node, fixSpec bool) bool {
	foundMergeAnchor:=false
	var rec func(*yaml.Node)
	rec=func(node *yaml.Node){
		if node==nil{return}
		if node.Kind==yaml.AliasNode { return } // handled by parent replacement
		node.Anchor=""
		if node.Kind==yaml.MappingNode{
			// process merge keys
			// build new content
			var newContent []*yaml.Node
			// First explode children (except merge values anchored - handle)
			for i:=0;i+1<len(node.Content);i+=2{
				k:=node.Content[i]; v:=node.Content[i+1]
				if k.Tag=="!!merge" || k.Value=="<<" {
					// merge source(s)
					sources:=mergeSourceMaps(v)
					if v.Anchor!="" || (v.Kind!=yaml.AliasNode && v.Anchor!="") { foundMergeAnchor=true }
					// Detect anchored merge value: v had an anchor before?
					// yaml parser puts anchor on value node (map with Anchor)
					// If fixSpec=false and source was defined inline with anchor on merge value, old yq skipped merging it into this map (observed c losing p)
					// Check: if v is a MappingNode with Anchor != "" (not yet cleared? we cleared only node, not children)
					isAnchoredDefinition := v.Anchor!=""
					if isAnchoredDefinition { foundMergeAnchor=true }
					if !fixSpec && isAnchoredDefinition {
						// do not merge into this map, but still explode source for other references? Source map node is same object referenced by aliases elsewhere; exploding it (strip anchor) later when alias replaced - need keep anchor for now? Aliases pointing to it will be replaced by copy in their parents before anchor stripped globally? Our single pass top-down might strip.
						// Explode contents of source maps but keep them aside; they are still referenced.
						for _,s:=range sources{ rec(s) }
						continue
					}
					for _,src:=range sources{
						// for each entry in src copy
						srcCopy:=copyNodePreserve(src)
						rec(srcCopy)
						for j:=0;j+1<len(srcCopy.Content);j+=2{
							mk:=srcCopy.Content[j]; mv:=srcCopy.Content[j+1]
							// if key already exists in newContent or remaining original explicit keys, spec: explicit wins (skip). Old behaviour (?) merge anchor overrides - if anchored definition and !fix, override handled above skipped entirely, so not.
							if mapHasKey(newContent,mk) || mapHasExplicitKey(node,mk,i) {
								if !fixSpec && isAnchoredDefinition {
									// override existing in newContent
									replaceMapValue(&newContent,mk,mv)
								}
								continue
							}
							newContent=append(newContent,mk,mv)
						}
					}
					continue
				}
				// normal entry: explode key/value, replace alias value with copy of target
				rec(k)
				if v.Kind==yaml.AliasNode && v.Alias!=nil {
					tgtCopy:=copyNodePreserve(v.Alias)
					rec(tgtCopy)
					newContent=append(newContent,k,tgtCopy)
				} else {
					rec(v)
					newContent=append(newContent,k,v)
				}
			}
			node.Content=newContent
			return
		}
		if node.Kind==yaml.SequenceNode{
			for idx,ch:=range node.Content{
				if ch.Kind==yaml.AliasNode && ch.Alias!=nil { tgt:=copyNodePreserve(ch.Alias); rec(tgt); node.Content[idx]=tgt } else { rec(ch) }
			}
			return
		}
		// scalar: nothing
	}
	if n.Kind==yaml.AliasNode && n.Alias!=nil {
		tgt:=copyNodePreserve(n.Alias)
		replaceNodeContents(n,tgt)
		rec(n)
	} else {
		rec(n)
	}
	return foundMergeAnchor
}
func mergeSourceMaps(v *yaml.Node) []*yaml.Node {
	var out []*yaml.Node
	dv:=derefAlias(v)
	if dv.Kind==yaml.MappingNode{ out=append(out,dv) } else if dv.Kind==yaml.SequenceNode{ for _,ch:=range dv.Content{ dc:=derefAlias(ch); if dc.Kind==yaml.MappingNode{out=append(out,dc)} } }
	return out
}
func mapHasKey(content []*yaml.Node, k *yaml.Node) bool { for i:=0;i+1<len(content);i+=2{ if nodesEqual(content[i],k){return true} }; return false }
func mapHasExplicitKey(node *yaml.Node,k *yaml.Node, upTo int) bool {
	// check all explicit (non-merge) keys in original node
	for i:=0;i+1<len(node.Content);i+=2{ kk:=node.Content[i]; if kk.Value=="<<"||kk.Tag=="!!merge"{continue}; if nodesEqual(kk,k){return true} }
	return false
}
func replaceMapValue(content *[]*yaml.Node,k,v *yaml.Node){ for i:=0;i+1<len(*content);i+=2{ if nodesEqual((*content)[i],k){(*content)[i+1]=v; return} }; *content=append(*content,k,v) }

func argSystem(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	if !globalCfg.securityEnableSystem {
		return nil, fmt.Errorf("system operator is disabled by default, please enable it with --security-enable-system-operator")
	}
	// system("cmd") runs command, returns output?
	var out []*Cand
	for _,c:=range effectiveInputs(ctx,in){
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		for _,v:=range vals{
			cmdStr:=scalarStringValue(v.Node)
			cmd:=exec.Command("sh","-c",cmdStr)
			output,err:=cmd.Output()
			if err!=nil{ return nil, err }
			out=addCand(out,c.cloneWith(stringNode(strings.TrimSuffix(string(output),"\n"))))
		}
	}
	return out,nil
}

func argLoad(ctx *Ctx,in []*Cand,e *FuncExpr,isStr bool)([]*Cand,error){
	if globalCfg.securityDisableFileOps {
		return nil, fmt.Errorf("file operations have been disabled")
	}
	var out []*Cand
	for _,c:=range effectiveInputs(ctx,in){
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		if len(vals)==0 { return nil, fmt.Errorf("filename expression returned nil") }
		for _,v:=range vals{
			fname:=scalarStringValue(v.Node)
			if fname=="" && v.Node.Kind==yaml.ScalarNode && v.Node.Tag=="!!null" { return nil, fmt.Errorf("filename expression returned nil") }
			if isStr {
				data,err:=os.ReadFile(fname); if err!=nil{return nil,err}
				out=addCand(out,c.cloneWith(stringNode(string(data)))); continue
			}
			docs,err:=loadFileAsDocs(fname,c)
			if err!=nil{return nil,err}
			out=addCands(out,docs)
		}
	}
	return out,nil
}

func argEval(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	// Evaluate arg to get expression string(s): arg evaluated against each input? Original eval(".a") at root returns .a evaluated against input.
	// If arg is a string literal, eval arg will return that string per input.
	for _,c:=range effectiveInputs(ctx,in){
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		for _,v:=range vals{
			exprStr:=scalarStringValue(v.Node)
			parsed,err:=parseExpression(exprStr); if err!=nil{return nil,err}
			res,err:=parsed.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
			out=addCands(out,res)
		}
	}
	return out,nil
}

//_regex
func regexArgs(ctx *Ctx,c *Cand,arg Expr)(string,string,error){
	// returns pattern, flags (or replacement for sub handled separately)
	args,kind:=blockOrUnionArgs(arg)
	if kind=="block" && len(args)>=2 {
		pv,err:=args[0].Eval(ctx,[]*Cand{c}); if err!=nil{return "","",err}
		fv,err:=args[1].Eval(ctx,[]*Cand{c}); if err!=nil{return "","",err}
		p:=""; if len(pv)>0{p=scalarStringValue(pv[0].Node)}; f:=""; if len(fv)>0{f=scalarStringValue(fv[0].Node)}
		return p,f,nil
	}
	vals,err:=arg.Eval(ctx,[]*Cand{c}); if err!=nil{return "","",err}
	if len(vals)==0 {return "","",nil}
	// If union produced multiple vals, first pattern second flags/replacement
	p:=scalarStringValue(vals[0].Node); f:=""; if len(vals)>1{f=scalarStringValue(vals[1].Node)}
	return p,f,nil
}
func compileRegex(pattern, flags string)(*regexp.Regexp,error){
	// flags: yq match/test second arg may be "g" (global) or ??? 'i' invalid as quoted probe: Error: 'i' is not a valid option for match...
	// Valid options appear to be "g" only? and maybe "i" handled via (?i)
	for _,ch:=range flags{
		if ch!='g' {
			return nil, fmt.Errorf("'%c' is not a valid option for match. To ignore case, use an expression like match(\"(?i)cat\")", ch)
		}
	}
	return regexp.Compile(pattern)
}
func argRegex(ctx *Ctx,in []*Cand,e *FuncExpr,name string)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		// test/match/capture operate on strings; if not string? Convert?
		pattern,flags,err:=regexArgs(ctx,c,e.arg); if err!=nil{return nil,err}
		re,err:=compileRegex(pattern,flags); if err!=nil{return nil,err}
		s:=dn.Value
		if dn.Kind!=yaml.ScalarNode { s="" }
		switch name {
		case "test":
			out=addCand(out,c.cloneWith(boolNode(re.MatchString(s))))
		case "match":
			// Find first or all if g flag
			if strings.Contains(flags,"g") {
				// original with g still returned single match object in probe (for l+ only one) - if multiple matches, returns multiple candidates?
				matches:=re.FindAllStringSubmatchIndex(s,-1)
				if len(matches)==0 { /* return no candidate? jq match with no match returns... yq returns? We'll return null cand? Probe later */ out=addCand(out,c.cloneWith(nullNode())); continue }
				for _,m:=range matches{ out=addCand(out,c.cloneWith(matchObject(re,s,m))) }
			} else {
				m:=re.FindStringSubmatchIndex(s)
				if m==nil { out=addCand(out,c.cloneWith(nullNode())); continue }
				out=addCand(out,c.cloneWith(matchObject(re,s,m)))
			}
		case "capture":
			m:=re.FindStringSubmatch(s)
			if m==nil { out=addCand(out,c.cloneWith(nullNode())); continue }
			mp:=mapNode()
			names:=re.SubexpNames()
			for i,nameCap:=range names{ if i==0||nameCap==""{continue}; mp.Content=append(mp.Content,stringNode(nameCap),stringNode(m[i])) }
			out=addCand(out,c.cloneWith(mp))
		}
	}
	return out,nil
}
func matchObject(re *regexp.Regexp,s string,m []int) *yaml.Node {
	// {string,offset,length,captures:[{string,offset,length,name}...]}
	full:=s[m[0]:m[1]]
	caps:=seqNode(); caps.Style=yaml.FlowStyle
	names:=re.SubexpNames()
	// captures only for groups? Probe l+ no groups => []
	for i:=1;i<len(m)/2;i++{
		if m[2*i]<0 { continue }
		capNode:=mapNode(
			stringNode("string"), stringNode(s[m[2*i]:m[2*i+1]]),
			stringNode("offset"), intNode(int64(m[2*i])),
			stringNode("length"), intNode(int64(m[2*i+1]-m[2*i])),
			stringNode("name"), stringNode(names[i]),
		)
		// yq capture object format may omit name if empty? Probe later.
		if names[i]=="" {
			// remove name pair?
			capNode.Content=capNode.Content[:6]
		}
		caps.Content=append(caps.Content,capNode)
		caps.Style=0
	}
	return mapNode(
		stringNode("string"), stringNode(full),
		stringNode("offset"), intNode(int64(m[0])),
		stringNode("length"), intNode(int64(m[1]-m[0])),
		stringNode("captures"), caps,
	)
}
func argSub(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		if dn.Kind!=yaml.ScalarNode || dn.Tag!="!!str" {
			// what error? defer
			return nil, fmt.Errorf("cannot substitute with %s, can only substitute strings", nodeTagOrDefault(dn))
		}
		// args: pattern, replacement (via union or block)
		args,kind:=blockOrUnionArgs(e.arg)
		var pattern, repl string
		var flags string
		if (kind=="block"||kind=="union") && len(args)>=1 {
			pv,err:=args[0].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}; if len(pv)>0{pattern=scalarStringValue(pv[0].Node)}
			if len(args)>=2 { rv,err:=args[1].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}; if len(rv)>0{repl=scalarStringValue(rv[0].Node)} }
			if len(args)>=3 { fv,err:=args[2].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}; if len(fv)>0{flags=scalarStringValue(fv[0].Node)} }
		} else {
			p,f,err:=regexArgs(ctx,c,e.arg); if err!=nil{return nil,err}; pattern=p; repl=f
		}
		_ = flags
		re,err:=compileRegex(pattern,""); if err!=nil{return nil,err}
		// Replacement may contain $1 etc: yq uses Go Expand? Or ${1} ? Use re.ReplaceAllString with repl containing $ signs - Go interprets $$ etc.
		// jq gsub replacement uses captured via "\(.x)" - not here.
		resStr:=re.ReplaceAllString(dn.Value, repl)
		nn:=copyNode(c.Node); nn.Value=resStr
		out=addCand(out,c.cloneWith(nn))
	}
	return out,nil
}
func argSplit(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		if dn.Kind!=yaml.ScalarNode || dn.Tag!="!!str" { return nil, fmt.Errorf("cannot split %s, can only split strings", nodeTagOrDefault(dn)) }
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		sep:=""; if len(vals)>0{sep=scalarStringValue(vals[0].Node)}
		// sep is regex or literal? yq split docs: split with a separator string; regex if? Use regex split if sep has regex chars? Original jq-like split(",") literal; yq docs use split(", ") etc and also regex? Probe: "." splitting.
		// We'll try regex split using regexp (sep as regex). But literal dot in ".a.b" splitting by "." users expect regex dot matches any -> they'd escape \. Hmm.
		// Use regexp if sep compiles and contains regex meta? Simple: regexp split.
		var parts []string
		if sep=="" { parts=strings.Split(dn.Value,"") } else {
			re,err:=regexp.Compile(sep); if err!=nil{return nil,err}
			parts=re.Split(dn.Value,-1)
		}
		seq:=seqNode(); for _,p:=range parts{seq.Content=append(seq.Content,stringNode(p))}
		out=addCand(out,c.cloneWith(seq))
	}
	return out,nil
}
func argJoin(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("cannot join with %s, can only join arrays of scalars", nodeTagOrDefault(dn)) }
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		sep:=""; if len(vals)>0{sep=scalarStringValue(vals[0].Node)}
		var parts []string
		for _,ch:=range dn.Content{ dc:=derefAlias(ch); if dc.Kind!=yaml.ScalarNode{ return nil, fmt.Errorf("cannot join with %s, can only join arrays of scalars", nodeTagOrDefault(dc)) }; parts=append(parts,scalarToStringForJoin(dc)) }
		out=addCand(out,c.cloneWith(stringNode(strings.Join(parts,sep))))
	}
	return out,nil
}
func scalarToStringForJoin(n *yaml.Node) string { if n.Tag=="!!null"{ if n.Value=="null"||n.Value=="~"{return ""}; return n.Value}; return n.Value }

// other helper impls referenced in funcs.go
func encodeDecodeZero(ctx *Ctx,c *Cand,name string)([]*Cand,error){
	// name normalized could be tojson etc.
	switch name {
