		logWarn(fmt.Sprintf("EnvSubstOperator, env name: %s ", nodeTagOrDefault(dn)))
		return nil, fmt.Errorf("cannot substitute with %s, can only substitute strings", nodeTagOrDefault(dn))
	}
	res,err:=envSubstString(dn.Value, args)
