	a=derefAlias(a); b=derefAlias(b)
	if b.Kind==yaml.MappingNode {
		if a.Kind!=yaml.MappingNode {return false}
		for i:=0;i+1<len(b.Content);i+=2{
			found:=false
			for j:=0;j+1<len(a.Content);j+=2{ if nodesEqual(a.Content[j],b.Content[i]) { if containsNode(a.Content[j+1],b.Content[i+1]){found=true}; break } }
