	sort.SliceStable(targets,func(i,j int)bool{
		if len(targets[i].Path)!=len(targets[j].Path){return len(targets[i].Path)>len(targets[j].Path)}
		// same parent seq index descending
		if len(targets[i].Path)>0 && len(targets[j].Path)>0 {
			ii,_:=targets[i].Path[len(targets[i].Path)-1].(int); jj,_:=targets[j].Path[len(targets[j].Path)-1].(int); return ii>jj
		}
