		if p.Kind==yaml.MappingNode {
			for idx:=0;idx+1<len(p.Content);idx+=2{ if p.Content[idx+1]==t.Node { p.Content=append(p.Content[:idx],p.Content[idx+2:]...); break } }
		} else if p.Kind==yaml.SequenceNode {
			for idx,ch:=range p.Content{ if ch==t.Node { p.Content=append(p.Content[:idx],p.Content[idx+1:]...); break } }
		}
	}
}

