func regexArgs(ctx *Ctx,c *Cand,arg Expr)(string,string,error){
	// returns pattern, flags (or replacement for sub handled separately)
	args,kind:=blockOrUnionArgs(arg)
	if kind=="block" && len(args)>=2 {
		pv,err:=args[0].Eval(ctx,[]*Cand{c}); if err!=nil{return "","",err}
		fv,err:=args[1].Eval(ctx,[]*Cand{c}); if err!=nil{return "","",err}
		p:=""; if len(pv)>0{p=scalarStringValue(pv[0].Node)}; f:=""; if len(fv)>0{f=scalarStringValue(fv[0].Node)}
		return p,f,nil
	}
	vals,err:=arg.Eval(ctx,[]*Cand{c}); if err!=nil{return "","",err}
	if len(vals)==0 {return "","",nil}
	// If union produced multiple vals, first pattern second flags/replacement
	p:=scalarStringValue(vals[0].Node); f:=""; if len(vals)>1{f=scalarStringValue(vals[1].Node)}
	return p,f,nil
}
func compileRegex(pattern, flags string)(*regexp.Regexp,error){
	// flags: yq match/test second arg may be "g" (global) or ??? 'i' invalid as quoted probe: Error: 'i' is not a valid option for match...
	// Valid options appear to be "g" only? and maybe "i" handled via (?i)
	for _,ch:=range flags{
		if ch!='g' {
			return nil, fmt.Errorf("'%c' is not a valid option for match. To ignore case, use an expression like match(\"(?i)cat\")", ch)
		}
	}
	return regexp.Compile(pattern)
}
func argRegex(ctx *Ctx,in []*Cand,e *FuncExpr,name string)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		// test/match/capture operate on strings; if not string? Convert?
		pattern,flags,err:=regexArgs(ctx,c,e.arg); if err!=nil{return nil,err}
		re,err:=compileRegex(pattern,flags); if err!=nil{return nil,err}
		s:=dn.Value
		if dn.Kind!=yaml.ScalarNode { s="" }
		switch name {
		case "test":
			out=addCand(out,c.cloneWith(boolNode(re.MatchString(s))))
		case "match":
			// Find first or all if g flag
			if strings.Contains(flags,"g") {
				// original with g still returned single match object in probe (for l+ only one) - if multiple matches, returns multiple candidates?
				matches:=re.FindAllStringSubmatchIndex(s,-1)
				if len(matches)==0 { /* return no candidate? jq match with no match returns... yq returns? We'll return null cand? Probe later */ out=addCand(out,c.cloneWith(nullNode())); continue }
				for _,m:=range matches{ out=addCand(out,c.cloneWith(matchObject(re,s,m))) }
			} else {
				m:=re.FindStringSubmatchIndex(s)
				if m==nil { out=addCand(out,c.cloneWith(nullNode())); continue }
				out=addCand(out,c.cloneWith(matchObject(re,s,m)))
			}
		case "capture":
			m:=re.FindStringSubmatch(s)
			if m==nil { out=addCand(out,c.cloneWith(nullNode())); continue }
			mp:=mapNode()
			names:=re.SubexpNames()
			for i,nameCap:=range names{ if i==0||nameCap==""{continue}; mp.Content=append(mp.Content,stringNode(nameCap),stringNode(m[i])) }
			out=addCand(out,c.cloneWith(mp))
		}
	}
	return out,nil
}
func matchObject(re *regexp.Regexp,s string,m []int) *yaml.Node {
	// {string,offset,length,captures:[{string,offset,length,name}...]}
	full:=s[m[0]:m[1]]
	caps:=seqNode(); caps.Style=yaml.FlowStyle
	names:=re.SubexpNames()
	// captures only for groups? Probe l+ no groups => []
	for i:=1;i<len(m)/2;i++{
		if m[2*i]<0 { continue }
		capNode:=mapNode(
			stringNode("string"), stringNode(s[m[2*i]:m[2*i+1]]),
			stringNode("offset"), intNode(int64(m[2*i])),
			stringNode("length"), intNode(int64(m[2*i+1]-m[2*i])),
			stringNode("name"), stringNode(names[i]),
		)
		// yq capture object format may omit name if empty? Probe later.
		if names[i]=="" {
			// remove name pair?
			capNode.Content=capNode.Content[:6]
		}
		caps.Content=append(caps.Content,capNode)
		caps.Style=0
	}
	return mapNode(
		stringNode("string"), stringNode(full),
		stringNode("offset"), intNode(int64(m[0])),
		stringNode("length"), intNode(int64(m[1]-m[0])),
		stringNode("captures"), caps,
	)
}
func argSub(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		if dn.Kind!=yaml.ScalarNode || dn.Tag!="!!str" {
			// what error? defer
			return nil, fmt.Errorf("cannot substitute with %s, can only substitute strings", nodeTagOrDefault(dn))
		}
		// args: pattern, replacement (via union or block)
		args,kind:=blockOrUnionArgs(e.arg)
		var pattern, repl string
		var flags string
		if (kind=="block"||kind=="union") && len(args)>=1 {
			pv,err:=args[0].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}; if len(pv)>0{pattern=scalarStringValue(pv[0].Node)}
			if len(args)>=2 { rv,err:=args[1].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}; if len(rv)>0{repl=scalarStringValue(rv[0].Node)} }
			if len(args)>=3 { fv,err:=args[2].Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}; if len(fv)>0{flags=scalarStringValue(fv[0].Node)} }
		} else {
			p,f,err:=regexArgs(ctx,c,e.arg); if err!=nil{return nil,err}; pattern=p; repl=f
		}
		_ = flags
		re,err:=compileRegex(pattern,""); if err!=nil{return nil,err}
		// Replacement may contain $1 etc: yq uses Go Expand? Or ${1} ? Use re.ReplaceAllString with repl containing $ signs - Go interprets $$ etc.
		// jq gsub replacement uses captured via "\(.x)" - not here.
		resStr:=re.ReplaceAllString(dn.Value, repl)
		nn:=copyNode(c.Node); nn.Value=resStr
		out=addCand(out,c.cloneWith(nn))
	}
	return out,nil
}
func argSplit(ctx *Ctx,in []*Cand,e *FuncExpr)([]*Cand,error){
	var out []*Cand
	for _,c:=range in{
		dn:=derefAlias(c.Node)
		if dn.Kind!=yaml.ScalarNode || dn.Tag!="!!str" { return nil, fmt.Errorf("cannot split %s, can only split strings", nodeTagOrDefault(dn)) }
		vals,err:=e.arg.Eval(ctx,[]*Cand{c}); if err!=nil{return nil,err}
		sep:=""; if len(vals)>0{sep=scalarStringValue(vals[0].Node)}
		// sep is regex or literal? yq split docs: split with a separator string; regex if? Use regex split if sep has regex chars? Original jq-like split(",") literal; yq docs use split(", ") etc and also regex? Probe: "." splitting.
		// We'll try regex split using regexp (sep as regex). But literal dot in ".a.b" splitting by "." users expect regex dot matches any -> they'd escape \. Hmm.
		// Use regexp if sep compiles and contains regex meta? Simple: regexp split.
		var parts []string
		if sep=="" { parts=strings.Split(dn.Value,"") } else {
			re,err:=regexp.Compile(sep); if err!=nil{return nil,err}
			parts=re.Split(dn.Value,-1)
		}
		seq:=seqNode(); for _,p:=range parts{seq.Content=append(seq.Content,stringNode(p))}
		out=addCand(out,c.cloneWith(seq))
	}
	return out,nil
