func envSubstString(s string, args []string)(string,error){
	// Supports $VAR and ${VAR}, ${VAR:-default}, ${VAR-default}, ${VAR:?error} etc shell-ish
	// Simple implementation for common cases.
	var b strings.Builder
	for i:=0;i<len(s);i++{
		if s[i]=='$' && i+1<len(s) {
			if s[i+1]=='{' {
				j:=strings.Index(s[i:],"}"); if j<0 { b.WriteByte(s[i]); continue }
				inner:=s[i+2:i+j]
				val,err:=expandEnvBraced(inner); if err!=nil{return "",err}
				b.WriteString(val); i+=j; continue
			}
			if isVarChar(s[i+1]) {
				j:=i+1; for j<len(s)&&isVarChar(s[j]){j++}
				name:=s[i+1:j]; b.WriteString(os.Getenv(name)); i=j-1; continue
			}
		}
		b.WriteByte(s[i])
	}
	return b.String(),nil
}
func expandEnvBraced(inner string)(string,error){
	// parse VAR, optional op :- - :? ? :+ +
	// find op position
	for _,op:=range []string{":-",":?":="+","-","?","+"}{
		_ = op
	}
	// manual scan
	i:=0; for i<len(inner)&&isVarChar(inner[i]){i++}
	name:=inner[:i]; rest:=inner[i:]
	val,present:=os.LookupEnv(name)
	if rest==""{return val,nil}
	// :- default if unset or empty; - if unset
	if strings.HasPrefix(rest,":-"){ if !present||val==""{return rest[2:],nil}; return val,nil }
	if strings.HasPrefix(rest,"-"){ if !present{return rest[1:],nil}; return val,nil }
	if strings.HasPrefix(rest,":?"){ if !present||val==""{ msg:=rest[2:]; if msg==""{msg="error"}; return "",fmt.Errorf("%s",msg)}; return val,nil }
	if strings.HasPrefix(rest,"?"){ if !present{ msg:=rest[1:]; if msg==""{msg="error"}; return "",fmt.Errorf("%s",msg)}; return val,nil }
	if strings.HasPrefix(rest,":+"){ if present&&val!=""{return rest[2:],nil}; return "",nil }
	if strings.HasPrefix(rest,"+"){ if present{return rest[1:],nil}; return "",nil }
	return val,nil
}

func arrayToMap(c *Cand)([]*Cand,error){
	dn:=derefAlias(c.Node)
	if dn.Kind!=yaml.SequenceNode { return []*Cand{c},nil } // original on map returned map unchanged
	mp:=mapNode()
	for _,ch:=range dn.Content{
		dc:=derefAlias(ch)
		if dc.Kind==yaml.ScalarNode{ mp.Content=append(mp.Content, copyNodePreserve(dc), nullNode()) } else if dc.Kind==yaml.MappingNode {
			// merge entries?
			for i:=0;i+1<len(dc.Content);i+=2{ mp.Content=append(mp.Content,copyNodePreserve(dc.Content[i]),copyNodePreserve(dc.Content[i+1])) }
		}
	}
	return []*Cand{c.cloneWith(mp)},nil
}
func pivotCand(c *Cand)([]*Cand,error){
	dn:=derefAlias(c.Node)
	if dn.Kind!=yaml.SequenceNode { return nil, fmt.Errorf("cannot pivot node of type %s", nodeTagOrDefault(dn)) }
	// pivot turns array of arrays / maps (csv) transpose: rows to columns
	// If elements are maps with same keys, transpose to map of arrays? Probe later - implement arrays transpose
	var rows [][]*yaml.Node
	for _,ch:=range dn.Content{ dc:=derefAlias(ch); if dc.Kind!=yaml.SequenceNode{ return []*Cand{c},nil }; rows=append(rows,dc.Content)}
	maxCols:=0; for _,r:=range rows{ if len(r)>maxCols{maxCols=len(r)} }
	newSeq:=seqNode()
	for col:=0;col<maxCols;col++{ row:=seqNode(); for r:=0;r<len(rows);r++{ if col<len(rows[r]){row.Content=append(row.Content,copyNodePreserve(rows[r][col]))}else{row.Content=append(row.Content,nullNode())} }; newSeq.Content=append(newSeq.Content,row)}
	return []*Cand{c.cloneWith(newSeq)},nil
}
func splitDoc(c *Cand)([]*Cand,error){
