func formatFromFilename(filename string) (string, string) {
	if filename == "" || filename == "-" {
		return "yaml", "yaml"
	}
	lower := strings.ToLower(filename)
	idx := strings.LastIndex(lower, ".")
	if idx < 0 {
		return "yaml", "yaml"
	}
	ext := lower[idx+1:]
	switch ext {
	case "yaml", "yml":
		return "yaml", "yaml"
	case "json":
		return "json", "json"
	case "xml":
		return "xml", "xml"
