{"command":"cat > formats_in.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

type docData struct {
	node    *yaml.Node
	leading string
}

func decodeAllDocs(format string, data []byte, filename string) ([]*docData, error) {
	switch format {
	case "yaml", "kyaml":
		return decodeYAML(data)
	case "json":
		return decodeJSON(data)
	case "props":
		n, err := decodeProps(data)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "ini":
		n, err := decodeINI(data)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "csv":
		n, err := decodeCSV(data, rune(globalCfg.csvSeparator), globalCfg.csvAutoParse)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "tsv":
		n, err := decodeCSV(data, '\t', globalCfg.tsvAutoParse)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "xml":
		n, err := decodeXML(data)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "toml":
		n, err := decodeTOML(data)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "hcl":
		n, err := decodeHCL(data)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "lua":
		n, err := decodeLua(data)
		if err != nil { return nil, err }
		return []*docData{{node:n}}, nil
	case "base64":
		// trim whitespace? original errors on "a: 1\n" at byte1 because ':' invalid; newline at end is ignored by decoder? Go base64 decoder ignores \n\r
		decoded, err := base64.StdEncoding.DecodeString(string(data))
		if err != nil {
			// StdEncoding.DecodeString returns "illegal base64 data at input byte X" match
			return nil, err
		}
		return []*docData{{node: stringNode(string(decoded))}}, nil
	case "uri":
		s, err := url.QueryUnescape(string(data))
		if err != nil { return nil, err }
		return []*docData{{node: stringNode(s)}}, nil
	case "shell":
		// handled earlier with raw format string in error
		return nil, fmt.Errorf("no support for shell input format")
	}
	return nil, fmt.Errorf("unknown format")
}

func extractLeadingHeader(data []byte, preprocess bool) (string, []byte) {
	if !preprocess {
		return "", data
	}
	// Scan lines; leading lines are blank, comments, %YAML, or doc separator '---' / '--- rest'
	remaining := data
	var leading strings.Builder
	for len(remaining) > 0 {
		// get one line including newline
		lineEnd := bytes.IndexByte(remaining, '\n')
		var line []byte
		var rest []byte
		if lineEnd < 0 {
			line = remaining
			rest = nil
		} else {
			line = remaining[:lineEnd+1]
			rest = remaining[lineEnd+1:]
		}
		lineStr := strings.TrimSuffix(strings.TrimSuffix(string(line), "\n"), "\r")
		trimmed := strings.TrimSpace(lineStr)
		if trimmed == "" {
			leading.Write(line)
			// ensure newline if last line no newline
			if lineEnd < 0 && !strings.HasSuffix(string(line),"\n") { /* keep */ }
			remaining = rest
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			leading.Write(line)
			if lineEnd < 0 { leading.WriteString("\n") }
			remaining = rest
			continue
		}
		if strings.HasPrefix(lineStr, "%YAML") {
			leading.Write(line)
			if lineEnd < 0 { leading.WriteString("\n") }
			remaining = rest
			continue
		}
		if trimmed == "---" {
			leading.WriteString("---\n")
			remaining = rest
			continue
		}
		if strings.HasPrefix(lineStr, "--- ") || strings.HasPrefix(lineStr, "---\t") {
			leading.WriteString("---\n")
			// remainder of this line after '--- ' becomes first content line
			contentPart := lineStr[4:]
			newData := append([]byte(contentPart+"\n"), rest...)
			return leading.String(), newData
		}
		break
	}
	return leading.String(), remaining
}

func decodeYAML(data []byte) ([]*docData, error) {
	leading, rest := extractLeadingHeader(data, globalCfg.headerPreprocess)
	dec := yaml.NewDecoder(bytes.NewReader(rest))
	var docs []*docData
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, adjustYAMLError(err)
		}
		var root *yaml.Node
		if len(node.Content) > 0 {
			root = node.Content[0]
		} else {
			root = blankNullNode()
		}
		d := &docData{node: root}
		if len(docs) == 0 {
			d.leading = leading
		}
		docs = append(docs, d)
	}
	if len(docs) == 0 {
		// empty input: one blank null doc with leading
		docs = append(docs, &docData{node: blankNullNode(), leading: leading})
	} else if leading != "" && docs[0].leading == "" {
		docs[0].leading = leading
	}
	return docs, nil
}

func adjustYAMLError(err error) error {
	// yaml.v3 error strings differ from newer yaml lib used by original in some cases.
	// Handle some known mappings:
	msg := err.Error()
	if msg == "yaml: found incompatible YAML document" {
		return fmt.Errorf("yaml: <unknown position>: found incompatible YAML document")
	}
	// Leave others for now; tuning phase may add transforms for common errors.
	return err
}

func decodeJSON(data []byte) ([]*docData, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var docs []*docData
	for {
		node, err := readJSONValue(dec)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		docs = append(docs, &docData{node: node})
		// Check for more values: peek token? readJSONValue at EOF next iter will give EOF. But trailing whitespace ok.
	}
	if len(docs)==0 {
		// empty JSON input: original? For -p json with empty stdin, probe later. Return blank null to avoid crash, but json decoder on empty should error EOF as fromjson did. For file input empty, earlier fromjson on map (empty string) gave EOF error. For stdin empty json file, likely error EOF. We'll make caller decide? Here return error EOF if data empty/whitespace
		if len(bytes.TrimSpace(data))==0 {
			return nil, io.EOF
		}
	}
	return docs, nil
}

func readJSONValue(dec *json.Decoder) (*yaml.Node, error) {
	tok, err := dec.Token()
	if err != nil { return nil, err }
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			m := mapNode()
			for dec.More() {
				ktok, err := dec.Token(); if err!=nil{return nil,err}
				ks, _ := ktok.(string)
				kNode := stringNode(ks); kNode.Style = yaml.DoubleQuotedStyle
				v, err := readJSONValue(dec); if err!=nil{return nil,err}
				m.Content = append(m.Content, kNode, v)
			}
			_, err := dec.Token(); if err!=nil{return nil,err} // }
			return m, nil
		case '[':
			s := seqNode()
			for dec.More() {
				v, err := readJSONValue(dec); if err!=nil{return nil,err}
				s.Content=append(s.Content,v)
			}
			_, err := dec.Token(); if err!=nil{return nil,err}
			return s, nil
		}
	case string:
		n:=stringNode(t); n.Style=yaml.DoubleQuotedStyle; return n,nil
	case json.Number:
		s:=t.String()
		if strings.ContainsAny(s,".eE") { return scalarNode("!!float",s),nil }
		return scalarNode("!!int",s),nil
	case bool:
		return boolNode(t),nil
	case nil:
		return nullNode(),nil
	case float64:
		return floatNode(t),nil
	}
	return stringNode(fmt.Sprintf("%v",tok)),nil
}

// PROPERTIES
func decodeProps(data []byte)(*yaml.Node,error){
	root:=mapNode()
	scanner:=bufio.NewScanner(bytes.NewReader(data))
	// increase buffer for long lines
	buf:=make([]byte,0,64*1024); scanner.Buffer(buf,10*1024*1024)
	var pendingComments []string
	for scanner.Scan(){
		line:=scanner.Text()
		trimmed:=strings.TrimSpace(line)
		if trimmed=="" { continue }
		if strings.HasPrefix(trimmed,"#") || strings.HasPrefix(trimmed,"!") && !strings.Contains(trimmed,"=") && !strings.Contains(trimmed,":") {
			// comment line (starting with #) - also observed # comment preserved before next key
			if strings.HasPrefix(trimmed,"#") { pendingComments=append(pendingComments,trimmed); continue }
		}
		// continuation lines ending with \ - simplified: not handled
		key, val, found := splitPropsLine(line)
		if !found {
			// key with empty value?
			key=trimmed; val=""
		}
		key=strings.TrimSpace(unescapeProps(key))
		val=strings.TrimSpace(val)
		// value unescape? properties values may have escapes \n etc - do basic
		val=unescapePropsValue(val)
		segments:=splitPropsKey(key)
		vNode:=stringNode(val)
		// attach pending comments as HeadComment to key node that will be created at top segment? We'll pass to insert function via global? Simplify: attach to vNode? Original comment before x: y appeared before x in map output - that's HeadComment on key node "x".
		insertPropsPath(root,segments,vNode,pendingComments)
		pendingComments=nil
	}
	if err:=scanner.Err(); err!=nil{return nil,err}
	return root,nil
}
func splitPropsLine(line string)(string,string,bool){
	// find first unescaped = or : separator; properties also allows whitespace separator.
	escaped:=false
	for i,ch:=range line{
		if escaped{escaped=false; continue}
		if ch=='\\'{escaped=true; continue}
		if ch=='='||ch==':'{ return line[:i], line[i+1:], true }
	}
	// whitespace separator: first space sequence
	fields:=strings.Fields(line)
	if len(fields)>=2{
		idx:=strings.Index(line, fields[0])+len(fields[0])
		return fields[0], strings.TrimSpace(line[idx:]), true
	}
	return "", "", false
}
func unescapeProps(s string) string {
	// remove escapes for ., =, :, space, \ etc simplistic
	var b strings.Builder
	for i:=0;i<len(s);i++{ if s[i]=='\\' && i+1<len(s){ i++; b.WriteByte(s[i]) } else { b.WriteByte(s[i]) } }
	return b.String()
}
func unescapePropsValue(s string) string {
	// properties file escapes: \n \t \r \\ \uXXXX etc - use similar limited
	var b strings.Builder
	for i:=0;i<len(s);i++{
		if s[i]=='\\'&&i+1<len(s){
			switch s[i+1]{
			case 'n': b.WriteByte('\n'); i++
			case 't': b.WriteByte('\t'); i++
			case 'r': b.WriteByte('\r'); i++
			case '\\': b.WriteByte('\\'); i++
			case 'u': if i+5<len(s){ if code,err:=strconv.ParseInt(s[i+2:i+6],16,32); err==nil{ b.WriteRune(rune(code)); i+=5 } else { b.WriteByte(s[i]) } } else { b.WriteByte(s[i]) }
			default: b.WriteByte(s[i+1]); i++
			}
		} else { b.WriteByte(s[i]) }
	}
	return b.String()
}
func splitPropsKey(key string) []string {
	// split on unescaped '.', handling [index] segments if propertiesArrayBrackets? Input parsing may also support a[0] always? Observed a.0 becomes array. a[0] maybe also.
	// First expand brackets: "a[0].b" -> ["a","0","b"]; "a[foo]" -> ["a","foo"]?
	var parts []string
	var cur strings.Builder
	for i:=0;i<len(key);i++{
		ch:=key[i]
		if ch=='.' { parts=append(parts,cur.String()); cur.Reset(); continue }
		if ch=='[' {
			// finish cur if not empty
			if cur.Len()>0{ parts=append(parts,cur.String()); cur.Reset() }
			end:=strings.Index(key[i:],"]")
			if end<0{ cur.WriteByte(ch); continue }
			inside:=key[i+1:i+end]
			parts=append(parts,inside)
			i+=end
			// skip possible following dot in loop next iterations (dot will add empty - avoid)
			if i+1<len(key) && key[i+1]=='.' { i++ }
			continue
		}
		cur.WriteByte(ch)
	}
	if cur.Len()>0 || len(parts)==0 { parts=append(parts,cur.String()) }
	return parts
}
func insertPropsPath(root *yaml.Node, segs []string, vNode *yaml.Node, comments []string){
	if len(segs)==0{return}
	cur:=root
	for idx,seg:=range segs{
		last:=idx==len(segs)-1
		// determine if next segment is numeric -> child should be seq
		if cur.Kind==yaml.MappingNode{
			// find key
			var existing *yaml.Node; var keyNode *yaml.Node; pos:=-1
			for i:=0;i+1<len(cur.Content);i+=2{ if cur.Content[i].Value==seg { existing=cur.Content[i+1]; keyNode=cur.Content[i]; pos=i; break } }
			if existing==nil{
				keyNode=stringNode(seg)
				if len(comments)>0 && idx==0 { keyNode.HeadComment = strings.Join(stripHashComments(comments),"\n") }
				if last{
					cur.Content=append(cur.Content,keyNode,vNode)
					return
				}
				// create next container based on next seg numeric?
				var child *yaml.Node
				if isNumericString(segs[idx+1]){ child=seqNode() } else { child=mapNode() }
				cur.Content=append(cur.Content,keyNode,child)
				cur=child
			} else {
				_ = keyNode; _=pos
				if last{
					// replace value (duplicate keys last wins? or array? props duplicates - replace)
					cur.Content[pos+1]=vNode
					return
				}
				// if existing is scalar but need container, convert to map/seq losing scalar?
				if existing.Kind==yaml.ScalarNode{
					var child *yaml.Node; if isNumericString(segs[idx+1]){child=seqNode()}else{child=mapNode()}
					cur.Content[pos+1]=child; cur=child
				} else {
					cur=existing
				}
			}
		} else if cur.Kind==yaml.SequenceNode{
			iv,err:=strconv.Atoi(seg); if err!=nil{
				// cannot insert non-numeric into seq: convert? break
				return
			}
			for len(cur.Content)<=iv{ cur.Content=append(cur.Content, nullNode()) } // placeholder may remain wrong for sparse
			if last{ cur.Content[iv]=vNode; return }
			child:=cur.Content[iv]
			if child.Kind==yaml.ScalarNode && child.Tag=="!!null" {
				var nc *yaml.Node; if isNumericString(segs[idx+1]){nc=seqNode()}else{nc=mapNode()}
				cur.Content[iv]=nc; cur=nc
			} else { cur=child }
		} else {
			return
		}
	}
}
func stripHashComments(cs []string) []string{ var out []string; for _,c:=range cs{ out=append(out, strings.TrimSpace(strings.TrimPrefix(c,"#"))) }; return out }
func isNumericString(s string) bool { if s==""{return false}; for _,r:=range s{ if r<'0'||r>'9'{return false} }; return true }

// INI
func decodeINI(data []byte)(*yaml.Node,error){
	root:=mapNode()
	current:=root
	scanner:=bufio.NewScanner(bytes.NewReader(data)); buf:=make([]byte,0,64*1024); scanner.Buffer(buf,10*1024*1024)
	for scanner.Scan(){
		line:=strings.TrimSpace(scanner.Text())
		if line==""{continue}
		if strings.HasPrefix(line,";")||strings.HasPrefix(line,"#"){continue}
		if strings.HasPrefix(line,"[") && strings.HasSuffix(line,"]"){
			sec:=strings.TrimSpace(line[1:len(line)-1])
			// section names may be quoted or have dots meaning nested? ini lib treats dots as child sections? Implement split by '.'
			segs:=strings.Split(sec,".")
			current=root
			for _,seg:=range segs{
				seg=strings.TrimSpace(seg)
				var existing *yaml.Node
				for i:=0;i+1<len(current.Content);i+=2{ if current.Content[i].Value==seg{existing=current.Content[i+1]; break}}
				if existing==nil{ m:=mapNode(); current.Content=append(current.Content,stringNode(seg),m); current=m } else { current=existing }
			}
			continue
		}
		// key = value or key: value
		idx:=strings.IndexAny(line,"=:")
		if idx<0{
			// key without value ->? ini sets true? set empty
			current.Content=append(current.Content,stringNode(line),stringNode(""))
			continue
		}
		k:=strings.TrimSpace(line[:idx]); v:=strings.TrimSpace(line[idx+1:])
		// strip surrounding quotes from value? ini lib keeps? If quoted with "...", value inside?
		// Keep raw except if triple quotes etc.
		// duplicate keys: append as array?
		var pos=-1
		for i:=0;i+1<len(current.Content);i+=2{ if current.Content[i].Value==k{pos=i;break} }
		if pos>=0{
			ex:=current.Content[pos+1]
			if ex.Kind==yaml.SequenceNode{ ex.Content=append(ex.Content,stringNode(v)) } else { newSeq:=seqNode(ex,stringNode(v)); current.Content[pos+1]=newSeq }
		} else {
			current.Content=append(current.Content,stringNode(k),stringNode(v))
		}
	}
	return root, scanner.Err()
}

// CSV
func decodeCSV(data []byte, sep rune, autoParse bool)(*yaml.Node,error){
	r:=csv.NewReader(bytes.NewReader(data))
	if sep!=0 { r.Comma=sep }
	r.TrimLeadingSpace=false
	r.FieldsPerRecord=-1
	records,err:=r.ReadAll()
	if err!=nil{return nil,err}
	if len(records)==0{
		seq:=seqNode(); seq.Style=yaml.FlowStyle; return seq,nil
	}
	headers:=records[0]
	seq:=seqNode()
	if len(records)==1{
		// only header -> empty array as observed "a: 1\n" single line case
		seq.Style=yaml.FlowStyle; return seq,nil
	}
	for _,rec:=range records[1:]{
		row:=mapNode()
		for i,h:=range headers{
			var val string; if i<len(rec){val=rec[i]}
			row.Content=append(row.Content,stringNode(h), parseCSVCell(val,autoParse))
		}
		seq.Content=append(seq.Content,row)
	}
	return seq,nil
}
func parseCSVCell(s string,autoParse bool)*yaml.Node{
	if !autoParse { return stringNode(s) }
	// Use yaml scalar parsing for a single cell: decode via yaml into Node would treat "a: b" as map - original says parse CSV YAML/JSON values
	if s==""{ return stringNode("") }
	// Try parse as yaml document and take root if it is scalar and its textual representation corresponds? For JSON values like {"a":1} or [1,2] parsed as structures.
	// Use yaml decoder on cell
	var n yaml.Node
	dec:=yaml.NewDecoder(strings.NewReader(s))
	if err:=dec.Decode(&n); err==nil && len(n.Content)>0{
		root:=n.Content[0]
		// If root is map due to colon in plain text, yq might still treat as map? Their auto-parse probably uses yaml Unmarshal to interface then node - a value like "12:30" becomes string in yaml? "a: b" in CSV cell would be map - possible intentional.
		return root
	}
	return stringNode(s)
}

// generic decode string to node for from_X operators
func decodeStringToNode(s string, format string, c *Cand)(*yaml.Node,error){
	docs,err:=decodeAllDocs(format, []byte(s), "-")
	if err!=nil{return nil,err}
	if len(docs)==0{return blankNullNode(),nil}
	return docs[0].node,nil
}

func loadFileAsDocs(fname string, base *Cand)([]*Cand,error){
	data,err:=readInputFile(fname)
	if err!=nil{return nil,err}
	// format from extension
	format,_:=formatFromFilename(fname)
	// If global input format specified? load uses extension regardless? yq load guesses format by extension.
	docs,err:=decodeAllDocs(format,data,fname)
	if err!=nil{return nil, fmt.Errorf("bad file '%s': %s", fname, err.Error())}
	var out []*Cand
	for i,d:=range docs{
		out=append(out,&Cand{Node:d.node, Path: []interface{}{}, DocIdx:i, FileIdx: base.FileIdx, Filename: fname, Leading:d.leading})
	}
	return out,nil
}
