// shell escape for @sh operator - mimic shellescape.Quote behaviour observed
func shellEscape(s string) string {
	if s==""{return ""}
	// Based on observations:
	// safe prefix chars [a-zA-Z0-9_-.,:/\n] are left unquoted; first unsafe char triggers single-quoting of remainder, but single quote itself is escaped as \'
	// Let's examine algorithm: we can implement state machine:
	// Iterate runes, keep a buffer. When char is safe and we're not in quotes, append. When char is single quote: close quote if in, append \', (remain out?)
	// When char unsafe (not single quote): if not in quotes, open '; append char; in quotes at end close.
	var b strings.Builder
	inQ:=false
	for _,r:=range s{
		if r=='\''{
			if inQ{ b.WriteString("'"); inQ=false }
			b.WriteString("\\'")
			continue
		}
		if isShellSafe(r){
			if inQ{
				// safe chars inside quotes remain quoted until end? In observed "a b c", after opening at first space, b etc stayed in quotes until end.
				b.WriteRune(r)
			} else {
				b.WriteRune(r)
			}
			continue
		}
		// unsafe
		if !inQ{ b.WriteString("'"); inQ=true }
		b.WriteRune(r)
	}
	if inQ{ b.WriteString("'") }
	return b.String()
}
func isShellSafe(r rune) bool {
	if (r>='a'&&r<='z')||(r>='A'&&r<='Z')||(r>='0'&&r<='9'){return true}
	switch r{case '_','-',',',':','/','\n': return true}
	// '.' is safe? probe later; shellescape safe set includes . ?
	if r=='.'{return true}
	return false
}
