	// yaml.v3 Encoder Encode expects a value; encoding a *Node works
	if err:=enc.Encode(n); err!=nil{ enc.Close(); return "",err }
	if err:=enc.Close(); err!=nil{return "",err}
	out:=buf.String()
	if compact || globalCfg.yamlCompactSeq {
		out=compactSeqIndent(out,indent)
	}
	return out,nil
}

func compactSeqIndent(s string, indent int) string {
	// Heuristic transform: remove `indent` spaces from lines that are sequence entries at a level where parent is a map key line ending with ':' (and their nested continuation lines shift accordingly)
	// Track a stack of shifts per indentation level.
	lines:=strings.SplitAfter(s,"\n")
	// We'll compute for each line its original indent (count spaces, tabs not expected)
	// Determine seq levels: a seq entry is a line with indent X and content starting "- " or "-" where previous non-blank line with smaller indent is a mapping key ending ':' (with indent X-indent)
	// When found, record shift at that level: all lines with indent >= X while within that seq block get shifted by indent. Nested seqs cumulate.
	type shiftInfo struct{ level int; shift int } // level = original indent of seq entries
	var shifts []shiftInfo
	var outLines []string
	// Need to know parent context: maintain stack of indents of map keys awaiting block value
	// Simpler state: keep list of active seq shifts; pop when line indent < shift level and line not blank/comment?
	prevNonBlankIndent:=-1
	prevNonBlankText:=""
	for _,line:=range lines{
		if line==""{continue}
		content:=strings.TrimSuffix(line,"\n")
		if strings.TrimSpace(content)==""{
			outLines=append(outLines,line); continue
		}
		origIndent:=len(content)-len(strings.TrimLeft(content," "))
		trimmed:=strings.TrimLeft(content," ")
		// pop shifts whose level > origIndent
		for len(shifts)>0 && shifts[len(shifts)-1].level > origIndent { shifts=shifts[:len(shifts)-1] }
		// detect new seq under map
		isSeq:= trimmed=="-" || strings.HasPrefix(trimmed,"- ")
		if isSeq {
			// check if this seq level already has a shift
			has:=false; for _,sh:=range shifts{ if sh.level==origIndent{has=true;break} }
			if !has {
				// Determine parent: prev nonblank indent should be origIndent-indent and text ends with ":" (map key with block value) OR parent is also a seq entry? Compact only for seq under map, not nested seq under seq (where "- - x" style or indented)
				if prevNonBlankIndent==origIndent-indent && strings.HasSuffix(strings.TrimSpace(prevNonBlankText),":") {
					shifts=append(shifts, shiftInfo{level:origIndent, shift:indent})
				} else if origIndent>0 && prevNonBlankIndent<origIndent {
					// Could be seq as value of a map key inside a seq entry etc. Check any line above? We'll be conservative: if prev text ends with ':' and prev indent < origIndent, add.
					if strings.HasSuffix(strings.TrimSpace(prevNonBlankText),":") {
						// shift amount = origIndent - (prevIndent) ??? For -c, seq indent considered part of prev indent; expected new indent = prevIndent when '- ' counts? In yaml.v3, seq indent = prevIndent + indent.
						amt:=origIndent-prevNonBlankIndent
						if amt>0 { shifts=append(shifts, shiftInfo{level:origIndent, shift:amt}) }
					}
				}
			}
		}
		totalShift:=0; for _,sh:=range shifts{ if origIndent>=sh.level{ totalShift+=sh.shift } }
		newIndent:=origIndent-totalShift; if newIndent<0{newIndent=0}
		newLine:=strings.Repeat(" ",newIndent)+trimmed
		if strings.HasSuffix(line,"\n"){ newLine+="\n" }
		outLines=append(outLines,newLine)
		// update prev (comments should not update? comments trimmed start with # - skip as prev for detection? keep if not comment)
		if !strings.HasPrefix(trimmed,"#"){
			prevNonBlankIndent=origIndent; prevNonBlankText=content
		}
		// If this line is a literal/folded block scalar header, subsequent content lines are literal and should NOT be shifted blindly... yaml encoder indents block content by indent relative to key; with compact, content under seq needs shifting too. Our method shifts based indent, which would alter literal text leading spaces beyond block indentation? Block content lines in output have exactly block indent + original leading spaces; shifting them by seq shift is correct to keep relative content (encoder would do same). Lines that are completely blank handled.
	}
	return strings.Join(outLines,"")
}

// JSON
func encodeJSON(n *yaml.Node, indent int)(string,error){
	v,err:=nodeToJSONValue(n); if err!=nil{return "",err}
	var buf bytes.Buffer
	if indent==0 {
		// compact
		s,err:=marshalJSONCompact(v); if err!=nil{return "",err}; return s+"\n",nil // tojson(0) printed without extra blank line in probe when used as value? encodeNodeToString returns string ending \n; printer with json format uses this and adds? We'll handle printer separately not double.
	}
	prefix:=""; indentStr:=strings.Repeat(" ",indent)
	s,err:=marshalJSONIndent(v,prefix,indentStr); if err!=nil{return "",err}
	buf.WriteString(s); buf.WriteString("\n")
	return buf.String(),nil
}

// We implement JSON marshaling ourselves to control number handling and HTML escaping.
type jsonValue interface{}
type jsonOrderedMap struct{ keys []string; vals map[string]jsonValue }
type jsonNumber string

func nodeToJSONValue(n *yaml.Node)(jsonValue,error){
	n=derefAlias(n)
	switch n.Kind{
	case yaml.ScalarNode:
		switch n.Tag{
		case "!!null": return nil,nil
		case "!!bool": return parseBool(n.Value),nil
		case "!!int":
			// preserve integer as number; convert hex etc to decimal
			v,ok:=parseNumberValue(n.Value); if !ok{return n.Value,nil}
			switch t:=v.(type){case int64: return jsonNumber(strconv.FormatInt(t,10)),nil; case uint64: return jsonNumber(strconv.FormatUint(t,10)),nil; case float64: return jsonNumber(formatJSONFloat(t)),nil}
			return jsonNumber(n.Value),nil
		case "!!float":
			v,ok:=parseNumberValue(n.Value); if !ok{return n.Value,nil}
			if f,ok:=v.(float64); ok {
				// inf/nan cannot json - original errors? Return error matching Go json: "json: unsupported value: +Inf"
			}
			switch t:=v.(type){case int64: return jsonNumber(strconv.FormatInt(t,10)),nil; case float64: return jsonNumber(formatJSONFloat(t)),nil}
			return jsonNumber(n.Value),nil
		case "!!timestamp":
			t,err:=parseTimestamp(n.Value); if err==nil{ return formatTimestamp(t),nil }; return n.Value,nil
		default:
			return n.Value,nil
		}
	case yaml.SequenceNode:
		var arr []jsonValue; for _,ch:=range n.Content{ v,err:=nodeToJSONValue(ch); if err!=nil{return nil,err}; arr=append(arr,v)}; if arr==nil{arr=[]jsonValue{}}; return arr,nil
	case yaml.MappingNode:
		om:=&jsonOrderedMap{vals:map[string]jsonValue{}}
		// handle merge keys: first collect merged entries then explicit override? YAML decode semantics: merge keys have lower priority.
		// Implement: process merge keys first, then explicit in order (new keys appended, existing keys keep first position? Go yaml map decode order not relevant. JSON order likely explicit order with merged at merge position if not overridden... simplify below sequential processing: when encountering <<, insert merged pairs if not already present nor present as explicit later - pre-scan explicit keys.
		explicit:=map[string]bool{}
		for i:=0;i+1<len(n.Content);i+=2{ k:=n.Content[i]; if k.Tag!="!!merge" && k.Value!="<<" { explicit[jsonKeyString(k)]=true } }
		for i:=0;i+1<len(n.Content);i+=2{
			k:=n.Content[i]; v:=n.Content[i+1]
			if k.Tag=="!!merge" || k.Value=="<<" {
				mergedMaps:=mergeSourceMaps(v)
				for _,mm:=range mergedMaps{
					mv,err:=nodeToJSONValue(mm); if err!=nil{return nil,err}
					if mom,ok:=mv.(*jsonOrderedMap); ok{ for _,mk:=range mom.keys{ if !explicit[mk] { if _,exists:=om.vals[mk]; !exists{om.keys=append(om.keys,mk)}; om.vals[mk]=mom.vals[mk] } } }
				}
				continue
			}
			ks:=jsonKeyString(k)
			jv,err:=nodeToJSONValue(v); if err!=nil{return nil,err}
			if _,exists:=om.vals[ks]; !exists{om.keys=append(om.keys,ks)}
			om.vals[ks]=jv
		}
		return om,nil
	}
	return nil,nil
}
func jsonKeyString(k *yaml.Node) string {
	k=derefAlias(k)
	if k.Kind==yaml.ScalarNode{
		if k.Tag=="!!timestamp"{ if t,err:=parseTimestamp(k.Value); err==nil{return formatTimestamp(t)} }
		return k.Value
	}
	s,_:=encodeYAML(k,2,false); return strings.TrimSpace(s)
}
func formatJSONFloat(f float64) string {
	// Use Go encoding/json float formatting: 'g' with special exponent cleanup.
	// strconv FormatFloat with 'g' may produce e+ etc valid json.
	s:=strconv.FormatFloat(f,'g',-1,64)
	return s
}
func marshalJSONCompact(v jsonValue)(string,error){
	var b strings.Builder; err:=writeJSON(&b,v,"","",0,false); return b.String(),err
}
func marshalJSONIndent(v jsonValue,prefix,indent string)(string,error){
	var b strings.Builder; err:=writeJSON(&b,v,prefix,indent,0,true); return b.String(),err
}
func writeJSON(b *strings.Builder,v jsonValue,prefix,indent string,depth int,pretty bool) error {
	switch t:=v.(type){
	case nil: b.WriteString("null")
	case bool: if t{b.WriteString("true")}else{b.WriteString("false")}
	case jsonNumber: b.WriteString(string(t))
	case string: b.WriteString(strconv.Quote(t)) // Go Quote escapes < >? No, only control and quotes, leaves unicode as is (non-printable escaped) - acceptable
		// Note JSON must escape <?? no.
	case []jsonValue:
		if len(t)==0{b.WriteString("[]"); return nil}
		b.WriteString("[")
		for i,e:=range t{
			if i>0{b.WriteString(",")}
			if pretty{ b.WriteString("\n"); b.WriteString(prefix); for k:=0;k<depth+1;k++{b.WriteString(indent)} }
			if err:=writeJSON(b,e,prefix,indent,depth+1,pretty); err!=nil{return err}
		}
		if pretty{ b.WriteString("\n"); b.WriteString(prefix); for k:=0;k<depth;k++{b.WriteString(indent)} }
		b.WriteString("]")
	case *jsonOrderedMap:
		if len(t.keys)==0{b.WriteString("{}"); return nil}
		b.WriteString("{")
		for i,k:=range t.keys{
			if i>0{b.WriteString(",")}
			if pretty{ b.WriteString("\n"); b.WriteString(prefix); for kk:=0;kk<depth+1;kk++{b.WriteString(indent)} }
			b.WriteString(strconv.Quote(k)); b.WriteString(":")
			if pretty{b.WriteString(" ")}
			if err:=writeJSON(b,t.vals[k],prefix,indent,depth+1,pretty); err!=nil{return err}
		}
		if pretty{ b.WriteString("\n"); b.WriteString(prefix); for kk:=0;kk<depth;kk++{b.WriteString(indent)} }
		b.WriteString("}")
	default:
		b.WriteString(strconv.Quote(fmt.Sprintf("%v",t)))
	}
	return nil
}

// PROPS output
func encodeProps(n *yaml.Node)(string,error){
	var lines []string
	flattenProps("",derefAlias(n),&lines)
	if len(lines)==0{return "",nil}
	return strings.Join(lines,"\n")+"\n",nil
}
func flattenProps(prefix string,n *yaml.Node,lines *[]string){
	n=derefAlias(n)
	switch n.Kind{
	case yaml.MappingNode:
		// comments? attach head comment of key as "# comment" line before? For props output from props input preserving comments - implement: if key node has HeadComment, emit "# <comment>" lines before its flattened entries (only first entry below that key?)
		for i:=0;i+1<len(n.Content);i+=2{
			k:=n.Content[i]; v:=n.Content[i+1]
			key:=scalarStringOfKey(k)
			full:=key; if prefix!=""{full=prefix+"."+key}
			if k.HeadComment!=""{
				for _,cl:=range strings.Split(strings.TrimSpace(k.HeadComment),"\n"){ *lines=append(*lines,"# "+cl) }
			}
			flattenProps(full,v,lines)
		}
	case yaml.SequenceNode:
		for i,ch:=range n.Content{
			var full string
			if globalCfg.propertiesArrayBrackets {
				full=fmt.Sprintf("%s[%d]",prefix,i)
			} else {
				if prefix==""{full=fmt.Sprintf("%d",i)}else{full=fmt.Sprintf("%s.%d",prefix,i)}
			}
			flattenProps(full,ch,lines)
		}
	case yaml.ScalarNode:
		if prefix==""{
			// scalar root with @props gave just value + blank line (encode to string yields value) For output format props with scalar root, original? Printer may handle scalar root differently.
			*lines=append(*lines, propsScalarValue(n))
		} else {
			*lines=append(*lines, prefix+globalCfg.propertiesSeparator+propsScalarValue(n))
		}
	}
}
func scalarStringOfKey(k *yaml.Node) string { k=derefAlias(k); if k.Kind==yaml.ScalarNode{return k.Value}; s,_:=encodeYAML(k,2,false); return strings.TrimSpace(s) }
func propsScalarValue(n *yaml.Node) string {
	if n.Tag=="!!null"{ if n.Value==""{return ""}; return n.Value }
	return n.Value
}

// CSV/TSV
func encodeCSV(n *yaml.Node, sep rune)(string,error){
	n=derefAlias(n)
	if n.Kind!=yaml.SequenceNode{
		return "", fmt.Errorf("csv encoding only works for arrays, got: %s", nodeTagOrDefault(n))
	}
	var buf bytes.Buffer
	w:=csv.NewWriter(&buf); if sep!=0{w.Comma=sep}
	// Determine if array of maps or arrays or scalars
	if len(n.Content)>0 {
		first:=derefAlias(n.Content[0])
		if first.Kind==yaml.MappingNode{
			// header from first row keys (collect all keys in order across rows?)
			var headers []string; seen:=map[string]bool{}
			for _,row:=range n.Content{ r:=derefAlias(row); if r.Kind!=yaml.MappingNode{continue}; for i:=0;i+1<len(r.Content);i+=2{ ks:=scalarStringOfKey(r.Content[i]); if !seen[ks]{seen[ks]=true; headers=append(headers,ks)}}}
			// Empty seq of maps?
			if len(headers)>0{ w.Write(headers) }
			for _,row:=range n.Content{
				r:=derefAlias(row); rec:=make([]string,len(headers))
				if r.Kind==yaml.MappingNode{ for idx,h:=range headers{ for i:=0;i+1<len(r.Content);i+=2{ if scalarStringOfKey(r.Content[i])==h{ rec[idx]=csvCellString(r.Content[i+1]); break } } } }
				w.Write(rec)
			}
			w.Flush(); return buf.String(),w.Error()
		}
	}
	// array of arrays / scalars - each element is a row (if scalar, single column row)
	for _,row:=range n.Content{
		r:=derefAlias(row)
		if r.Kind==yaml.SequenceNode{
			rec:=make([]string,len(r.Content)); for i,ch:=range r.Content{rec[i]=csvCellString(ch)}; w.Write(rec)
		} else {
			w.Write([]string{csvCellString(r)})
		}
	}
	w.Flush(); return buf.String(),w.Error()
}
func csvCellString(n *yaml.Node) string {
	n=derefAlias(n)
	if n.Kind==yaml.ScalarNode{
		if n.Tag=="!!null"{return ""}
		return n.Value
	}
	// nested structure in cell: encode as JSON? or yaml? Original csv auto-parse reverses: complex values may be encoded as JSON string.
	s,err:=encodeJSON(n,0); if err==nil{ return strings.TrimSpace(s) }
	return ""
}

// SHELL output
func encodeShell(n *yaml.Node)(string,error){
	var lines []string
	flattenShell("",derefAlias(n),&lines)
	if len(lines)==0{return "",nil}
	return strings.Join(lines,"\n")+"\n",nil
}
func flattenShell(prefix string,n *yaml.Node,lines *[]string){
	n=derefAlias(n)
	sep:=globalCfg.shellKeySeparator; if sep==""{sep="_"}
	switch n.Kind{
	case yaml.MappingNode:
		for i:=0;i+1<len(n.Content);i+=2{
			k:=shellSanitizeKey(scalarStringOfKey(n.Content[i]))
			full:=k; if prefix!=""{full=prefix+sep+k}
			flattenShell(full,n.Content[i+1],lines)
		}
	case yaml.SequenceNode:
		for i,ch:=range n.Content{
			full:=fmt.Sprintf("%s%s%d",prefix,sep,i); if prefix==""{full=fmt.Sprintf("%d",i)}
			flattenShell(full,ch,lines)
		}
	case yaml.ScalarNode:
		if prefix==""{ *lines=append(*lines, shellQuoteValue(n)) } else { *lines=append(*lines, prefix+"="+shellQuoteValue(n)) }
	}
}
func shellSanitizeKey(s string) string {
	// replace non [A-Za-z0-9_] with separator? Original shell encoder likely uses a sanitizer
	var b strings.Builder
	for _,r:=range s{ if (r>='A'&&r<='Z')||(r>='a'&&r<='z')||(r>='0'&&r<='9')||r=='_'{b.WriteRune(r)}else{b.WriteString(globalCfg.shellKeySeparator)} }
	res:=b.String(); if res==""{res="_"}; return res
}
func shellQuoteValue(n *yaml.Node) string {
	// For !str strings containing spaces/specials, single quote with escaping: 'x y' ; numbers/bools unquoted
	if n.Tag!="!!str"{
		if n.Tag=="!!null"{return ""}
		return n.Value
	}
	s:=n.Value
	if s==""{return "''"}
	// safe chars: alphanumeric and _-.,:/ etc no quote
	safe:=true; for _,r:=range s{ if !((r>='A'&&r<='Z')||(r>='a'&&r<='z')||(r>='0'&&r<='9')||strings.ContainsRune("_-.,:/@\n",r)){safe=false;break} }
	// newline in shellescape becomes quoted with actual newline?
	if safe && !strings.Contains(s,"\n"){return s}
	return "'" + strings.ReplaceAll(s,"'","'\"'\"'") + "'"
}

// shell escape for @sh operator - mimic shellescape.Quote behaviour observed
func shellEscape(s string) string {
	if s==""{return ""}
	// Based on observations:
	// safe prefix chars [a-zA-Z0-9_-.,:/\n] are left unquoted; first unsafe char triggers single-quoting of remainder, but single quote itself is escaped as \'
	// Let's examine algorithm: we can implement state machine:
	// Iterate runes, keep a buffer. When char is safe and we're not in quotes, append. When char is single quote: close quote if in, append \', (remain out?)
	// When char unsafe (not single quote): if not in quotes, open '; append char; in quotes at end close.
	var b strings.Builder
	inQ:=false
	for _,r:=range s{
		if r=='\''{
			if inQ{ b.WriteString("'"); inQ=false }
			b.WriteString("\\'")
			continue
		}
		if isShellSafe(r){
			if inQ{
				// safe chars inside quotes remain quoted until end? In observed "a b c", after opening at first space, b etc stayed in quotes until end.
				b.WriteRune(r)
			} else {
				b.WriteRune(r)
			}
			continue
		}
		// unsafe
		if !inQ{ b.WriteString("'"); inQ=true }
		b.WriteRune(r)
	}
	if inQ{ b.WriteString("'") }
	return b.String()
}
func isShellSafe(r rune) bool {
	if (r>='a'&&r<='z')||(r>='A'&&r<='Z')||(r>='0'&&r<='9'){return true}
	switch r{case '_','-',',',':','/','\n': return true}
	// '.' is safe? probe later; shellescape safe set includes . ?
	if r=='.'{return true}
	return false
}
