	}
	return strings.Join(outLines,"")
}

// JSON
func encodeJSON(n *yaml.Node, indent int)(string,error){
	v,err:=nodeToJSONValue(n); if err!=nil{return "",err}
	var buf bytes.Buffer
	if indent==0 {
		// compact
		s,err:=marshalJSONCompact(v); if err!=nil{return "",err}; return s+"\n",nil // tojson(0) printed without extra blank line in probe when used as value? encodeNodeToString returns string ending \n; printer with json format uses this and adds? We'll handle printer separately not double.
	}
	prefix:=""; indentStr:=strings.Repeat(" ",indent)
	s,err:=marshalJSONIndent(v,prefix,indentStr); if err!=nil{return "",err}
	buf.WriteString(s); buf.WriteString("\n")
	return buf.String(),nil
}

// We implement JSON marshaling ourselves to control number handling and HTML escaping.
type jsonValue interface{}
type jsonOrderedMap struct{ keys []string; vals map[string]jsonValue }
type jsonNumber string

func nodeToJSONValue(n *yaml.Node)(jsonValue,error){
	n=derefAlias(n)
	switch n.Kind{
	case yaml.ScalarNode:
		switch n.Tag{
		case "!!null": return nil,nil
		case "!!bool": return parseBool(n.Value),nil
		case "!!int":
			// preserve integer as number; convert hex etc to decimal
			v,ok:=parseNumberValue(n.Value); if !ok{return n.Value,nil}
			switch t:=v.(type){case int64: return jsonNumber(strconv.FormatInt(t,10)),nil; case uint64: return jsonNumber(strconv.FormatUint(t,10)),nil; case float64: return jsonNumber(formatJSONFloat(t)),nil}
			return jsonNumber(n.Value),nil
		case "!!float":
			v,ok:=parseNumberValue(n.Value); if !ok{return n.Value,nil}
			if f,ok:=v.(float64); ok {
				// inf/nan cannot json - original errors? Return error matching Go json: "json: unsupported value: +Inf"
			}
			switch t:=v.(type){case int64: return jsonNumber(strconv.FormatInt(t,10)),nil; case float64: return jsonNumber(formatJSONFloat(t)),nil}
			return jsonNumber(n.Value),nil
		case "!!timestamp":
			t,err:=parseTimestamp(n.Value); if err==nil{ return formatTimestamp(t),nil }; return n.Value,nil
		default:
			return n.Value,nil
		}
	case yaml.SequenceNode:
		var arr []jsonValue; for _,ch:=range n.Content{ v,err:=nodeToJSONValue(ch); if err!=nil{return nil,err}; arr=append(arr,v)}; if arr==nil{arr=[]jsonValue{}}; return arr,nil
	case yaml.MappingNode:
		om:=&jsonOrderedMap{vals:map[string]jsonValue{}}
		// handle merge keys: first collect merged entries then explicit override? YAML decode semantics: merge keys have lower priority.
		// Implement: process merge keys first, then explicit in order (new keys appended, existing keys keep first position? Go yaml map decode order not relevant. JSON order likely explicit order with merged at merge position if not overridden... simplify below sequential processing: when encountering <<, insert merged pairs if not already present nor present as explicit later - pre-scan explicit keys.
		explicit:=map[string]bool{}
		for i:=0;i+1<len(n.Content);i+=2{ k:=n.Content[i]; if k.Tag!="!!merge" && k.Value!="<<" { explicit[jsonKeyString(k)]=true } }
		for i:=0;i+1<len(n.Content);i+=2{
			k:=n.Content[i]; v:=n.Content[i+1]
			if k.Tag=="!!merge" || k.Value=="<<" {
				mergedMaps:=mergeSourceMaps(v)
				for _,mm:=range mergedMaps{
					mv,err:=nodeToJSONValue(mm); if err!=nil{return nil,err}
					if mom,ok:=mv.(*jsonOrderedMap); ok{ for _,mk:=range mom.keys{ if !explicit[mk] { if _,exists:=om.vals[mk]; !exists{om.keys=append(om.keys,mk)}; om.vals[mk]=mom.vals[mk] } } }
				}
				continue
			}
			ks:=jsonKeyString(k)
			jv,err:=nodeToJSONValue(v); if err!=nil{return nil,err}
			if _,exists:=om.vals[ks]; !exists{om.keys=append(om.keys,ks)}
			om.vals[ks]=jv
		}
		return om,nil
	}
	return nil,nil
}
func jsonKeyString(k *yaml.Node) string {
	k=derefAlias(k)
	if k.Kind==yaml.ScalarNode{
		if k.Tag=="!!timestamp"{ if t,err:=parseTimestamp(k.Value); err==nil{return formatTimestamp(t)} }
		return k.Value
	}
	s,_:=encodeYAML(k,2,false); return strings.TrimSpace(s)
}
func formatJSONFloat(f float64) string {
	// Use Go encoding/json float formatting: 'g' with special exponent cleanup.
	// strconv FormatFloat with 'g' may produce e+ etc valid json.
	s:=strconv.FormatFloat(f,'g',-1,64)
	return s
}
func marshalJSONCompact(v jsonValue)(string,error){
	var b strings.Builder; err:=writeJSON(&b,v,"","",0,false); return b.String(),err
}
func marshalJSONIndent(v jsonValue,prefix,indent string)(string,error){
	var b strings.Builder; err:=writeJSON(&b,v,prefix,indent,0,true); return b.String(),err
}
func writeJSON(b *strings.Builder,v jsonValue,prefix,indent string,depth int,pretty bool) error {
	switch t:=v.(type){
	case nil: b.WriteString("null")
	case bool: if t{b.WriteString("true")}else{b.WriteString("false")}
	case jsonNumber: b.WriteString(string(t))
	case string: b.WriteString(strconv.Quote(t)) // Go Quote escapes < >? No, only control and quotes, leaves unicode as is (non-printable escaped) - acceptable
		// Note JSON must escape <?? no.
	case []jsonValue:
		if len(t)==0{b.WriteString("[]"); return nil}
		b.WriteString("[")
		for i,e:=range t{
			if i>0{b.WriteString(",")}
			if pretty{ b.WriteString("\n"); b.WriteString(prefix); for k:=0;k<depth+1;k++{b.WriteString(indent)} }
			if err:=writeJSON(b,e,prefix,indent,depth+1,pretty); err!=nil{return err}
		}
		if pretty{ b.WriteString("\n"); b.WriteString(prefix); for k:=0;k<depth;k++{b.WriteString(indent)} }
		b.WriteString("]")
	case *jsonOrderedMap:
		if len(t.keys)==0{b.WriteString("{}"); return nil}
		b.WriteString("{")
		for i,k:=range t.keys{
			if i>0{b.WriteString(",")}
			if pretty{ b.WriteString("\n"); b.WriteString(prefix); for kk:=0;kk<depth+1;kk++{b.WriteString(indent)} }
			b.WriteString(strconv.Quote(k)); b.WriteString(":")
			if pretty{b.WriteString(" ")}
			if err:=writeJSON(b,t.vals[k],prefix,indent,depth+1,pretty); err!=nil{return err}
		}
		if pretty{ b.WriteString("\n"); b.WriteString(prefix); for kk:=0;kk<depth;kk++{b.WriteString(indent)} }
		b.WriteString("}")
	default:
		b.WriteString(strconv.Quote(fmt.Sprintf("%v",t)))
	}
	return nil
}

// PROPS output
func encodeProps(n *yaml.Node)(string,error){
	var lines []string
	flattenProps("",derefAlias(n),&lines)
