				m.Content=append(m.Content,stringNode(globalCfg.xmlAttrPrefix+an),stringNode(at.Value))
			}
			stack=append(stack,fr)
		case xml.EndElement:
			if len(stack)==0{ return nil, fmt.Errorf("invalid XML: unexpected end element") }
