func unescapeTOMLString(s string) string {
	var b strings.Builder
	for i:=0;i<len(s);i++{ if s[i]=='\\'&&i+1<len(s){ switch s[i+1]{case 'n':b.WriteByte('\n');i++;case 't':b.WriteByte('\t');i++;case 'r':b.WriteByte('\r');i++;case '"':b.WriteByte('"');i++;case '\\':b.WriteByte('\\');i++;default:b.WriteByte(s[i])} } else {b.WriteByte(s[i])} }
