}
func encodeTOML(n *yaml.Node)(string,error){
	n=derefAlias(n)
	if n.Kind!=yaml.MappingNode{
		// top level must be table; if scalar, original errors? We'll encode as a bare value? Probe later.
		return "",fmt.Errorf("cannot encode %s as toml, only maps supported",nodeTagOrDefault(n))
	}
	var b strings.Builder
	writeTOMLTable(&b,n, "")
