}
func writeTOMLTable(b *strings.Builder,m *yaml.Node,prefix string){
	// First scalar/simple entries, then sub-tables, then arrays of tables. TOML requires scalar keys before tables within a section.
	type entry struct{k string; v *yaml.Node; kn *yaml.Node}
	var scalars, tables, arrTables []entry
	for i:=0;i+1<len(m.Content);i+=2{
		k:=scalarStringOfKey(m.Content[i]); v:=derefAlias(m.Content[i+1])
		if v.Kind==yaml.MappingNode{ tables=append(tables,entry{k,v,m.Content[i]}) } else if v.Kind==yaml.SequenceNode && len(v.Content)>0 && derefAlias(v.Content[0]).Kind==yaml.MappingNode { arrTables=append(arrTables,entry{k,v,m.Content[i]}) } else { scalars=append(scalars,entry{k,v,m.Content[i]}) }
	}
	for _,e:=range scalars{
		b.WriteString(tomlKey(e.k)+" = "+tomlValue(e.v)+"\n")
	}
	for _,e:=range tables{
		full:=e.k; if prefix!=""{full=prefix+"."+e.k}
		b.WriteString("\n["+tomlKeyPath(full)+"]\n")
		writeTOMLTable(b,e.v,full)
	}
	for _,e:=range arrTables{
		full:=e.k; if prefix!=""{full=prefix+"."+e.k}
		for _,elem:=range e.v.Content{
			b.WriteString("\n[["+tomlKeyPath(full)+"]]\n")
			writeTOMLTable(b,derefAlias(elem),full)
		}
	}
}
func tomlKeyPath(s string) string { parts:=strings.Split(s,"."); for i,p:=range parts{parts[i]=tomlKey(p)}; return strings.Join(parts,".") }
func tomlKey(s string) string {
	// bare key if [A-Za-z0-9_-]+ else quoted
	for _,r:=range s{ if !((r>='A'&&r<='Z')||(r>='a'&&r<='z')||(r>='0'&&r<='9')||r=='_'||r=='-'){return strconv.Quote(s)} }
	if s==""{return strconv.Quote(s)}
	return s
}
func tomlValue(n *yaml.Node) string {
	n=derefAlias(n)
	switch n.Kind{
	case yaml.ScalarNode:
		switch n.Tag{
		case "!!str": return strconv.Quote(n.Value)
		case "!!int","!!float","!!bool": return n.Value
		case "!!timestamp": return n.Value
		case "!!null": return "\"\"" // toml has no null - original error? probe later
		default: return strconv.Quote(n.Value)
		}
	case yaml.SequenceNode:
		var parts []string; for _,ch:=range n.Content{parts=append(parts,tomlValue(ch))}; return "["+strings.Join(parts,", ")+"]"
	case yaml.MappingNode:
		var parts []string; for i:=0;i+1<len(n.Content);i+=2{parts=append(parts, tomlKey(scalarStringOfKey(n.Content[i]))+" = "+tomlValue(n.Content[i+1]))}; return "{"+strings.Join(parts,", ")+"}"
	}
	return strconv.Quote(n.Value)
}

// INI encode
func encodeINI(n *yaml.Node)(string,error){
	n=derefAlias(n)
	if n.Kind!=yaml.MappingNode{ return "",fmt.Errorf("cannot encode %s as ini",nodeTagOrDefault(n)) }
	var b strings.Builder
	// root scalars first
	type entry struct{k string;v *yaml.Node}
	var scalars, sections []entry
	for i:=0;i+1<len(n.Content);i+=2{ k:=scalarStringOfKey(n.Content[i]); v:=derefAlias(n.Content[i+1]); if v.Kind==yaml.MappingNode{sections=append(sections,entry{k,v})}else{scalars=append(scalars,entry{k,v})} }
	for _,e:=range scalars{ writeINIValue(&b,e.k,e.v) }
	for _,s:=range sections{
