func writeINIValue(b *strings.Builder,k string,v *yaml.Node){
	v=derefAlias(v)
	if v.Kind==yaml.SequenceNode{ for _,ch:=range v.Content{ b.WriteString(k+" = "+scalarXMLElementText(ch)+"\n") }; return }
	b.WriteString(k+" = "+scalarXMLElementText(v)+"\n")
}

