	}
	return nil, fmt.Errorf("bad expression, please check expression syntax")
}

// KYAML encode
func encodeKYAML(n *yaml.Node, indent int)(string,error){
	var b strings.Builder
	writeKYAML(&b,derefAlias(n),0,indent)
	b.WriteString("\n")
	return b.String(),nil
}
func writeKYAML(b *strings.Builder,n *yaml.Node,depth,indent int){
	n=derefAlias(n)
	ind:=func(d int)string{return strings.Repeat(" ",indent*d)}
	switch n.Kind{
	case yaml.MappingNode:
		if len(n.Content)==0{b.WriteString("{}"); return}
		b.WriteString("{\n")
		for i:=0;i+1<len(n.Content);i+=2{
			b.WriteString(ind(depth+1))
			// key: unquoted if simple else quoted?
			b.WriteString(kyamlScalarString(n.Content[i],true))
			b.WriteString(": ")
			writeKYAML(b,n.Content[i+1],depth+1,indent)
			b.WriteString(",\n")
		}
		b.WriteString(ind(depth)+"}")
	case yaml.SequenceNode:
		if len(n.Content)==0{b.WriteString("[]"); return}
		b.WriteString("[\n")
		for _,ch:=range n.Content{
			b.WriteString(ind(depth+1))
			writeKYAML(b,ch,depth+1,indent)
			b.WriteString(",\n")
		}
		b.WriteString(ind(depth)+"]")
	case yaml.ScalarNode:
		b.WriteString(kyamlScalarString(n,false))
	default:
		b.WriteString("null")
	}
}
func kyamlScalarString(n *yaml.Node,isKey bool) string {
	n=derefAlias(n)
	if n.Kind!=yaml.ScalarNode{ s,_:=encodeKYAML(n,2); return strings.TrimSpace(s) }
	switch n.Tag{
	case "!!str":
		// strings are quoted? Probe in tuning. Keys: plain if identifier-like.
		if isKey && isSimpleKey(n.Value){return n.Value}
		// Value strings in KYAML appear as ??? We'll need probe. Assume quoted with double quotes if needed else plain? Kubernetes KYAML uses JSON-ish but strings maybe plain or quoted depending.
		// Use JSON quote for safety; tuning will correct.
		return strconv.Quote(n.Value)
	case "!!null": return "null"
	default: return n.Value
	}
}
func isSimpleKey(s string) bool { if s==""{return false}; for i,r:=range s{ if !((r>='a'&&r<='z')||(r>='A'&&r<='Z')||r=='_'||r=='-'||(i>0&&r>='0'&&r<='9')||r=='.'||r=='/'){return false} }; return true }

// TOML decode/encode (subset)
func decodeTOML(data []byte)(*yaml.Node,error){
	root:=mapNode()
	current:=root
	lines:=strings.Split(string(data),"\n")
	// Handle multiline strings/arrays by joining lines until balanced - simple approach: preprocess logical lines
	logical:=joinTOMLLogicalLines(lines)
	for _,rawLine:=range logical{
		line:=strings.TrimSpace(stripTOMLComment(rawLine))
		if line==""{continue}
		if strings.HasPrefix(line,"[[") && strings.HasSuffix(line,"]]" ){
			path:=parseTOMLKeyPath(strings.TrimSpace(line[2:len(line)-2]))
			current=tomlNavigateArrayTable(root,path)
			continue
		}
		if strings.HasPrefix(line,"[") && strings.HasSuffix(line,"]"){
			path:=parseTOMLKeyPath(strings.TrimSpace(line[1:len(line)-1]))
			current=tomlNavigateTable(root,path)
			continue
		}
		eq:=findTOMLEquals(line)
		if eq<0{ return nil, fmt.Errorf("expected character =") }
		keyPart:=strings.TrimSpace(line[:eq]); valPart:=strings.TrimSpace(line[eq+1:])
		path:=parseTOMLKeyPath(keyPart)
		valNode,err:=parseTOMLValue(valPart); if err!=nil{return nil,err}
		// insert nested dotted key
		target:=current
		for _,p:=range path[:len(path)-1]{ target=tomlNavigateTable(target,[]string{p}) }
		last:=path[len(path)-1]
		// replace if exists
		pos:=-1; for i:=0;i+1<len(target.Content);i+=2{ if target.Content[i].Value==last{pos=i;break}}
		if pos>=0{target.Content[pos+1]=valNode}else{target.Content=append(target.Content,stringNode(last),valNode)}
	}
	return root,nil
}
func joinTOMLLogicalLines(lines []string) []string {
	var out []string; var cur strings.Builder; depth:=0; inML:=false; mlTriple:=""
	for _,ln:=range lines{
		if cur.Len()>0{cur.WriteString("\n")}
		cur.WriteString(ln)
		// update state naively counting triple quotes and brackets outside strings is hard. Simple: count ''' and """ occurrences
		if !inML{
			if strings.Contains(ln,"\"\"\""){ if strings.Count(ln,"\"\"\"")%2==1{inML=true; mlTriple="\"\"\""} }
			if strings.Contains(ln,"'''"){ if strings.Count(ln,"'''")%2==1{inML=true; mlTriple="'''"} }
		} else {
			if strings.Contains(ln,mlTriple){inML=false}
		}
		if !inML{
			// bracket depth (ignore brackets in strings roughly)
			for _,ch:=range ln{ if ch=='['||ch=='{'{depth++}; if ch==']'||ch=='}'{depth--} }
			if depth<=0{depth=0; out=append(out,cur.String()); cur.Reset()}
		}
	}
	if cur.Len()>0{out=append(out,cur.String())}
	return out
}
func stripTOMLComment(s string) string {
	// Remove # comments not inside strings (basic)
	inStr:=byte(0)
	for i:=0;i<len(s);i++{
		if inStr!=0{ if s[i]==inStr && s[i-1]!='\\'{inStr=0}; continue }
		if s[i]=='"'||s[i]=='\''{inStr=s[i]; continue}
		if s[i]=='#'{return s[:i]}
	}
	return s
}
func parseTOMLKeyPath(s string) []string {
	var parts []string; var cur strings.Builder; inQ:=byte(0)
	for i:=0;i<len(s);i++{
		ch:=s[i]
		if inQ!=0{ if ch==inQ{inQ=0}else{cur.WriteByte(ch)}; continue }
		if ch=='"'||ch=='\''{inQ=ch; continue}
		if ch=='.'{parts=append(parts,strings.TrimSpace(cur.String())); cur.Reset(); continue}
		cur.WriteByte(ch)
	}
	parts=append(parts,strings.TrimSpace(cur.String()))
	return parts
}
func tomlNavigateTable(root *yaml.Node, path []string) *yaml.Node {
	cur:=root
	for _,p:=range path{
		var found *yaml.Node
		for i:=0;i+1<len(cur.Content);i+=2{ if cur.Content[i].Value==p{ v:=derefAlias(cur.Content[i+1]); if v.Kind==yaml.MappingNode{found=v}; break } }
		if found==nil{ m:=mapNode(); cur.Content=append(cur.Content,stringNode(p),m); cur=m } else {cur=found}
	}
	return cur
}
func tomlNavigateArrayTable(root *yaml.Node, path []string) *yaml.Node {
	if len(path)==0{return root}
	parent:=tomlNavigateTable(root,path[:len(path)-1])
	last:=path[len(path)-1]
	var arr *yaml.Node; pos:=-1
	for i:=0;i+1<len(parent.Content);i+=2{ if parent.Content[i].Value==last{arr=parent.Content[i+1]; pos=i; break}}
	if arr==nil || arr.Kind!=yaml.SequenceNode{ arr=seqNode(); if pos>=0{parent.Content[pos+1]=arr}else{parent.Content=append(parent.Content,stringNode(last),arr)} }
	m:=mapNode(); arr.Content=append(arr.Content,m); return m
}
func findTOMLEquals(s string) int { inQ:=byte(0); for i:=0;i<len(s);i++{ if inQ!=0{ if s[i]==inQ{inQ=0}; continue}; if s[i]=='"'||s[i]=='\''{inQ=s[i]; continue}; if s[i]=='=' {return i} }; return -1 }
func parseTOMLValue(s string)(*yaml.Node,error){
	s=strings.TrimSpace(s)
	if s==""{return stringNode(""),nil}
	// array
	if strings.HasPrefix(s,"[") {
		// need find matching ]
		elems,err:=splitTOMLArray(s); if err!=nil{return nil,err}
		seq:=seqNode(); for _,e:=range elems{ if strings.TrimSpace(e)==""{continue}; vn,err:=parseTOMLValue(e); if err!=nil{return nil,err}; seq.Content=append(seq.Content,vn)}; return seq,nil
	}
	if strings.HasPrefix(s,"{") {
		// inline table
		inner:=strings.TrimSpace(s[1:len(s)-1])
		mp:=mapNode(); if inner==""{return mp,nil}
		parts:=splitTopLevel(inner,',')
		for _,p:=range parts{ eq:=findTOMLEquals(p); if eq<0{continue}; k:=strings.TrimSpace(p[:eq]); kp:=parseTOMLKeyPath(k); vn,err:=parseTOMLValue(strings.TrimSpace(p[eq+1:])); if err!=nil{return nil,err}; target:=mp; for _,seg:=range kp[:len(kp)-1]{target=tomlNavigateTable(target,[]string{seg})}; target.Content=append(target.Content,stringNode(kp[len(kp)-1]),vn)}
		return mp,nil
	}
	if strings.HasPrefix(s,"\"\"\""){
		end:=strings.LastIndex(s,"\"\"\""); content:=s[3:end]; content=strings.TrimPrefix(content,"\n"); return stringNode(unescapeTOMLString(content)),nil
	}
	if strings.HasPrefix(s,"'''"){
		end:=strings.LastIndex(s,"'''"); content:=s[3:end]; content=strings.TrimPrefix(content,"\n"); return stringNode(content),nil
	}
	if strings.HasPrefix(s,"\""){
		// parse with Go string unquote after finding end quote
		// Use strconv.Unquote on the first quoted token
		// Find closing unescaped quote
		for i:=1;i<len(s);i++{ if s[i]=='"' && s[i-1]!='\\'{ str:=s[:i+1]; uq,err:=strconv.Unquote(str); if err!=nil{return stringNode(unescapeTOMLString(s[1:i])),nil}; return stringNode(uq),nil } }
		return stringNode(s),nil
	}
	if strings.HasPrefix(s,"'"){
		end:=strings.Index(s[1:],"'"); if end>=0{return stringNode(s[1:1+end]),nil}; return stringNode(s),nil
	}
	if s=="true"||s=="false"{return boolNode(s=="true"),nil}
	// datetime (contains T or date dashes with time) treat as timestamp if parseable and looks datetime
	if _,err:=parseTimestamp(s); err==nil && (strings.Contains(s,"T")||strings.Contains(s," ")|| regexpDateLike(s)){ return scalarNode("!!timestamp",s),nil }
	// numbers: strip underscores
	clean:=strings.ReplaceAll(s,"_","")
	if v,ok:=parseNumberValue(clean); ok{
		switch t:=v.(type){case int64: return scalarNode("!!int",clean),nil; _=t; case float64: return scalarNode("!!float",clean),nil; case uint64: return scalarNode("!!int",clean),nil}
		return scalarNode("!!int",clean),nil
	}
	return stringNode(s),nil
}
func regexpDateLike(s string) bool { return len(s)==10 && s[4]=='-' && s[7]=='-' }
func splitTOMLArray(s string)([]string,error){
	// s starts [ ends ]
	depth:=0; end:=-1
	for i,ch:=range s{ if ch=='['||ch=='{'{depth++}; if ch==']'||ch=='}'{depth--; if depth==0{end=i;break}} }
	if end<0{return nil,fmt.Errorf("expected character ]")}
	inner:=strings.TrimSpace(s[1:end]); if inner==""{return nil,nil}
	return splitTopLevel(inner,','),nil
}
func splitTopLevel(s string, sep rune) []string {
	var parts []string; depth:=0; inQ:=byte(0); start:=0
	for i:=0;i<len(s);i++{
		ch:=s[i]
		if inQ!=0{ if ch==inQ && s[i-1]!='\\'{inQ=0}; continue }
		if ch=='"'||ch=='\''{ /* triple handling ignore */ inQ=ch; continue }
		if ch=='['||ch=='{'||ch=='(' {depth++}
		if ch==']'||ch=='}'||ch==')' {depth--}
		if rune(ch)==sep && depth==0{ parts=append(parts,s[start:i]); start=i+1 }
	}
	parts=append(parts,s[start:]); return parts
}
func unescapeTOMLString(s string) string {
	var b strings.Builder
	for i:=0;i<len(s);i++{ if s[i]=='\\'&&i+1<len(s){ switch s[i+1]{case 'n':b.WriteByte('\n');i++;case 't':b.WriteByte('\t');i++;case 'r':b.WriteByte('\r');i++;case '"':b.WriteByte('"');i++;case '\\':b.WriteByte('\\');i++;default:b.WriteByte(s[i])} } else {b.WriteByte(s[i])} }
	return b.String()
