	return s
}
func tomlValue(n *yaml.Node) string {
	n=derefAlias(n)
	switch n.Kind{
	case yaml.ScalarNode:
		switch n.Tag{
		case "!!str": return strconv.Quote(n.Value)
		case "!!int","!!float","!!bool": return n.Value
		case "!!timestamp": return n.Value
		case "!!null": return "\"\"" // toml has no null - original error? probe later
		default: return strconv.Quote(n.Value)
		}
	case yaml.SequenceNode:
		var parts []string; for _,ch:=range n.Content{parts=append(parts,tomlValue(ch))}; return "["+strings.Join(parts,", ")+"]"
