func isSimpleKey(s string) bool { if s==""{return false}; for i,r:=range s{ if !((r>='a'&&r<='z')||(r>='A'&&r<='Z')||r=='_'||r=='-'||(i>0&&r>='0'&&r<='9')||r=='.'||r=='/'){return false} }; return true }

// TOML decode/encode (subset)
func decodeTOML(data []byte)(*yaml.Node,error){
	root:=mapNode()
	current:=root
	lines:=strings.Split(string(data),"\n")
