	logical:=joinTOMLLogicalLines(lines)
	for _,rawLine:=range logical{
		line:=strings.TrimSpace(stripTOMLComment(rawLine))
		if line==""{continue}
		if strings.HasPrefix(line,"[[") && strings.HasSuffix(line,"]]" ){
			path:=parseTOMLKeyPath(strings.TrimSpace(line[2:len(line)-2]))
			current=tomlNavigateArrayTable(root,path)
			continue
		}
		if strings.HasPrefix(line,"[") && strings.HasSuffix(line,"]"){
			path:=parseTOMLKeyPath(strings.TrimSpace(line[1:len(line)-1]))
			current=tomlNavigateTable(root,path)
			continue
		}
		eq:=findTOMLEquals(line)
		if eq<0{ return nil, fmt.Errorf("expected character =") }
		keyPart:=strings.TrimSpace(line[:eq]); valPart:=strings.TrimSpace(line[eq+1:])
		path:=parseTOMLKeyPath(keyPart)
		valNode,err:=parseTOMLValue(valPart); if err!=nil{return nil,err}
		// insert nested dotted key
		target:=current
		for _,p:=range path[:len(path)-1]{ target=tomlNavigateTable(target,[]string{p}) }
		last:=path[len(path)-1]
		// replace if exists
		pos:=-1; for i:=0;i+1<len(target.Content);i+=2{ if target.Content[i].Value==last{pos=i;break}}
		if pos>=0{target.Content[pos+1]=valNode}else{target.Content=append(target.Content,stringNode(last),valNode)}
	}
	return root,nil
}
func joinTOMLLogicalLines(lines []string) []string {
	var out []string; var cur strings.Builder; depth:=0; inML:=false; mlTriple:=""
	for _,ln:=range lines{
		if cur.Len()>0{cur.WriteString("\n")}
		cur.WriteString(ln)
		// update state naively counting triple quotes and brackets outside strings is hard. Simple: count ''' and """ occurrences
		if !inML{
			if strings.Contains(ln,"\"\"\""){ if strings.Count(ln,"\"\"\"")%2==1{inML=true; mlTriple="\"\"\""} }
			if strings.Contains(ln,"'''"){ if strings.Count(ln,"'''")%2==1{inML=true; mlTriple="'''"} }
		} else {
			if strings.Contains(ln,mlTriple){inML=false}
		}
		if !inML{
			// bracket depth (ignore brackets in strings roughly)
			for _,ch:=range ln{ if ch=='['||ch=='{'{depth++}; if ch==']'||ch=='}'{depth--} }
			if depth<=0{depth=0; out=append(out,cur.String()); cur.Reset()}
		}
	}
	if cur.Len()>0{out=append(out,cur.String())}
	return out
}
func stripTOMLComment(s string) string {
