	for i:=0;i<len(s);i++{
		if inStr!=0{ if s[i]==inStr && s[i-1]!='\\'{inStr=0}; continue }
		if s[i]=='"'||s[i]=='\''{inStr=s[i]; continue}
		if s[i]=='#'{return s[:i]}
