		if inQ!=0{ if ch==inQ{inQ=0}else{cur.WriteByte(ch)}; continue }
		if ch=='"'||ch=='\''{inQ=ch; continue}
		if ch=='.'{parts=append(parts,strings.TrimSpace(cur.String())); cur.Reset(); continue}
		cur.WriteByte(ch)
	}
	parts=append(parts,strings.TrimSpace(cur.String()))
