			// Could be block or object value: HCL encoder chooses blocks for nested maps at top? Observed a:1 => a=1; nested map likely becomes block { ... }. Probe tuning.
			b.WriteString(indent+k+" {\n")
			writeHCLBody(b,v,depth+1)
			b.WriteString(indent+"}\n")
		} else {
