func hclValue(n *yaml.Node,depth int) string {
	n=derefAlias(n)
	switch n.Kind{
	case yaml.ScalarNode:
		switch n.Tag{case "!!str": return strconv.Quote(n.Value); case "!!null": return "null"; default: return n.Value}
	case yaml.SequenceNode:
		var parts []string; for _,ch:=range n.Content{parts=append(parts,hclValue(ch,depth+1))}; return "["+strings.Join(parts,", ")+"]"
