		var parts []string; for i:=0;i+1<len(n.Content);i+=2{parts=append(parts, scalarStringOfKey(n.Content[i])+" = "+hclValue(n.Content[i+1],depth+1))}; return "{"+strings.Join(parts,", ")+"}"
	}
	return strconv.Quote(n.Value)
}
