// ---------- LUA decode ----------
// Minimal Lua parser for: return <table/value>, or a series of global assignments name = value, or just a table literal.
type luaParser struct{ s string; pos int }
func decodeLua(data []byte)(*yaml.Node,error){
	src:=string(data)
	p:=&luaParser{s:src}
	p.skip()
	// '@input line:1(column:4) near '1': syntax error' error format for invalid like "a: 1"
	// Detect return
	if p.consumeWord("return"){
		v,err:=p.parseLuaValue(); if err!=nil{return nil,err}
		p.skip(); if p.pos<len(p.s) && p.s[p.pos]==';'{p.pos++; p.skip()}
		if p.pos < len(p.s){ return nil, luaSyntaxError(p.s,p.pos) }
		return v,nil
	}
	// Try assignments or bare value
	save:=p.pos
	// check if starts with '{' or literal
	if p.pos<len(p.s) && (p.s[p.pos]=='{' || p.s[p.pos]=='"' || p.s[p.pos]=='\'' || isDigit(p.s[p.pos])) {
		v,err:=p.parseLuaValue(); if err==nil{ p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==';'{p.pos++}; p.skip(); if p.pos>=len(p.s){return v,nil} }
		p.pos=save
	}
	// Global assignments: name = value (separated by newlines/semicolons)
	root:=mapNode(); hasAny:=false
	for{
		p.skip()
		if p.pos>=len(p.s){break}
		name,err:=p.parseLuaIdent(); if err!=nil{return nil, luaSyntaxError(p.s,p.pos)}
		p.skip()
		if p.pos>=len(p.s) || p.s[p.pos]!='=' { return nil, luaSyntaxError(p.s,p.pos) }
		p.pos++
		v,err:=p.parseLuaValue(); if err!=nil{return nil,err}
		root.Content=append(root.Content,stringNode(name),v); hasAny=true
		p.skip(); if p.pos<len(p.s)&&(p.s[p.pos]==';'||p.s[p.pos]==',' ){p.pos++}
	}
	if !hasAny{
		// empty input -> blank?
		if strings.TrimSpace(src)==""{return blankNullNode(),nil}
		return nil, luaSyntaxError(p.s,0)
	}
