}
func luaSyntaxError(s string,pos int) error {
	// Format observed: "@input line:1(column:4) near '1':   syntax error\n" wrapped by runner as Error: bad file '-': ...
	line:=1; col:=1; lastNL:=-1
	for i:=0;i<pos && i<len(s);i++{ if s[i]=='\n'{line++; lastNL=i} }
	col=pos-lastNL
	near:=""
