func (p *luaParser) skip(){
	for p.pos<len(p.s){
		if strings.HasPrefix(p.s[p.pos:],"--"){
			// comment to end line (block --[[ ]] handling simple)
			if strings.HasPrefix(p.s[p.pos:],"--[["){ end:=strings.Index(p.s[p.pos:]," ]]"); if end>=0{ p.pos+=end+3; continue } }
			for p.pos<len(p.s)&&p.s[p.pos]!='\n'{p.pos++}; continue
		}
		c:=p.s[p.pos]; if c==' '||c=='\t'||c=='\n'||c=='\r'{p.pos++; continue}; break
