func (p *luaParser) consumeWord(w string) bool {
	p.skip(); if strings.HasPrefix(p.s[p.pos:],w){
		after:=p.pos+len(w); if after>=len(p.s)||!isVarChar(p.s[after]){p.pos=after; return true}
	}
