func (p *luaParser) parseLuaValue()(*yaml.Node,error){
	p.skip(); if p.pos>=len(p.s){return nil,luaSyntaxError(p.s,p.pos)}
	c:=p.s[p.pos]
	switch{
	case c=='{': return p.parseLuaTable()
	case c=='"'||c=='\'':
		s,err:=p.parseLuaString(); return stringNode(s),err
	case c=='['&& p.pos+1<len(p.s)&&p.s[p.pos+1]=='[':
