		end:=strings.Index(p.s[p.pos+2:],"]]") ; if end<0{return nil,luaSyntaxError(p.s,p.pos)}; content:=p.s[p.pos+2:p.pos+2+end]; p.pos+=2+end+2; content=strings.TrimPrefix(content,"\n"); return stringNode(content),nil
