		// keywords true/false/nil or ident reference (treat as string?)
		if p.consumeWord("true"){return boolNode(true),nil}
		if p.consumeWord("false"){return boolNode(false),nil}
		if p.consumeWord("nil"){return nullNode(),nil}
		return nil,luaSyntaxError(p.s,p.pos)
