}
func (p *luaParser) parseLuaString()(string,error){
	quote:=p.s[p.pos]; p.pos++; var b strings.Builder
	for p.pos<len(p.s){
		c:=p.s[p.pos]
		if c=='\\'&&p.pos+1<len(p.s){
			n:=p.s[p.pos+1]
			switch n{case 'n':b.WriteByte('\n');case 't':b.WriteByte('\t');case 'r':b.WriteByte('\r');case '\\':b.WriteByte('\\');case '"':b.WriteByte('"');case '\'':b.WriteByte('\'');default:b.WriteByte(n)}
