		p.skip(); if p.pos<len(p.s)&&(p.s[p.pos]==','||p.s[p.pos]==';'){p.pos++; continue}
		p.skip(); if p.pos<len(p.s)&&p.s[p.pos]=='}'{p.pos++; break}
