}

// ---------- LUA encode ----------
func encodeLua(n *yaml.Node)(string,error){
	n=derefAlias(n)
	var core string
	if globalCfg.luaGlobals && n.Kind==yaml.MappingNode{
		var lines []string
		for i:=0;i+1<len(n.Content);i+=2{
			k:=scalarStringOfKey(n.Content[i])
