// ---------- HCL ----------
func decodeHCL(data []byte)(*yaml.Node,error){
	// Minimal HCL parser: attributes and blocks.
	p:=&hclParser{s:string(data)}
	root,err:=p.parseBody(true)
	if err!=nil{return nil,err}
