}
type hclParser struct{s string; pos int}
func hclError(s string,pos int) error {
	// Format: "hcl parse error: input.hcl:1,1-2: Argument or block definition required; An argument or block definition is required here. To set an argument, use the equals sign \"=\" to introduce the argument value."
