func (p *hclParser) parseIdent()(string,error){
	p.skip(); start:=p.pos
	if start>=len(p.s)||!((p.s[start]>='A'&&p.s[start]<='Z')||(p.s[start]>='a'&&p.s[start]<='z')||p.s[start]=='_'){return "",hclError(p.s,start)}
