			p.pos++
			v,err:=p.parseHCLValue(); if err!=nil{return nil,err}
			addHCLMapEntry(root,name,v)
			continue
		}
		// block: labels (strings or idents) until {
		var labels []string
		for{
			p.skip()
			if p.pos<len(p.s)&&p.s[p.pos]=='{'{p.pos++; break}
			if p.pos<len(p.s)&&(p.s[p.pos]=='"'||p.s[p.pos]=='\''){
				// string label
				strv,err:=p.parseHCLString(); if err!=nil{return nil,err}; labels=append(labels,strv); continue
			}
			// ident label
			if p.pos<len(p.s)&&isIdentStart(p.s[p.pos]){
				lab,err:=p.parseIdent(); if err!=nil{return nil,err}; labels=append(labels,lab); continue
			}
			return nil,hclError(p.s,p.pos)
		}
		body,err:=p.parseBody(false); if err!=nil{return nil,err}
		// Nest by labels: block "a" "b" { } -> {name: {a: {b: body}}} ??? Common yq HCL handling: labels become nested keys.
		node:=body
		for i:=len(labels)-1;i>=0;i--{ m:=mapNode(stringNode(labels[i]),node); node=m }
		addHCLMapEntry(root,name,node)
	}
	return root,nil
}
func isIdentStart(c byte) bool { return (c>='A'&&c<='Z')||(c>='a'&&c<='z')||c=='_' }
func addHCLMapEntry(m *yaml.Node,name string,v *yaml.Node){
	for i:=0;i+1<len(m.Content);i+=2{
		if m.Content[i].Value==name{
			ex:=m.Content[i+1]
			// If both maps, merge? repeated blocks: convert to list? HCL yq lib (hclwrite?) may merge blocks of same type with different labels into a map.
			if ex.Kind==yaml.MappingNode && v.Kind==yaml.MappingNode{
				// merge keys recursively for labels case
				mergeMapsForHCL(ex,v); return
			}
			if ex.Kind==yaml.SequenceNode{ ex.Content=append(ex.Content,v); return }
			m.Content[i+1]=seqNode(ex,v); return
		}
	}
	m.Content=append(m.Content,stringNode(name),v)
}
func mergeMapsForHCL(dst,src *yaml.Node){
	for i:=0;i+1<len(src.Content);i+=2{
		sk:=src.Content[i].Value; sv:=src.Content[i+1]; found:=false
		for j:=0;j+1<len(dst.Content);j+=2{ if dst.Content[j].Value==sk{ if dst.Content[j+1].Kind==yaml.MappingNode&&sv.Kind==yaml.MappingNode{mergeMapsForHCL(dst.Content[j+1],sv)}else{ // append list
			ex:=dst.Content[j+1]; if ex.Kind==yaml.SequenceNode{ex.Content=append(ex.Content,sv)}else{dst.Content[j+1]=seqNode(ex,sv)} }; found=true; break } }
		if !found{dst.Content=append(dst.Content,src.Content[i],sv)}
	}
}
func (p *hclParser) parseHCLString()(string,error){
	p.skip(); if p.pos>=len(p.s){return "",hclError(p.s,p.pos)}
	// heredoc <<-EOT ... EOT
	if strings.HasPrefix(p.s[p.pos:],"<<"){
		// skip <<-? and marker
		p.pos+=2; if p.pos<len(p.s)&&p.s[p.pos]=='-' {p.pos++}
		p.skip()
		start:=p.pos; for p.pos<len(p.s)&&p.s[p.pos]!='\n'{p.pos++}; marker:=strings.TrimSpace(p.s[start:p.pos]); if p.pos<len(p.s){p.pos++}
		endMarker:="\n"+marker; idx:=strings.Index(p.s[p.pos:],endMarker); if idx<0{return "",hclError(p.s,p.pos)}; content:=p.s[p.pos:p.pos+idx+1]; p.pos+=idx+len(endMarker); return content,nil
	}
	quote:=p.s[p.pos]; p.pos++; var b strings.Builder
	for p.pos<len(p.s){
		c:=p.s[p.pos]
		if c=='\\'&&p.pos+1<len(p.s){ n:=p.s[p.pos+1]; switch n{case 'n':b.WriteByte('\n');case 't':b.WriteByte('\t');case 'r':b.WriteByte('\r');case '"':b.WriteByte('"');case '\\':b.WriteByte('\\');default:b.WriteByte(n)}; p.pos+=2; continue }
		if c==quote{p.pos++; return b.String(),nil}
		b.WriteByte(c); p.pos++
	}
	return "",hclError(p.s,p.pos)
}
func (p *hclParser) parseHCLValue()(*yaml.Node,error){
	p.skip(); if p.pos>=len(p.s){return nil,hclError(p.s,p.pos)}
	c:=p.s[p.pos]
	switch{
	case c=='"'|| strings.HasPrefix(p.s[p.pos:],"<<"):
		s,err:=p.parseHCLString(); if err!=nil{return nil,err}; n:=stringNode(s); n.Style=yaml.DoubleQuotedStyle; return n,nil
	case c=='[':
		p.pos++; seq:=seqNode()
		for{ p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==']'{p.pos++;break}; v,err:=p.parseHCLValue(); if err!=nil{return nil,err}; seq.Content=append(seq.Content,v); p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==','{p.pos++;continue} }
		return seq,nil
	case c=='{':
		p.pos++; mp:=mapNode()
		for{ p.skip(); if p.pos<len(p.s)&&p.s[p.pos]=='}'{p.pos++;break}
			// key could be ident or string; separator = or :
			var k string
			if p.s[p.pos]=='"' { s,err:=p.parseHCLString(); if err!=nil{return nil,err}; k=s } else { id,err:=p.parseIdent(); if err!=nil{return nil,err}; k=id }
			p.skip(); if p.pos<len(p.s)&&(p.s[p.pos]=='='||p.s[p.pos]==':'){p.pos++}else{return nil,hclError(p.s,p.pos)}
			v,err:=p.parseHCLValue(); if err!=nil{return nil,err}; mp.Content=append(mp.Content,stringNode(k),v); p.skip(); if p.pos<len(p.s)&&p.s[p.pos]==','{p.pos++}
		}
		return mp,nil
	case isDigit(c)||c=='-':
		start:=p.pos; if c=='-' {p.pos++}; for p.pos<len(p.s)&&(isDigit(p.s[p.pos])||p.s[p.pos]=='.'||p.s[p.pos]=='e'||p.s[p.pos]=='E'||p.s[p.pos]=='+'||p.s[p.pos]=='-'){
			if (p.s[p.pos]=='+'||p.s[p.pos]=='-') && !(p.s[p.pos-1]=='e'||p.s[p.pos-1]=='E'){break}; p.pos++ }
		txt:=p.s[start:p.pos]; if strings.ContainsAny(txt,".eE"){return scalarNode("!!float",txt),nil}; return scalarNode("!!int",txt),nil
	default:
		// ident reference / bool / null - read until delimiters but stop at operators? Expressions like var.foo, aws_instance.x.id, func(...)
		// Capture a balanced expression up to newline/comma/closing bracket at depth 0. HCL expressions can be complex (ternary, arithmetic). yq converts non-literal expressions to string? Probe later.
		start:=p.pos; depth:=0
		for p.pos<len(p.s){
			ch:=p.s[p.pos]
			if ch=='('||ch=='['||ch=='{'{depth++}
			if ch==')'||ch==']'||ch=='}'{ if depth==0{break}; depth-- }
			if depth==0 && (ch=='\n'&&false){break}
			if depth==0 && ch==',' {break}
			// Stop at newline only if we've seen a complete ident and next token could be new attribute? Harder: HCL attributes are newline separated. A reference alone ends at newline.
			if depth==0 && ch=='\n'{
				// peek: if expression so far ends with operator/function open, continue, else break
				trimmed:=strings.TrimSpace(p.s[start:p.pos]); if trimmed!="" && !strings.HasSuffix(trimmed,"+")&&!strings.HasSuffix(trimmed,"-")&&!strings.HasSuffix(trimmed,"*")&&!strings.HasSuffix(trimmed,"/")&&!strings.HasSuffix(trimmed,"?")&&!strings.HasSuffix(trimmed,":")&&!strings.HasSuffix(trimmed,"=") {break}
			}
			p.pos++
		}
		txt:=strings.TrimSpace(p.s[start:p.pos])
		if txt=="true"||txt=="false"{return boolNode(txt=="true"),nil}
		if txt=="null"{return nullNode(),nil}
		// Reference as string with double quoted style? Observed b{c="x"} gave string; references may appear as string node containing "var.xxx"?
		return stringNode(txt),nil
	}
}
func encodeHCL(n *yaml.Node)(string,error){
	n=derefAlias(n)
	if n.Kind!=yaml.MappingNode{ return "",fmt.Errorf("cannot encode %s as hcl",nodeTagOrDefault(n)) }
	var b strings.Builder
	writeHCLBody(&b,n,0)
	return b.String(),nil
}
func writeHCLBody(b *strings.Builder,m *yaml.Node,depth int){
	indent:=strings.Repeat("  ",depth)
	for i:=0;i+1<len(m.Content);i+=2{
		k:=scalarStringOfKey(m.Content[i]); v:=derefAlias(m.Content[i+1])
		if v.Kind==yaml.MappingNode{
			// Could be block or object value: HCL encoder chooses blocks for nested maps at top? Observed a:1 => a=1; nested map likely becomes block { ... }. Probe tuning.
			b.WriteString(indent+k+" {\n")
			writeHCLBody(b,v,depth+1)
			b.WriteString(indent+"}\n")
		} else {
			b.WriteString(indent+k+" = "+hclValue(v,depth)+"\n")
		}
	}
}
func hclValue(n *yaml.Node,depth int) string {
	n=derefAlias(n)
	switch n.Kind{
	case yaml.ScalarNode:
		switch n.Tag{case "!!str": return strconv.Quote(n.Value); case "!!null": return "null"; default: return n.Value}
	case yaml.SequenceNode:
		var parts []string; for _,ch:=range n.Content{parts=append(parts,hclValue(ch,depth+1))}; return "["+strings.Join(parts,", ")+"]"
	case yaml.MappingNode:
		var parts []string; for i:=0;i+1<len(n.Content);i+=2{parts=append(parts, scalarStringOfKey(n.Content[i])+" = "+hclValue(n.Content[i+1],depth+1))}; return "{"+strings.Join(parts,", ")+"}"
	}
	return strconv.Quote(n.Value)
}
