// Scanner to insert "eval" as default command if first positional arg is not a known command.
func preprocessCommandArgs(args []string, root *cobra.Command) []string {
	firstPos,found:=firstPositionalArg(args,root)
	if !found{
		return args
	}
	switch firstPos{
	case "eval","e","eval-all","ea","completion","shell-completion","__complete","__completeNoDesc":
		return args
	}
	// insert eval at beginning
	return append([]string{"eval"}, args...)
}

func firstPositionalArg(args []string, root *cobra.Command)(string,bool){
	fs:=root.PersistentFlags()
	local:=root.Flags()
	i:=0
	for i<len(args){
		a:=args[i]
		if a=="--"{
			if i+1<len(args){return args[i+1],true}
			return "",false
		}
		if a=="-"{
			i++; continue
		}
		if strings.HasPrefix(a,"--"){
			// long flag
			name:=a[2:]
			hasEq:=strings.Contains(name,"=")
			if hasEq{ name=strings.SplitN(name,"=",2)[0] }
			fl:=fs.Lookup(name); if fl==nil{fl=local.Lookup(name)}
			if fl!=nil && !hasEq{
				// if flag needs value (NoOptDefVal == "")
				if fl.NoOptDefVal==""{
					i+=2; continue
				}
			}
			if fl==nil{
				// unknown flag - let cobra handle as root (do not insert eval)?? Original --bad with no positional gave root usage; --bad .a (?) unknown.
				// To mirror --unknown --help root usage, return not found if remaining args contain ...? Simpler: if unknown flag occurs before any positional, don't insert.
				return "",false
			}
			i++; continue
		}
		if strings.HasPrefix(a,"-") && a!="-" {
			// shorthand cluster
			j:=1
			consumedNext:=false
			unknown:=false
			for j<len(a){
				ch:=a[j]
				fl:=fs.ShorthandLookup(string([]byte{ch})); if fl==nil{fl=local.ShorthandLookup(string([]byte{ch}))}
				if fl==nil{ unknown=true; break }
				if fl.NoOptDefVal==""{
					// needs value: either rest of arg is value or next arg
					if j+1 < len(a){
						// remainder is value (possibly starting with =)
						j=len(a)
					} else {
						consumedNext=true; j++
					}
					break
				}
				j++
			}
			if unknown{return "",false}
			i++; if consumedNext{i++}
			continue
		}
		// positional
		return a,true
	}
	return "",false
}

// stdin handling
var stdinBytes []byte
var stdinRead bool
var stdinErr error
func readStdinOnce()([]byte,error){
	if stdinRead{ return []byte{},stdinErr }
	stdinRead=true
	stdinBytes,stdinErr=io.ReadAll(os.Stdin)
	return stdinBytes,stdinErr
}
// For testing subsequent "-" reads after first, original reads EOF (empty). Track consumption:
var stdinConsumed bool
func readInputFile(filename string)([]byte,error){
	if filename=="-"{
		if stdinConsumed{ return []byte{},nil }
		stdinConsumed=true
		return readStdinOnce()
	}
	return os.ReadFile(filename)
}
func isFileArg(s string) bool {
	logDebug(fmt.Sprintf("checking '%s' is a file",s))
	fi,err:=os.Stat(s)
	if err!=nil{
		logDebug(fmt.Sprintf("error: stat %s: no such file or directory",s))
		logDebug("result: false")
		return false
	}
	res:=!fi.IsDir()
	logDebug(fmt.Sprintf("result: %v",res))
	_ = fi
	return res
}
