func setupRun(cmd *cobra.Command,args []string) (*runSetup,error){
	// Parse formats first (unknown format errors)
	inFmt,err:=normalizeFormat(globalCfg.inputFormatStr); if err!=nil{return nil,err}
	outFmtNorm,err:=normalizeFormat(globalCfg.outputFormatStr); if err!=nil{return nil,err}
	if inFmt=="shell"{
		return nil, fmt.Errorf("no support for %s input format", globalCfg.inputFormatStr)
	}
	// Front matter validation
	if globalCfg.frontMatter!="" && globalCfg.frontMatter!="extract" && globalCfg.frontMatter!="process"{
		// Original error? Probe later
		return nil, fmt.Errorf("front-matter must be either extract or process, got %s", globalCfg.frontMatter)
	}
	expression, files, err:=processExpressionAndFiles(args)
	if err!=nil{return nil,err}
	// null input files check
	if globalCfg.nullInput{
		// files here: if explicit files present (i.e., not just implicit "-")
		hasExplicit:=false
		for _,f:=range files{ if f!="-"{hasExplicit=true} }
		// Determine explicitness: processExpressionAndFiles adds "-" if no files; but for null input it shouldn't add. It currently doesn't add when nullInput - see that func.
		if hasExplicit{
			return nil, fmt.Errorf("cannot pass files in when using null-input flag")
		}
		files=nil
	}
	// Determine first filename for auto detection
	firstFilename:=""
	if len(files)>0{firstFilename=files[0]}
	// Input format resolution
	inputFormat:=inFmt
	detectedFormat, detectedDisplay:=formatFromFilename(firstFilename)
	if inputFormat=="auto"{
		logDebug(fmt.Sprintf("checking filename '%s' for auto format detection", displayFilename(firstFilename)))
		if firstFilename==""||firstFilename=="-"{
			logDebug("using default inputFormat 'yaml'")
			inputFormat="yaml"
		} else {
			inputFormat=detectedFormat
		}
	}
	// Output format resolution
	outputFormat:=outFmtNorm
	if outputFormat=="auto"{
		userSetInput:=!(globalCfg.inputFormatStr=="auto"||globalCfg.inputFormatStr=="a"||globalCfg.inputFormatStr=="")
		if userSetInput{
			outputFormat="yaml"
			// warn condition
			shouldWarn:=false
			if globalCfg.nullInput{ shouldWarn=true } else if len(files)>0 && files[0]!="-" { shouldWarn=true } else if len(files)==0 { shouldWarn=true }
			if shouldWarn{
				display:=detectedDisplay
				// when no file, yaml
				logWarn(fmt.Sprintf("yq default output is now 'auto' (based on the filename extension). Normally yq would output '%s', but for backwards compatibility 'yaml' has been set. Please use -oy to specify yaml, or drop the -p flag.",display))
			}
		} else {
			outputFormat=inputFormat
		}
	}
	if outputFormat=="auto"{outputFormat="yaml"}
	if inputFormat=="auto"{inputFormat="yaml"}
	globalCfg.inputFormat=inputFormat
	globalCfg.outputFormat=outputFormat
	// colors
	globalCfg.colorsEnabled=resolveColors()
	logDebug(fmt.Sprintf("Using input format %s",inputFormat))
	logDebug(fmt.Sprintf("Using output format %s",outputFormat))
	// Parse expression
	logDebug(fmt.Sprintf("Parsing expression: [%s]",expression))
	expr,err:=parseExpression(expression)
	if err!=nil{return nil,err}
	setup:=&runSetup{expression:expression,files:files,expr:expr,inputFormat:inputFormat,outputFormat:outputFormat,firstFilename:firstFilename}
	// split exp
	splitStr:=globalCfg.splitExp
	if globalCfg.splitExpFile!=""{
		data,err:=os.ReadFile(globalCfg.splitExpFile); if err!=nil{return nil,err}; splitStr=string(data)
	}
	if splitStr!=""{
		se,err:=parseExpression(splitStr); if err!=nil{return nil,fmt.Errorf("bad split document expression: %s",err.Error())}
		setup.splitExpr=se
	}
	// Inplace pre-check: first file must exist (stat error)
	if globalCfg.inplace{
		if len(files)==0{
			return nil, fmt.Errorf("inplace update requires a file argument")
		}
		if files[0]=="-"{
			// probe original later
			return nil, fmt.Errorf("cannot update stdin in place")
		}
		if _,err:=os.Stat(files[0]); err!=nil{
			return nil, err // os.Stat error is "stat X: no such file or directory" - matches
		}
	}
