func displayFilename(f string)string{ if f==""{return "-"}; return f }

func processExpressionAndFiles(args []string)(string,[]string,error){
	// from-file / expression flag overrides
	if globalCfg.fromFile!=""{
		data,err:=os.ReadFile(globalCfg.fromFile); if err!=nil{return "",nil,err}
		exprStr:=string(data)
		// files = all args, perhaps process stdin addition
		files:=append([]string(nil),args...)
		if len(files)==0 && !globalCfg.nullInput{
			logDebug("missing '-', adding it to the end")
			files=[]string{"-"}
		}
		return exprStr,files,nil
	}
	// Flag --expression: check if it was explicitly set? global value default "" and empty expression flag would be ''. Need cmd flags Changed info not available here - globalCfg from pflag doesn't track. We can infer: if expression flag non-empty OR (we store a sentinel?) For now if expression != "" use it. Edge: --expression '' with files... rare.
	// To detect explicit empty, we could scan os.Args - implement helper.
	if globalCfg.expression!="" || flagWasProvided("expression"){
		files:=append([]string(nil),args...)
		if len(files)==0 && !globalCfg.nullInput{
			logDebug("missing '-', adding it to the end")
			files=[]string{"-"}
		}
		return globalCfg.expression,files,nil
	}
	if len(args)==0{
		var files []string
		if !globalCfg.nullInput{
			logDebug("missing '-', adding it to the end")
			logDebug("processed args: [-]")
			files=[]string{"-"}
		}
		return "",files,nil
	}
	// args >=1
	// Check if first arg is a file or "-" single special handling in processStdInArgs steps logged:
	// Their logic (approx): if missing '-' and stdin is piped etc., add '-' then check first arg is file.
	// We'll implement:
	first:=args[0]
	if first=="-" {
		// treat as file, expression empty, rest are files
		return "", append([]string(nil),args...), nil
	}
	if isFileArg(first){
		logDebug(fmt.Sprintf("processed args: %v", args))
		return "", append([]string(nil),args...), nil
	}
	// expression is first
	logDebug(fmt.Sprintf("assuming expression is '%s'",first))
	files:=append([]string(nil),args[1:]...)
	if len(files)==0 && !globalCfg.nullInput{
		// Add '-' - logs in original order differ, approximate
		// Two checks happen due nested functions; we already logged one check.
		files=[]string{"-"}
	}
	return first,files,nil
}
func flagWasProvided(long string) bool {
	// scan os.Args for --long or --long=...
	for _,a:=range os.Args{ if a=="--"+long || strings.HasPrefix(a,"--"+long+"="){return true} }
	return false
}

func resolveColors() bool {
	if globalCfg.colorsNo{return false}
	if globalCfg.colorsForce{return true}
	if _,present:=os.LookupEnv("NO_COLOR"); present{return false}
	if os.Getenv("TERM")=="dumb"{return false}
	// check if stdout is tty
	fi,err:=os.Stdout.Stat(); if err!=nil{return false}
	if (fi.Mode() & os.ModeCharDevice)!=0{
		// also respect FORCE_COLOR env if set to 0?
		return true
	}
	// FORCE_COLOR env
	if fc:=os.Getenv("FORCE_COLOR"); fc!="" && fc!="0"{return true}
	// CLICOLOR_FORCE
	if os.Getenv("CLICOLOR_FORCE")=="1"{return true}
	return false
}

func evaluateSequence(cmd *cobra.Command,args []string) error {
	setup,err:=setupRun(cmd,args); if err!=nil{return err}
	return runEval(cmd,setup,false)
}
func evaluateAll(cmd *cobra.Command,args []string) error {
	setup,err:=setupRun(cmd,args); if err!=nil{return err}
	return runEval(cmd,setup,true)
