func runEval(cmd *cobra.Command,setup *runSetup, all bool) error {
	// output destination
	var outWriter io.Writer = cmd.OutOrStdout()
	var buf *bytes.Buffer
	if globalCfg.inplace{
		buf=&bytes.Buffer{}; outWriter=buf
		// colors disabled when inplace? output to file shouldn't have colors unless forced? Original probably forces no colors when inplace unless -C. Our resolveColors based on stdout tty - if user runs in terminal with -i, would colour file - likely yq disables. Handle: if inplace and not colorsForce, disable.
		if !globalCfg.colorsForce{globalCfg.colorsEnabled=false}
	}
	printer:=newPrinter(outWriter,setup)
	matched:=false
	// front matter handling stored
	var frontMatterRest string
	var frontMatterMode string = globalCfg.frontMatter
	processBatch:=func(results []*Cand) error {
		if globalCfg.prettyPrint{
			for _,r:=range results{ clearStyles(r.Node) }
		}
		for _,r:=range results{ if !nodeIsFalsey(r.Node){matched=true} }
		return printer.printBatch(results)
	}
	if globalCfg.nullInput{
		docCand:=&Cand{Node:blankNullNode(), Path: []interface{}{}, DocIdx:0, FileIdx:0, Filename:"", Leading:""}
		ctx:=newCtx(); ctx.fallback=[]*Cand{docCand}
		results,err:=setup.expr.Eval(ctx,[]*Cand{docCand}); if err!=nil{return err}
		if err:=processBatch(results); err!=nil{return err}
	} else if all {
		candidates,err:=loadAllCandidates(setup,&frontMatterRest); if err!=nil{return err}
		ctx:=newCtx(); if len(candidates)>0{ctx.fallback=candidates}
		results,err:=setup.expr.Eval(ctx,candidates); if err!=nil{return err}
		if err:=processBatch(results); err!=nil{return err}
	} else {
		// sequential per file per doc
		for fileIdx,filename:=range setup.files{
			docs,err:=loadDocsForFile(setup,filename,fileIdx,&frontMatterRest)
			if err!=nil{
				// If error already is a bad file error, return; printer may have printed previous
				return err
			}
			for _,docCand:=range docs{
				ctx:=newCtx(); ctx.fallback=[]*Cand{docCand}
				results,err:=setup.expr.Eval(ctx,[]*Cand{docCand}); if err!=nil{return err}
				if frontMatterMode=="extract" && fileIdx==0{
					// extract: only print results (yaml content evaluated) - same as normal, rest discarded
				}
				if err:=processBatch(results); err!=nil{return err}
			}
		}
	}
	// front matter process: append rest after (printer already printed yaml with --- wrappers handled in printer? Approach: when frontMatterMode==process, our printer for first file should be wrapped...
	// We implement front matter at printer level? Simpler post-process: if process mode and not inplace/split, we printed YAML content only; now we need to have printed it wrapped with --- and rest. Our loadDocsForFile stripped front matter and stored rest; the yaml docs printed normally without leading ---\n wrapper. Tests for this feature need special handling which we currently don't do correctly.
	// TODO: implement in printer setup: if frontMatter process, output buffer wrapping is handled in newPrinter via prefix/suffix.
	// As a workaround in current structure, printer.printBatch has access to setup and frontMatterRest via printer field set below before batches - but printBatch already ran.
	// For now, if process mode, append separator+rest to output (and if wasn't prefixed, output will be missing initial ---)
	if frontMatterMode=="process" && frontMatterRest!="" && !globalCfg.inplace && setup.splitExpr==nil {
		// front matter output should be: ---\n<printed yaml>---\n<rest>
		// This cannot be fixed post-hoc without buffering. Buffering approach is used when inplace; for stdout we printed directly.
		// We'll handle this by noting printer.frontMatterRest and printer did the wrapping - see printer code where first batch is buffered.
		// To avoid double append, check flag
		if !printer.frontMatterHandled{
			_,_ = io.WriteString(outWriter,"---\n"+frontMatterRest)
		}
	}
	if globalCfg.inplace{
		// link front matter processed output if needed handled in buffer? If frontMatter process, buffer content needs wrap:
		content:=buf.Bytes()
		if frontMatterMode=="process"{
			// Wrap: ---\n + content (ensure ends newline) + ---\n + rest
			var wrapped bytes.Buffer
			wrapped.WriteString("---\n")
			wrapped.Write(content)
			if len(content)>0 && content[len(content)-1]!='\n'{wrapped.WriteString("\n")}
			wrapped.WriteString("---\n")
			wrapped.WriteString(frontMatterRest)
			content=wrapped.Bytes()
		}
		// Write to first file preserving permissions
		fname:=setup.files[0]
		perm:=os.FileMode(0644)
		if fi,err:=os.Stat(fname); err==nil{perm=fi.Mode()}
		// yq writes via temporary file then rename? It preserves original file mode etc.
		tmpfile,err:=os.CreateTemp(filepath.Dir(fname), ".yq-*")
		if err!=nil{
			// fallback direct write
			if err2:=os.WriteFile(fname,content,perm); err2!=nil{return err2}
		} else {
			tmpName:=tmpfile.Name()
			if _,err:=tmpfile.Write(content); err!=nil{tmpfile.Close(); os.Remove(tmpName); return err}
			tmpfile.Close()
			os.Chmod(tmpName,perm)
			if err:=os.Rename(tmpName,fname); err!=nil{ os.Remove(tmpName); return err }
		}
	}
	if globalCfg.exitStatus && !matched{
		return fmt.Errorf("no matches found")
	}
	return nil
}

func clearStyles(n *yaml.Node){
	if n==nil{return}
	n.Style=0
	for _,ch:=range n.Content{clearStyles(ch)}
	if n.Alias!=nil{ /* do not clear alias target repeatedly? Still clear if not visited */ }
}

func loadAllCandidates(setup *runSetup, frontMatterRest *string)([]*Cand,error){
	var all []*Cand
	for fileIdx,filename:=range setup.files{
		docs,err:=loadDocsForFile(setup,filename,fileIdx,frontMatterRest); if err!=nil{return nil,err}
		all=append(all,docs...)
	}
	if len(all)==0{
		all=append(all,&Cand{Node:blankNullNode(),Path:[]interface{}{},Filename:"-"})
	}
	return all,nil
}

func loadDocsForFile(setup *runSetup,filename string,fileIdx int, frontMatterRest *string)([]*Cand,error){
	data,err:=readInputFile(filename)
	if err!=nil{
		// Match original: open error as-is (e.g. "open extraFile.yaml: no such file or directory")
		return nil,err
	}
	// front matter handling for first file only
	if globalCfg.frontMatter!="" && fileIdx==0{
		yamlContent,rest,err:=extractFrontMatter(string(data))
		if err!=nil{
			// not front matter? Original maybe treats whole as yaml? We'll return error
			return nil,err
		}
		*frontMatterRest=rest
		data=[]byte(yamlContent)
	}
	docs,err:=decodeAllDocs(setup.inputFormat,data,filename)
	if err!=nil{
		if err==io.EOF{
			return nil, fmt.Errorf("bad file '%s': EOF",filename)
		}
		// Some decode errors already contain format like hcl parse error which original does NOT wrap with bad file (observed: "Error: hcl parse error: ...")
		msg:=err.Error()
		if strings.HasPrefix(msg,"hcl parse error:"){
			return nil,err
		}
		return nil, fmt.Errorf("bad file '%s': %s",filename,msg)
	}
	var out []*Cand
	for i,d:=range docs{
		out=append(out,&Cand{Node:d.node,Path:[]interface{}{},DocIdx:i,FileIdx:fileIdx,Filename:filename,Leading:d.leading})
	}
	return out,nil
}

func extractFrontMatter(s string)(string,string,error){
	// Expect starting ---\n (maybe \r\n) then yaml then a line ---\n or ...\n terminator
	if !strings.HasPrefix(s,"---\n") && !strings.HasPrefix(s,"---\r\n"){
		return "","",fmt.Errorf("failed to find front matter")
	}
	rest:=s[strings.Index(s,"\n")+1:]
	// find a line that is --- or ...
	lines:=strings.SplitAfter(rest,"\n")
	var yamlLines []string
	for i,line:=range lines{
		trimmed:=strings.TrimSpace(line)
		if trimmed=="---" || trimmed=="..."{
			yamlContent:=strings.Join(yamlLines,"")
			remaining:=strings.Join(lines[i+1:],"")
			return yamlContent,remaining,nil
		}
		yamlLines=append(yamlLines,line)
	}
	return "","",fmt.Errorf("failed to find front matter")
}
