	firstFilename:=""
	if len(files)>0{firstFilename=files[0]}
	// Input format resolution
	inputFormat:=inFmt
	detectedFormat, detectedDisplay:=formatFromFilename(firstFilename)
	if inputFormat=="auto"{
		logDebug(fmt.Sprintf("checking filename '%s' for auto format detection", displayFilename(firstFilename)))
		if firstFilename==""||firstFilename=="-"{
			logDebug("using default inputFormat 'yaml'")
			inputFormat="yaml"
		} else {
			inputFormat=detectedFormat
		}
	}
	// Output format resolution
	outputFormat:=outFmtNorm
	if outputFormat=="auto"{
		userSetInput:=!(globalCfg.inputFormatStr=="auto"||globalCfg.inputFormatStr=="a"||globalCfg.inputFormatStr=="")
		if userSetInput{
			outputFormat="yaml"
			// warn condition
			shouldWarn:=false
			if globalCfg.nullInput{ shouldWarn=true } else if len(files)>0 && files[0]!="-" { shouldWarn=true } else if len(files)==0 { shouldWarn=true }
