func resolveColors() bool {
	if globalCfg.colorsNo{return false}
	if globalCfg.colorsForce{return true}
	if _,present:=os.LookupEnv("NO_COLOR"); present{return false}
	if os.Getenv("TERM")=="dumb"{return false}
	// check if stdout is tty
	fi,err:=os.Stdout.Stat(); if err!=nil{return false}
	if (fi.Mode() & os.ModeCharDevice)!=0{
		// also respect FORCE_COLOR env if set to 0?
		return true
	}
	// FORCE_COLOR env
	if fc:=os.Getenv("FORCE_COLOR"); fc!="" && fc!="0"{return true}
	// CLICOLOR_FORCE
	if os.Getenv("CLICOLOR_FORCE")=="1"{return true}
	return false
