	if strings.HasPrefix(trimmed,"&")||strings.HasPrefix(trimmed,"*"){
		// parse anchor token
		// leading spaces before & are included in anchor color segment " &"
		leadLen:=len(s)-len(strings.TrimLeft(s," "))
		lead:=s[:leadLen]
		rest:=s[leadLen:] // &anc 1...
		// anchor is & + name
		j:=1; for j<len(rest)&&rest[j]!=' '{j++}
		anchorSym:=rest[:1]; anchorName:=rest[1:j]; remainder:=rest[j:]
		res:=col("93",lead+" "+anchorSym) // ??? Overcomplicating
		// Original " &" as one yellow segment then "anc" yellow segment: lead is single space before & returned as space in segment.
		// Our lead already is that space, so col segment should be lead+& (without extra)
		res="\x1b[93m"+lead+anchorSym+"\x1b[0m"+"\x1b[93m"+anchorName+"\x1b[0m"
		if remainder!=""{res+=colorizeValueToken(remainder)}
		return res
	}
	// tag !!str etc: tag not colored, value after space colored without leading space included (observed " !!str " plain, then green "hi")
	if strings.HasPrefix(trimmed,"!!")||strings.HasPrefix(trimmed,"!"){
		// split first space after tag
		leadLen:=len(s)-len(strings.TrimLeft(s," "))
		lead:=s[:leadLen]; rest:=s[leadLen:]
		sp:=strings.Index(rest," "); if sp>=0{ return lead+rest[:sp+1]+colorizeValueToken(strings.TrimLeft(rest[sp+1:]," "))}
		return s
	}
	// flow collections: color elements inside [] {} recursively-lite
	if strings.HasPrefix(trimmed,"[")||strings.HasPrefix(trimmed,"{"){
		return colorizeFlow(s)
	}
	// null
	if trimmed=="null"||trimmed=="~"||trimmed==""{
		return s
	}
	// Determine type guess
	if isQuoted(trimmed){ return col("32",s) }
	if trimmed=="true"||trimmed=="false"{return col("95",s)}
	if _,ok:=parseNumberValue(trimmed); ok {return col("95",s)}
	// plain string
	return col("32",s)
}
func isQuoted(s string) bool { return (strings.HasPrefix(s,"\"")&&strings.HasSuffix(s,"\""))||(strings.HasPrefix(s,"'")&&strings.HasSuffix(s,"'")) }
func colorizeFlow(s string) string {
	// token by token simple: brackets not colored, commas not, scalars colored with preceding space included for elements after comma/open
	// Original for [1, x]: "["
	// We'll reconstruct preserving characters and color scalar tokens between delimiters []{},:
	var out strings.Builder
	i:=0
	for i<len(s){
		c:=s[i]
		if strings.ContainsRune("[]{},:",rune(c)){ out.WriteByte(c); i++; continue }
		// collect token until delimiter (including leading spaces)
		j:=i; for j<len(s)&&!strings.ContainsRune("[]{},:",rune(s[j])){j++}
		tok:=s[i:j]
		if strings.TrimSpace(tok)==""{out.WriteString(tok)}else{
			// check if this token is a key (next non-space is colon) inside flow map
			isKey:=false; if j<len(s)&&s[j]==':' {isKey=true}
			if isKey{ out.WriteString(col("36",tok)) } else { out.WriteString(colorizeValueToken(tok)) }
		}
		i=j
	}
	return out.String()
}
func colorizeJSON(s string, node *yaml.Node) string {
	// Reuse line colorizer adapted: JSON lines keys are quoted, values similarly, braces get leftover artifacts in original - clean approx
	lines:=strings.SplitAfter(s,"\n")
	var out strings.Builder
	for _,line:=range lines{
		if line==""{continue}
		content:=strings.TrimSuffix(line,"\n")
		out.WriteString(colorizeJSONLine(content))
		out.WriteString("\n")
	}
	return out.String()
}
func colorizeJSONLine(line string) string {
	// braces alone uncolored
	trimmed:=strings.TrimSpace(line)
	if trimmed=="{"||trimmed=="}"||trimmed=="["||trimmed=="]"||trimmed=="},"||trimmed=="],"{
		return line
	}
	// key: value
	colon:=strings.Index(line,":")
	if colon>0{
		before:=line[:colon]; after:=line[colon+1:]
		// before includes indent + quoted key
		trimmedAfter:=strings.TrimRight(after,",")
		hasComma:=strings.HasSuffix(after,",")
		res:=col("36",before)+":"+colorizeValueToken(trimmedAfter)
		if hasComma{res+=","}
		return res
	}
	// array element value
	hasComma:=strings.HasSuffix(line,",")
	core:=strings.TrimSuffix(line,",")
	res:=colorizeValueToken(core)
	if hasComma{res+=","}
	return res
}
EOF
