			trimmed:=strings.TrimSuffix(s,"\n")
			if strings.Contains(trimmed,"\x00") && globalCfg.unwrapScalar {
				return fmt.Errorf("unwrapped scalar contains NUL character")
			}
			_,err:=io.WriteString(p.w,trimmed+"\x00"); return err
		}
		_,err:=io.WriteString(p.w,s); return err
	}
