			s=colorizeYAML(s,node)
		} else if globalCfg.colorsEnabled && globalCfg.colorsForce{
			s=colorizeYAML(s,node)
		}
		return writeOut(s)
	case "json":
		s,err:=encodeJSON(node,globalCfg.indent); if err!=nil{return err}
		if globalCfg.colorsEnabled{ s=colorizeJSON(s,node) }
		return writeOut(s)
	case "props":
		// Scalar root: original with -o props on scalar? props encoder flatten gives just value line. But if node is scalar and unwrap? -o props .a on 1 gives "1"? Probe later.
		s,err:=encodeProps(node); if err!=nil{return err}
		return writeOut(s)
