		sep:=rune(globalCfg.csvSeparator); if format=="tsv"{sep='\t'}
		s,err:=encodeCSV(node,sep); if err!=nil{return err}
		return writeOut(s)
	case "xml":
		s,err:=encodeXMLRoot(node,globalCfg.indent,false); if err!=nil{return err}
		return writeOut(s)
	case "toml":
		s,err:=encodeTOML(node); if err!=nil{return err}
		return writeOut(s)
	case "ini":
		s,err:=encodeINI(node); if err!=nil{return err}
		return writeOut(s)
	case "lua":
		s,err:=encodeLua(node); if err!=nil{return err}
		return writeOut(s)
	case "shell":
		s,err:=encodeShell(node); if err!=nil{return err}
		return writeOut(s)
	case "hcl":
		s,err:=encodeHCL(node); if err!=nil{return err}
		return writeOut(s)
	case "base64":
		s,err:=encodeNodeToString(node,"base64",0); if err!=nil{return err}
		// base64 output has no trailing newline in probe (.a)
		if globalCfg.nulOutput{return writeOut(s)}
		_,err=io.WriteString(p.w,s); return err
	case "uri":
		s,err:=encodeNodeToString(node,"uri",0); if err!=nil{return err}
		if globalCfg.nulOutput{return writeOut(s)}
		_,err=io.WriteString(p.w,s); return err
	}
	// fallback yaml
	s,err:=encodeYAML(node,globalCfg.indent,false); if err!=nil{return err}; return writeOut(s)
}
