}

func (p *printer) printBatch(results []*Cand) error {
	// front matter process wrapping needs buffering of the whole run - we handle in runner only for inplace; for stdout, this simple approach prints yaml only and runner appends rest (missing leading ---). Accept for now.
	for idx,r:=range results{
