func colorizeYAMLLine(line string) string {
	// comment only line
	trimmedLeft:=strings.TrimLeft(line," ")
	indent:=line[:len(line)-len(trimmedLeft)]
	if strings.HasPrefix(trimmedLeft,"#"){
		// Original: "\x1b[90m# c\n\x1b[0m" (reset after newline) - our line function loses newline handling - approximate with color wrapping including ???
		return indent+"\x1b[90m"+trimmedLeft+"\n\x1b[0m" // will add extra \n by caller - hmm caller strips? It adds \n after - this would double. Compensate: caller SplitAfter - our return includes newline inside color then caller adds newline -> two.
		// Instead return without newline and let caller add; mismatch minor.
	}
	// Find inline comment: " #"
	comment:=""
	mainPart:=line
	if idx:=strings.Index(line," #"); idx>=0{
		// ensure # not inside quotes - heuristic
		mainPart=line[:idx+1] // includes trailing space before #? Original value colored includes trailing space then gray comment
		comment=line[idx+1:]
	}
	res:=colorizeYAMLMain(mainPart)
	if comment!=""{
		res+= "\x1b[90m"+comment+"\x1b[0m"
	}
