package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

func lineColOf(data []byte, idx int) (int,int){
	line:=1; col:=1
	for i:=0;i<idx && i<len(data);i++{ if data[i]=='\n'{line++; col=1}else{col++} }
	return line,col
}
func lineText(data []byte, line int) string {
	lines:=strings.Split(string(data),"\n"); if line>=1&&line<=len(lines){return lines[line-1]}; return ""
}
func adjustYAMLErrorWithData(err error, data []byte) error {
	msg:=err.Error()
	if !strings.HasPrefix(msg,"yaml: "){return err}
	rest:=strings.TrimPrefix(msg,"yaml: ")
	line:=0
	reLine:=regexp.MustCompile(`^line (\d+): `)
	if m:=reLine.FindStringSubmatch(rest); m!=nil{ line,_=strconv.Atoi(m[1]); rest=rest[len(m[0]):] }
	switch rest{
	case "found incompatible YAML document":
		return fmt.Errorf("yaml: <unknown position>: found incompatible YAML document")
	case "mapping values are not allowed in this context":
		lt:=lineText(data,line); col:=strings.Index(lt,":")+1; if col<=0{col=1}
		return fmt.Errorf("yaml: line %d, column %d: mapping values are not allowed in this context",line,col)
	case "found character that cannot start any token":
		l:=line; if l==0{ idx:=strings.Index(string(data),"\t"); if idx>=0{l,_=lineColOf(data,idx)}else{l=1} }
		return fmt.Errorf("yaml: while scanning for the next token at line %d: found character that cannot start any token",l)
	case "found unexpected end of stream":
		// find first quote
		s:=string(data); idx:=strings.IndexAny(s,"\"'"); l,c:=1,1; if idx>=0{l,c=lineColOf(data,idx)}
		innerLine:=line; if innerLine==0{innerLine=l}
		return fmt.Errorf("yaml: while scanning a quoted scalar at line %d, column %d: line %d: found unexpected end of stream",l,c,innerLine)
	case "found unknown escape character":
		s:=string(data); qi:=strings.IndexAny(s,"\"'"); l,c:=1,1; if qi>=0{l,c=lineColOf(data,qi)}
		bi:=strings.Index(s,"\\"); pl,pc:=l,c; if bi>=0{pl,pc=lineColOf(data,bi)}
		return fmt.Errorf("yaml: while scanning a quoted scalar at line %d, column %d: line %d, column %d: found unknown escape character",l,c,pl,pc)
	case "did not find expected hexdecimal number":
		s:=string(data); qi:=strings.IndexAny(s,"\"'"); l,c:=1,1; if qi>=0{l,c=lineColOf(data,qi)}
		// find \u or \x or \U
		re:=regexp.MustCompile(`\\[uxU]`)
		loc:=re.FindStringIndex(s); pl,pc:=l,c
		if loc!=nil{
			need:=4; if s[loc[0]+1]=='x'{need=2}; if s[loc[0]+1]=='U'{need=8}
			j:=loc[0]+2; cnt:=0; for j<len(s)&&cnt<need&&isHex(s[j]){j++;cnt++}
			pl,pc=lineColOf(data,j)
		}
		return fmt.Errorf("yaml: while scanning a quoted scalar at line %d, column %d: line %d, column %d: did not find expected hexadecimal number",l,c,pl,pc)
	case "found unknown directive name":
		lines:=strings.Split(string(data),"\n"); l:=1; col:=1
		for i,ln:=range lines{ if strings.HasPrefix(ln,"%"){ l=i+1; // column after directive word
			wordEnd:=strings.IndexAny(ln," \t"); if wordEnd<0{col=len(ln)+1}else{col=wordEnd+1}; break } }
		return fmt.Errorf("yaml: while scanning a directive at line %d: line %d, column %d: found unknown directive name",l,l,col)
	case "could not find expected ':'":
		l:=line; if l==0{l=1}
		return fmt.Errorf("yaml: while scanning a simple key at line %d: line %d: could not find expected ':'",l,l+1)
	case "did not find expected ',' or ']'":
		pos:=contextPosForOpening(data,'[')
		return fmt.Errorf("yaml: while parsing a flow sequence at %s: line %d: did not find expected ',' or ']'",pos,line)
	case "did not find expected ',' or '}'":
		pos:=contextPosForOpening(data,'{')
		return fmt.Errorf("yaml: while parsing a flow mapping at %s: line %d: did not find expected ',' or '}'",pos,line)
	case "did not find expected node content":
		// flow if there's an unclosed [ or { before end / anywhere on relevant line
		isFlow:=false; openLine:=0
		// find last [ or { that is unclosed crude: if data contains [ or { and error line is at or after it
		s:=string(data)
		for _,ch:=range []byte{'[','{'}{
			if idx:=strings.IndexByte(s,ch); idx>=0{ isFlow=true; openLine,_=lineColOf(data,idx); break }
		}
		// But block cases like "a: [}"] is flow, "..." no flow chars -> block. "{a: [}]" flow.
		// If document is like "a: [1,,2]" flow though closed in text, still flow node.
		if isFlow{
			pos:="<unknown position>"; if openLine>1{pos=fmt.Sprintf("line %d",openLine)}
			// inner has line only if original line present and pos unknown? Original examples: line present in v3 for second doc ([ at line3) -> inner no line; for [1,,2] v3 no line -> inner no line.
			return fmt.Errorf("yaml: while parsing a flow node at %s: did not find expected node content",pos)
