		if line>1{pos=fmt.Sprintf("line %d",line)}
		return fmt.Errorf("yaml: while parsing a block node at %s: did not find expected node content",pos)
	case "did not find expected key":
		// block mapping context unknown if starts line1
		inner:="did not find expected key"
		trimmed:=strings.TrimSpace(string(data))
		if !strings.HasPrefix(trimmed,":") {
			inner="<unknown position>: did not find expected key"
		}
		return fmt.Errorf("yaml: while parsing a block mapping at <unknown position>: %s",inner)
	case "did not find expected tag URI":
		s:=string(data); idx:=strings.Index(s,"!<"); l,c:=1,1; pl,pc:=1,1
		if idx>=0{ l,c=lineColOf(data,idx); // problem at first char that isn't URI char - '>' or space after <
			j:=idx+2; for j<len(s)&&s[j]!='>'&&s[j]!=' '&&s[j]!='\t'&&s[j]!='\n'{j++}; pl,pc=lineColOf(data,j)
		} else if idx2:=strings.Index(s,"!"); idx2>=0{ l,c=lineColOf(data,idx2); pl,pc=l,c }
		return fmt.Errorf("yaml: while parsing a tag at line %d, column %d: line %d, column %d: did not find expected tag URI",l,c,pl,pc)
	}
	// unknown anchor
	if strings.HasPrefix(rest,"unknown anchor '"){
		re:=regexp.MustCompile(`unknown anchor '([^']+)' referenced`)
		if m:=re.FindStringSubmatch(rest); m!=nil{
			name:=m[1]; idx:=strings.Index(string(data),"*"+name); l,c:=1,1; if idx>=0{l,c=lineColOf(data,idx+1)}
			return fmt.Errorf("yaml: line %d, column %d: unknown anchor '%s' referenced",l,c,name)
		}
	}
	return err
}
func contextPosForOpening(data []byte, ch byte) string {
	idx:=strings.IndexByte(string(data),ch); if idx<0{return "<unknown position>"}
	l,_:=lineColOf(data,idx); if l<=1{return "<unknown position>"}; return fmt.Sprintf("line %d",l)
}
