import subprocess,os,tempfile,pathlib,re
ORIG=os.path.abspath("./executable");OURS="/tmp/ours"
def run(bin,setup,args):
 with tempfile.TemporaryDirectory() as td:
  setup(td)
  p=subprocess.run([bin]+args,input=b"",capture_output=True,cwd=td)
  files={}
  for path in pathlib.Path(td).rglob("*"):
   rel=str(path.relative_to(td))
   if path.is_symlink():files[rel]=("link",os.readlink(path))
   elif path.is_file():files[rel]=("file",oct(path.stat().st_mode),path.read_bytes())
   elif path.is_dir():files[rel]=("dir",)
  return p.returncode,p.stdout,re.sub(rb'time=[^ ]+',b'time=T',p.stderr),files
def s_dir(td): pathlib.Path(td,"dir").mkdir()
def s_perm(td):
 p=pathlib.Path(td,"f.yaml");p.write_text("a: 1\n");p.chmod(0o640)
def s_link(td):
 pathlib.Path(td,"real.yaml").write_text("a: 1\n");os.symlink("real.yaml",pathlib.Path(td,"link.yaml"))
def s_ro(td):
 p=pathlib.Path(td,"f.yaml");p.write_text("a: 1\n");p.chmod(0o444)
cases=[([".","dir"],s_dir),(["-i",".a=2","f.yaml"],s_perm),(["-i",".a=2","link.yaml"],s_link),(["-i",".a=2","f.yaml"],s_ro),([".","f.yaml"],s_perm),(["-i",".a=2","dir"],s_dir)]
for i,(args,setup) in enumerate(cases):
 r1=run(ORIG,setup,args);r2=run(OURS,setup,args)
 if r1!=r2:print(i,args);print(" O",r1);print(" U",r2)
print("done")
PY
